INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4e1637f-77c1-4939-814f-16a060e7658a', '江行無題一百首 五十二', '江行無題一百首 五十二', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["岸綠野煙遠，江紅斜照微。","撐開小漁艇，應到月明歸。"]', '["岸綠野煙远，江紅斜照微。","撐开小漁艇，應到月明归。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十二 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df62d1c9-611b-4a9b-bb73-4d2ecd7a2de7', '江行無題一百首 五十三', '江行無題一百首 五十三', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["雨餘江始漲，漾漾見流薪。","曾歎河中木，斯言憶古人。"]', '["雨餘江始漲，漾漾见流薪。","曾歎河中木，斯言憶古人。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十三 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('348fbc99-c047-4510-9cc3-c8067423c804', '江行無題一百首 五十四', '江行無題一百首 五十四', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["葉舟維夏口，煙野獨行時。","不見頭陀寺，空懷幼婦碑。"]', '["葉舟維夏口，煙野独行时。","不见头陀寺，空懷幼婦碑。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十四 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d3a6835-caa8-45c1-9873-0e2a2ad3406f', '江行無題一百首 五十五', '江行無題一百首 五十五', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["晚泊武昌岸，津亭疎柳風。","數株曾手植，好事憶陶公。"]', '["晚泊武昌岸，津亭疎柳风。","數株曾手植，好事憶陶公。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十五 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f72f4b11-6788-4e6f-8459-1a3fad13d4a9', '江行無題一百首 五十六', '江行無題一百首 五十六', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["墜露曉猶濃，秋花不易逢。","涉江雖已晚，高樹搴芙蓉。"]', '["墜露晓猶濃，秋花不易逢。","涉江雖已晚，高樹搴芙蓉。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十六 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6731314-59b8-44f9-b3bb-bdb29dec16d7', '江行無題一百首 五十七', '江行無題一百首 五十七', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["舟航依浦定，星斗滿江寒。","若比陰霾日，何妨夜未闌。"]', '["舟航依浦定，星斗满江寒。","若比陰霾日，何妨夜未闌。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十七 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e33620c-bf93-45e7-b799-f01ffa5f2288', '江行無題一百首 五十八', '江行無題一百首 五十八', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["近戍離金落，孤岑望火門。","唯將知命意，瀟灑向乾坤。"]', '["近戍離金落，孤岑望火门。","唯將知命意，瀟灑向乾坤。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十八 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fafa242-2cc4-40da-a37a-00dce75c22f0', '江行無題一百首 五十九', '江行無題一百首 五十九', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["叢菊生堤上，此花長後時。","有人還採掇，何必在春期。"]', '["叢菊生堤上，此花长後时。","有人還採掇，何必在春期。"]', '诗', 'shi', '', NULL, '江行無題一百首 五十九 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e131a01d-e149-44b7-8f97-fa93420d46e6', '江行無題一百首 六十', '江行無題一百首 六十', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["夕景殘霞落，秋寒細雨晴。","短纓何用濯，舟在月中行。"]', '["夕景殘霞落，秋寒細雨晴。","短纓何用濯，舟在月中行。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be9a4dde-30fd-4ab0-9fb0-0c0955b1622a', '江行無題一百首 六十一', '江行無題一百首 六十一', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["堤壞漏江水，地坳成野塘。","晚荷人不折，留取作秋香。"]', '["堤壞漏江水，地坳成野塘。","晚荷人不折，留取作秋香。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十一 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8ef9ce9-fad2-486e-8eb6-96511a84631b', '江行無題一百首 六十二', '江行無題一百首 六十二', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["左宦終何路，攄懷亦自寬。","襞牋嘲白鷺，無意喻梟鸞。"]', '["左宦終何路，攄懷亦自寬。","襞牋嘲白鷺，無意喻梟鸾。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十二 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72a08eb7-6097-4134-909d-c528366d8939', '江行無題一百首 六十三', '江行無題一百首 六十三', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["樓空人不歸，雲似去時衣。","黃鶴無心下，長應笑令威。"]', '["楼空人不归，云似去时衣。","黄鹤無心下，长應笑令威。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十三 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98553acc-8158-4b44-bba4-4b793afbfbe5', '江行無題一百首 六十四', '江行無題一百首 六十四', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["白帝朝驚浪，潯陽暮暎雲。","等閑生險易，世路秖如君。"]', '["白帝朝驚浪，潯陽暮暎云。","等闲生險易，世路秖如君。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十四 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc0f8809-e809-47b5-bf87-93d08ac28d50', '江行無題一百首 六十五', '江行無題一百首 六十五', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["櫓慢開輕浪，帆虛帶白雲。","客船雖狹小，容得庾將軍。"]', '["櫓慢开轻浪，帆虛带白云。","客船雖狹小，容得庾將軍。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十五 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63a4cbf8-8db3-46a4-ab49-ffd90776ba32', '江行無題一百首 六十六', '江行無題一百首 六十六', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["風雨正甘寢，雲霓忽晚晴。","放歌雖自遣，一歲又崢嶸。"]', '["风雨正甘寢，云霓忽晚晴。","放歌雖自遣，一歲又崢嶸。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十六 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7190d9c3-dc2e-45f7-9afe-3e7cad21dd36', '江行無題一百首 六十七', '江行無題一百首 六十七', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["靜看秋江水，風微浪漸平。","人間馳競處，塵土自波成。"]', '["静看秋江水，风微浪漸平。","人间驰競处，塵土自波成。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十七 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da1e4b47-8cfb-4fd3-9fad-61dd9304bd29', '江行無題一百首 六十八', '江行無題一百首 六十八', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["風勁帆方疾，風回櫂却遲。","較量人世事，不校一毫釐。"]', '["风勁帆方疾，风回櫂却遲。","較量人世事，不校一毫釐。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十八 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dcde895-c371-410d-b870-0ee3f99b0c86', '江行無題一百首 六十九', '江行無題一百首 六十九', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["咫尺愁風雨，匡廬不可登。","秖疑雲霧窟，猶有六朝僧。"]', '["咫尺愁风雨，匡廬不可登。","秖疑云霧窟，猶有六朝僧。"]', '诗', 'shi', '', NULL, '江行無題一百首 六十九 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22d5ec8b-4f39-4a81-b769-0b5a7a7f336e', '江行無題一百首 七十', '江行無題一百首 七十', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["幽思正遲遲，沙邊濯弄時。","自憐非博物，猶未識鳧葵。"]', '["幽思正遲遲，沙邊濯弄时。","自怜非博物，猶未識鳧葵。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22a798b3-a39a-4936-8066-7de3068d3f6b', '江行無題一百首 七十一', '江行無題一百首 七十一', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["曾有煙波客，能歌西塞山。","落帆唯待月，一釣紫菱灣。"]', '["曾有煙波客，能歌西塞山。","落帆唯待月，一釣紫菱灣。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十一 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('455630f7-af7d-4ce2-a2d1-fcca3274fed7', '江行無題一百首 七十二', '江行無題一百首 七十二', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["千頃水紋細，一拳嵐影孤。","君山寒樹綠，曾過洞庭湖。"]', '["千頃水紋細，一拳嵐影孤。","君山寒樹綠，曾過洞庭湖。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十二 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86dd5754-3960-4be4-b26a-4f7b2f4ea20d', '江行無題一百首 七十三', '江行無題一百首 七十三', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["光闊重湖水，低斜遠雁行。","未曾無興詠，多謝沈東陽。"]', '["光闊重湖水，低斜远雁行。","未曾無兴詠，多謝沈东陽。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十三 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca289f6b-ff7d-4b55-9459-ba8a2e516835', '江行無題一百首 七十四', '江行無題一百首 七十四', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["晚菊繞江壘，忽如開古屏。","莫言時節過，白日有餘馨。"]', '["晚菊繞江壘，忽如开古屏。","莫言时節過，白日有餘馨。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十四 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba042478-1814-4fcb-aa06-c72ab4e7fe72', '江行無題一百首 七十五', '江行無題一百首 七十五', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["秋寒鷹隼健，逐雀下雲空。","知是江湖闊，無心擊塞鴻。"]', '["秋寒鷹隼健，逐雀下云空。","知是江湖闊，無心擊塞鴻。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十五 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3182c836-007b-4cb8-9dc2-3e09463390a5', '江行無題一百首 七十六', '江行無題一百首 七十六', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["日落長亭晚，山門步障青。","可憐無酒分，處處有旗亭。"]', '["日落长亭晚，山门步障青。","可怜無酒分，处处有旗亭。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十六 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e5f39c5-8b87-4b9a-b41b-c774bcf5c107', '江行無題一百首 七十七', '江行無題一百首 七十七', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["江草何多思，冬青尚滿洲。","誰能驚鵩鳥，作賦爲沙鷗。"]', '["江草何多思，冬青尚满洲。","誰能驚鵩鸟，作賦爲沙鷗。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十七 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('253fd2bb-cb59-4abd-a729-7ee497940a3f', '江行無題一百首 七十八', '江行無題一百首 七十八', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["遠岸無行樹，經霜有半紅。","停船搜好句，題葉贈江楓。"]', '["远岸無行樹，經霜有半紅。","停船搜好句，題葉贈江楓。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十八 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecec07dc-9a38-48ac-8454-7124346a047c', '江行無題一百首 七十九', '江行無題一百首 七十九', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["身世比行舟，無風亦暫休。","敢言終破浪，唯願穩乘流。"]', '["身世比行舟，無风亦暫休。","敢言終破浪，唯願穩乘流。"]', '诗', 'shi', '', NULL, '江行無題一百首 七十九 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5087b097-5cff-459b-9c86-70b6f858425a', '江行無題一百首 八十', '江行無題一百首 八十', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["數畝蒼苔石，煙濛鶴卵洲。","定因詞客遇，名字始風流。"]', '["數畝蒼苔石，煙濛鹤卵洲。","定因词客遇，名字始风流。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d044a64a-26c5-4bec-9c1f-79570e41a0d9', '江行無題一百首 八十一', '江行無題一百首 八十一', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["興閑停桂楫，路好過松門。","不負佳山水，還開酒一尊。"]', '["兴闲停桂楫，路好過松门。","不負佳山水，還开酒一尊。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十一 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a20d7657-10ef-4fa2-ad3d-50987eea10a9', '江行無題一百首 八十二', '江行無題一百首 八十二', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["幽懷念煙水，長恨隔龍沙。","今日膝王閣，分明見落霞。"]', '["幽懷念煙水，长恨隔龙沙。","今日膝王閣，分明见落霞。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十二 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31c7fc3b-d002-40a1-aad0-c39183066fe5', '江行無題一百首 八十三', '江行無題一百首 八十三', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["短楫休敲桂，孤根自駐萍。","自憐非劒氣，空向斗牛星。"]', '["短楫休敲桂，孤根自駐萍。","自怜非劒氣，空向斗牛星。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十三 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6af7442b-0e6f-44d9-883c-dd5b3c5e126c', '江行無題一百首 八十四', '江行無題一百首 八十四', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["江流何渺渺，懷古獨依依。","漁父非賢者，蘆中但有磯。"]', '["江流何渺渺，懷古独依依。","漁父非賢者，蘆中但有磯。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十四 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a641d29c-670e-4ecb-9c68-703f7159bb79', '江行無題一百首 八十五', '江行無題一百首 八十五', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["高浪如銀屋，江風一發時。","筆端降太白，才大語終奇。"]', '["高浪如銀屋，江风一發时。","笔端降太白，才大語終奇。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十五 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd692bf4-7d92-4c73-a316-89fd80100c66', '江行無題一百首 八十六', '江行無題一百首 八十六', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["細竹漁家路，晴陽看結繒。","喜來邀客坐，分與折腰菱。"]', '["細竹漁家路，晴陽看結繒。","喜来邀客坐，分與折腰菱。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十六 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('339d2c0a-8297-464b-b37c-4755924c0a56', '江行無題一百首 八十七', '江行無題一百首 八十七', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["幸有煙波興，寧辭筆硯勞。","緣情無怨刺，却似反離騷。"]', '["幸有煙波兴，寧辞笔硯勞。","緣情無怨刺，却似反離騷。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十七 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85ae906f-5c82-4dd0-989d-233257f5ae6a', '江行無題一百首 八十八', '江行無題一百首 八十八', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["平湖五百里，江水想通波。","不奈扁舟去，其如決計何。"]', '["平湖五百里，江水想通波。","不奈扁舟去，其如決計何。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十八 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5123ca9-2423-4dba-a90a-dfcd3c2b6da5', '江行無題一百首 八十九', '江行無題一百首 八十九', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["數峯雲斷處，去岸暎高山。","身到韋江日，猶應未得閑。"]', '["數峯云斷处，去岸暎高山。","身到韋江日，猶應未得闲。"]', '诗', 'shi', '', NULL, '江行無題一百首 八十九 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f9e107a-aced-4b09-927b-bf1493e64921', '江行無題一百首 九十', '江行無題一百首 九十', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["一灣斜照水，三版順風船。","未敢相邀約，勞生秖自憐。"]', '["一灣斜照水，三版順风船。","未敢相邀約，勞生秖自怜。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2046e3de-19c0-4737-9f42-e24c6c114991', '江行無題一百首 九十一', '江行無題一百首 九十一', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["江雨正霏微，江村晚渡稀。","何曾妨釣艇，更待得魚歸。"]', '["江雨正霏微，江村晚渡稀。","何曾妨釣艇，更待得鱼归。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十一 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52804721-9e5c-4cd5-a58a-c47a491dcc85', '江行無題一百首 九十二', '江行無題一百首 九十二', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["沙上獨行時，高吟到楚詞。","難將垂岸蓼，盈把當江蘺。"]', '["沙上独行时，高吟到楚词。","难將垂岸蓼，盈把當江蘺。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十二 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d3c4f0d-bf0c-491d-9a12-aa58789ffcf3', '江行無題一百首 九十三', '江行無題一百首 九十三', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["新野舊樓名，潯陽勝賞情。","照人長一色，江月共淒清。"]', '["新野旧楼名，潯陽勝賞情。","照人长一色，江月共淒清。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十三 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a081071-eb67-404c-84a6-9f48a44520eb', '江行無題一百首 九十四', '江行無題一百首 九十四', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["願飲西江水，那吟北渚愁。","莫敎留滯跡，遠比蔡昭侯。"]', '["願饮西江水，那吟北渚愁。","莫敎留滯跡，远比蔡昭侯。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十四 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9c591e2-fb02-4826-b151-9f41ff835970', '江行無題一百首 九十五', '江行無題一百首 九十五', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["湖口分江水，東流獨有情。","當時好風物，誰伴謝宣城。"]', '["湖口分江水，东流独有情。","當时好风物，誰伴謝宣城。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十五 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c080f84-6840-4b71-a73c-f22d4b02c153', '江行無題一百首 九十六', '江行無題一百首 九十六', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["潯陽江畔菊，應似古來秋。","爲問幽棲客，吟時得酒不。"]', '["潯陽江畔菊，應似古来秋。","爲问幽棲客，吟时得酒不。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十六 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79757dc2-3afd-45bf-9998-465bd4aea1cb', '江行無題一百首 九十七', '江行無題一百首 九十七', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["高峯有佳號，千尺倚寒松。","若使鑪煙在，猶應爲上公。"]', '["高峯有佳號，千尺倚寒松。","若使鑪煙在，猶應爲上公。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十七 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28edc830-20a8-42d9-bfbf-d1480e3d8b7b', '江行無題一百首 九十八', '江行無題一百首 九十八', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["萬木已清霜，江邊村事忙。","故溪黃稻熟，一夜夢中香。"]', '["万木已清霜，江邊村事忙。","故溪黄稻熟，一夜梦中香。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十八 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65baec29-200b-4e33-9fde-aa80e3828fba', '江行無題一百首 九十九', '江行無題一百首 九十九', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["楚水苦縈迴，征帆落又開。","可緣非直路，却有好風來。"]', '["楚水苦縈迴，征帆落又开。","可緣非直路，却有好风来。"]', '诗', 'shi', '', NULL, '江行無題一百首 九十九 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('580221e9-8b31-406a-b280-dcd513ac7362', '江行無題一百首 一百', '江行無題一百首 一百', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["遠謫歲時晏，暮江風雨寒。","仍愁繫舟處，驚夢近長灘。"]', '["远謫歲时晏，暮江风雨寒。","仍愁繫舟处，驚梦近长灘。"]', '诗', 'shi', '', NULL, '江行無題一百首 一百 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10c7bd29-22f7-407c-bd5e-0253598689d5', '言懷', '言懷', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["夜月霽未好，雲泉堪夢歸。","如何建章漏，催著早朝衣。"]', '["夜月霽未好，云泉堪梦归。","如何建章漏，催著早朝衣。"]', '诗', 'shi', '', NULL, '言懷 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8210485-a1f4-4c76-a1f6-2f5e57d39d29', '和張僕射塞下曲', '和張僕射塞下曲', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["月黑雁飛高，單于夜遁逃。","欲將輕騎逐，大雪滿弓刀。"]', '["月黑雁飞高，單于夜遁逃。","欲將轻騎逐，大雪满弓刀。"]', '诗', 'shi', '', NULL, '和張僕射塞下曲 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8697e254-8a73-4e3e-b485-caf95c32e466', '送李明府去官', '送李明府去官', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["謗言三至後，直道歎何如。","今日藍溪水，無人不夜魚。"]', '["謗言三至後，直道歎何如。","今日藍溪水，無人不夜鱼。"]', '诗', 'shi', '', NULL, '送李明府去官 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc239060-b916-4be2-8c12-84635b56b26b', '赴章陵詶李卿贈別', '赴章陵詶李卿贈別', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["一官叨下秩，九棘謝知音。","芳草文園路，春愁滿別心。"]', '["一官叨下秩，九棘謝知音。","芳草文园路，春愁满別心。"]', '诗', 'shi', '', NULL, '赴章陵詶李卿贈別 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f453e0ad-09b1-4877-af85-1c38a42456e1', '逢俠者', '逢俠者', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["燕趙悲歌士，相逢劇孟家。","寸心言不盡，前路日將斜。"]', '["燕趙悲歌士，相逢劇孟家。","寸心言不尽，前路日將斜。"]', '诗', 'shi', '', NULL, '逢俠者 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fcfa6f8-6cd9-49fd-b727-d1652b676310', '郎員外見尋不遇', '郎員外见尋不遇', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["軒騎來相訪，漁樵悔晚歸。","更憐垂露跡，花裏點牆衣。"]', '["軒騎来相訪，漁樵悔晚归。","更怜垂露跡，花裏点牆衣。"]', '诗', 'shi', '', NULL, '郎員外見尋不遇 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b52a9754-58e2-4148-a1c0-9b750317ea0d', '過李侍御宅', '過李侍御宅', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["不見承明客，愁聞長樂鐘。","馬卿何早世，漢主欲登封。"]', '["不见承明客，愁闻长乐鐘。","马卿何早世，漢主欲登封。"]', '诗', 'shi', '', NULL, '過李侍御宅 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98082caf-de2a-4836-8990-24273b55de1c', '宿洞口館', '宿洞口館', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["野竹通溪冷，秋泉入戶鳴。","亂來人不到，芳草上堦生。"]', '["野竹通溪冷，秋泉入戶鳴。","亂来人不到，芳草上堦生。"]', '诗', 'shi', '', NULL, '宿洞口館 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3e8284c-313e-4635-8519-4f2f929d163c', '九日寄姪箊箕等', '九日寄姪箊箕等', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["采菊偏相憶，傳香寄便風。","今朝竹林下，莫使桂尊空。"]', '["采菊偏相憶，傳香寄便风。","今朝竹林下，莫使桂尊空。"]', '诗', 'shi', '', NULL, '九日寄姪箊箕等 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e00cf508-6def-4daf-8e9b-71fce922a6f9', '梨花', '梨花', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["豔靜如籠月，香寒未逐風。","桃花徒照地，終被笑妖紅。"]', '["豔静如籠月，香寒未逐风。","桃花徒照地，終被笑妖紅。"]', '诗', 'shi', '', NULL, '梨花 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07307446-f121-4be3-a68f-2146773a1091', '題崔逸人山亭', '題崔逸人山亭', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["藥徑深紅蘚，山窗滿翠微。","羨君花下酒，蝴蝶夢中飛。"]', '["藥徑深紅蘚，山窗满翠微。","羨君花下酒，蝴蝶梦中飞。"]', '诗', 'shi', '', NULL, '題崔逸人山亭 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b24f6be9-2176-458b-8870-ee6ec54d1397', '藍田溪雜詠二十二首 登臺', '藍田溪杂詠二十二首 登台', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["望山登春臺，目盡趣難極。","晚景下平阡，花際霞峯色。"]', '["望山登春台，目尽趣难極。","晚景下平阡，花際霞峯色。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 登臺 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c088869-d8a1-448d-a880-b2c7a92977fc', '藍田溪雜詠二十二首 板橋', '藍田溪杂詠二十二首 板橋', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["靜宜樵隱度，遠與車馬隔。","有時行藥來，喜遇歸山客。"]', '["静宜樵隐度，远與车马隔。","有时行藥来，喜遇归山客。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 板橋 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aad932f-b802-42ec-831c-c2734e20a1f0', '藍田溪雜詠二十二首 石井', '藍田溪杂詠二十二首 石井', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["片霞照仙井，泉底桃花紅。","那知幽石下，不與武陵通。"]', '["片霞照仙井，泉底桃花紅。","那知幽石下，不與武陵通。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 石井 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd47ef5a-fcb2-4e2a-9e85-f910de2fd173', '藍田溪雜詠二十二首 古藤', '藍田溪杂詠二十二首 古藤', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["引蔓出雲樹，垂綸覆巢鶴。","幽人對酒時，苔上閑花落。"]', '["引蔓出云樹，垂綸覆巢鹤。","幽人对酒时，苔上闲花落。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 古藤 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15ef0190-f37a-4dd2-b2f2-efbd06e5c252', '藍田溪雜詠二十二首 晚歸鷺', '藍田溪杂詠二十二首 晚归鷺', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["池上靜難厭，雲間欲去晚。","忽背夕陽飛，乘興清風遠。"]', '["池上静难厭，云间欲去晚。","忽背夕陽飞，乘兴清风远。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 晚歸鷺 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17fb29eb-2dde-4301-85fb-ec22ca57c6cb', '藍田溪雜詠二十二首 洞仙謠', '藍田溪杂詠二十二首 洞仙謠', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["幾轉到青山，數重度流水。","秦人入雲去，知向桃源裏。"]', '["幾轉到青山，數重度流水。","秦人入云去，知向桃源裏。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 洞仙謠 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c4e26bd-7682-40db-ac9a-7748a093ab71', '藍田溪雜詠二十二首 藥圃', '藍田溪杂詠二十二首 藥圃', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["春畦生百藥，花葉香初霽。","好容似風光，偏來入叢蕙。"]', '["春畦生百藥，花葉香初霽。","好容似风光，偏来入叢蕙。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 藥圃 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('546f15ef-b30b-43cd-b97d-0b2591abe2b9', '藍田溪雜詠二十二首 石上苔', '藍田溪杂詠二十二首 石上苔', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["淨與溪色連，幽宜松雨滴。","誰知古石上，不染世人跡。"]', '["淨與溪色連，幽宜松雨滴。","誰知古石上，不染世人跡。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 石上苔 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98b3a815-e691-4539-99dc-b8bcf13391e2', '藍田溪雜詠二十二首 窗裏山', '藍田溪杂詠二十二首 窗裏山', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["遠岫見如近，千里一窗裏。","坐來石上雲，乍謂壺中起。"]', '["远岫见如近，千里一窗裏。","坐来石上云，乍謂壺中起。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 窗裏山 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('006adf6f-0796-40ae-9143-224e5036cba0', '藍田溪雜詠二十二首 竹間路', '藍田溪杂詠二十二首 竹间路', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["暗歸草堂靜，半入花園去。","有時載酒來，不與清風遇。"]', '["暗归草堂静，半入花园去。","有时載酒来，不與清风遇。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 竹間路 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4639b839-235b-4c5e-8355-29c2b797fd3c', '藍田溪雜詠二十二首 竹嶼', '藍田溪杂詠二十二首 竹嶼', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["幽鳥清漣上，興來看不足。","新篁壓水低，昨夜鴛鴦宿。"]', '["幽鸟清漣上，兴来看不足。","新篁壓水低，昨夜鴛鴦宿。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 竹嶼 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f954ad6f-bac4-417a-96ae-0489e9fbf9f4', '藍田溪雜詠二十二首 砌下泉', '藍田溪杂詠二十二首 砌下泉', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["穿雲來自遠，激砌流偏駛。","能資庭戶幽，更引海禽至。"]', '["穿云来自远，激砌流偏駛。","能資庭戶幽，更引海禽至。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 砌下泉 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f5eb3c6-2a14-4f80-a59d-a19296ae310e', '藍田溪雜詠二十二首 戲鷗', '藍田溪杂詠二十二首 戲鷗', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["乍依菱蔓聚，盡向蘆花滅。","更喜好風來，數片翻晴雪。"]', '["乍依菱蔓聚，尽向蘆花滅。","更喜好风来，數片翻晴雪。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 戲鷗 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('702741c8-6f14-4f92-9e2c-195ede060535', '藍田溪雜詠二十二首 遠山鐘', '藍田溪杂詠二十二首 远山鐘', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["風送出山鐘，雲霞度水淺。","欲知聲盡處，鳥滅寥天遠。"]', '["风送出山鐘，云霞度水淺。","欲知声尽处，鸟滅寥天远。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 遠山鐘 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('684bb5ef-edb0-45c7-b3fe-0e3fdadfc958', '藍田溪雜詠二十二首 東陂', '藍田溪杂詠二十二首 东陂', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["永日興難忘，掇芳春陂曲。","新晴花枝下，愛此苔水綠。"]', '["永日兴难忘，掇芳春陂曲。","新晴花枝下，愛此苔水綠。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 東陂 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45cab612-ae5c-4262-891d-2a1f0a2a28e6', '藍田溪雜詠二十二首 池上亭', '藍田溪杂詠二十二首 池上亭', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["臨池構杏梁，待客歸煙塘。","水上褰簾好，蓮開杜若香。"]', '["臨池構杏梁，待客归煙塘。","水上褰簾好，蓮开杜若香。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 池上亭 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16b9f041-fd22-452c-a23e-137ee4703aee', '藍田溪雜詠二十二首 銜魚翠鳥', '藍田溪杂詠二十二首 銜鱼翠鸟', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["有意蓮葉間，瞥然下高樹。","擘波得潛魚，一點翠光去。"]', '["有意蓮葉间，瞥然下高樹。","擘波得潛鱼，一点翠光去。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 銜魚翠鳥 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3018b75e-666f-4dcb-9baa-cc5050fd2165', '藍田溪雜詠二十二首 石蓮花', '藍田溪杂詠二十二首 石蓮花', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["幽石生芙蓉，百花慚美色。","遠笑越溪女，聞芳不可識。"]', '["幽石生芙蓉，百花慚美色。","远笑越溪女，闻芳不可識。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 石蓮花 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2634eec-d22c-4240-bf42-6c8aa9fe364e', '藍田溪雜詠二十二首 潺湲聲', '藍田溪杂詠二十二首 潺湲声', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["亂石跳素波，寒聲聞幾處。","颼颼暝風引，散出空林去。"]', '["亂石跳素波，寒声闻幾处。","颼颼暝风引，散出空林去。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 潺湲聲 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ea81bc9-8f2c-45ed-9eec-04156a93b9fa', '藍田溪雜詠二十二首 松下雪', '藍田溪杂詠二十二首 松下雪', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["雖因朔風至，不向瑤臺側。","唯助苦寒松，偏明後彫色。"]', '["雖因朔风至，不向瑤台側。","唯助苦寒松，偏明後彫色。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 松下雪 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f65b5ec-4058-4515-bc68-719d1e163a0d', '藍田溪雜詠二十二首 田鶴', '藍田溪杂詠二十二首 田鹤', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["田鶴望碧霄，無風亦自舉。","單飛後片雲，早晚及前侶。"]', '["田鹤望碧霄，無风亦自舉。","單飞後片云，早晚及前侶。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 田鶴 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41d92717-d215-40e4-b0bc-ae82ad0a2f32', '藍田溪雜詠二十二首 題南陂', '藍田溪杂詠二十二首 題南陂', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["家住鳳城南，門臨古陂曲。","時憐上林雁，半入池塘宿。"]', '["家住鳳城南，门臨古陂曲。","时怜上林雁，半入池塘宿。"]', '诗', 'shi', '', NULL, '藍田溪雜詠二十二首 題南陂 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1d20fd6-5e74-4643-a77e-956d949927c9', '傷秋', '傷秋', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["歲去人頭白，秋來樹葉黃。","搔頭向黃葉，與爾共悲傷。"]', '["歲去人头白，秋来樹葉黄。","搔头向黄葉，與爾共悲傷。"]', '诗', 'shi', '', NULL, '傷秋 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c627c9cb-f2e3-49ad-bfb9-3639b5ffdbf3', '送崔山人歸山', '送崔山人归山', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["東山殘雨挂斜暉，野客巢由指翠微。","別酒稍酣乘興去，知君不羨白雲歸。"]', '["东山殘雨挂斜暉，野客巢由指翠微。","別酒稍酣乘兴去，知君不羨白云归。"]', '诗', 'shi', '', NULL, '送崔山人歸山 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('473f9647-7a46-44ef-a302-ec4795d11019', '題禮上人壁畫山水', '題禮上人壁畫山水', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["連山畫出暎禪扉，粉壁香筵滿翠微。","坐來鑪氣縈空散，共指晴雲向嶺歸。"]', '["連山畫出暎禪扉，粉壁香筵满翠微。","坐来鑪氣縈空散，共指晴云向嶺归。"]', '诗', 'shi', '', NULL, '題禮上人壁畫山水 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9197f16-9922-4614-8b04-4a7ed7330780', '送歐陽子還江華郡', '送歐陽子還江华郡', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["江華勝事接湘濱，千里湖山入興新。","才子思歸催去櫂，汀花且爲駐殘春。"]', '["江华勝事接湘濱，千里湖山入兴新。","才子思归催去櫂，汀花且爲駐殘春。"]', '诗', 'shi', '', NULL, '送歐陽子還江華郡 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f1dcbca-e2c9-4a43-be80-9d51f23a6dab', '暮春歸故山草堂', '暮春归故山草堂', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["谷口春殘黃鳥稀，辛夷花盡杏花飛。","始憐幽竹山窗下，不改清陰待我歸。"]', '["谷口春殘黄鸟稀，辛夷花尽杏花飞。","始怜幽竹山窗下，不改清陰待我归。"]', '诗', 'shi', '', NULL, '暮春歸故山草堂 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3eb2a78-af4b-4fae-b92b-d7f637c40f7d', '訪李卿不遇', '訪李卿不遇', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["畫戟朱樓暎晚霞，高梧寒柳度飛鴉。","門前不見歸軒至，城上愁看落日斜。"]', '["畫戟朱楼暎晚霞，高梧寒柳度飞鴉。","门前不见归軒至，城上愁看落日斜。"]', '诗', 'shi', '', NULL, '訪李卿不遇 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1c83a00-7713-4cbf-85c6-970cde2b6170', '與趙莒茶讌', '與趙莒茶讌', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["竹下忘言對紫茶，全勝羽客醉流霞。","塵心洗盡興難盡，一樹蟬聲片影斜。"]', '["竹下忘言对紫茶，全勝羽客醉流霞。","塵心洗尽兴难尽，一樹蟬声片影斜。"]', '诗', 'shi', '', NULL, '與趙莒茶讌 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f5f758b-ba23-44d3-b26e-e7b0f9e728e7', '故王維右丞堂前芍藥花開悽然感懷', '故王維右丞堂前芍藥花开悽然感懷', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["芍藥花開出舊欄，春衫掩淚再來看。","主人不在花長在，更勝青松守歲寒。"]', '["芍藥花开出旧欄，春衫掩泪再来看。","主人不在花长在，更勝青松守歲寒。"]', '诗', 'shi', '', NULL, '故王維右丞堂前芍藥花開悽然感懷 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46aa871a-fb98-4e33-94a7-3d250c069b34', '送張參及第還家', '送張參及第還家', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["大學三年聞琢玉，東堂一舉早成名。","借問還家何處好，玉人含笑下機迎。"]', '["大学三年闻琢玉，东堂一舉早成名。","借问還家何处好，玉人含笑下機迎。"]', '诗', 'shi', '', NULL, '送張參及第還家 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1caa9b60-cd4d-4439-aeb7-b213034c7860', '夜泊鸚鵡洲', '夜泊鸚鵡洲', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["月照溪邊一罩蓬，夜聞清唱有微風。","小樓深巷敲方響，水國人家在處同。"]', '["月照溪邊一罩蓬，夜闻清唱有微风。","小楼深巷敲方响，水国人家在处同。"]', '诗', 'shi', '', NULL, '夜泊鸚鵡洲 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0408a74-2d10-4fd2-a7b3-1206d341be96', '歸雁', '归雁', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["瀟湘何事等閑回，水碧沙明兩岸苔。","二十五弦彈夜月，不勝清怨却飛來。"]', '["瀟湘何事等闲回，水碧沙明兩岸苔。","二十五弦彈夜月，不勝清怨却飞来。"]', '诗', 'shi', '', NULL, '歸雁 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ba31a1d-ab47-46fd-927d-342561972d35', '春郊', '春郊', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["水遶冰渠漸有聲，氣融煙塢晚來明。","東風好作陽和使，逢草逢花報發生。"]', '["水遶冰渠漸有声，氣融煙塢晚来明。","东风好作陽和使，逢草逢花報發生。"]', '诗', 'shi', '', NULL, '春郊 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23f178cd-1724-4283-acba-9ca26452bde2', '晚歸嚴明府題門', '晚归嚴明府題门', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["降士林霑蕙草寒，弦驚翰苑失鴛鸞。","秋中回首君門阻，馬上應歌行路難。"]', '["降士林霑蕙草寒，弦驚翰苑失鴛鸾。","秋中回首君门阻，马上應歌行路难。"]', '诗', 'shi', '', NULL, '晚歸嚴明府題門 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5980c45-6386-4d47-a777-3855fe8c70a7', '秋夜送趙冽歸襄陽', '秋夜送趙冽归襄陽', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["斗酒忘言良夜深，紅萱露滴鵲驚林。","欲知別後思今夕，漢水東流是寸心。"]', '["斗酒忘言良夜深，紅萱露滴鵲驚林。","欲知別後思今夕，漢水东流是寸心。"]', '诗', 'shi', '', NULL, '秋夜送趙冽歸襄陽 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb877f52-1ffe-4c77-83c4-ecf32a854dca', '送符別駕還郡', '送符別駕還郡', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["驥足駸駸吳越關，屏星復與紫書還。","已知從事元無事，城上愁看海上山。"]', '["驥足駸駸吳越关，屏星复與紫书還。","已知從事元無事，城上愁看海上山。"]', '诗', 'shi', '', NULL, '送符別駕還郡 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f34518c9-3f0d-4d26-ac73-8906b9555189', '同王員外隴城絕句', '同王員外隴城絕句', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["三軍版築脫金刀，黎庶翻慚將士勞。","不憶新城連嶂起，唯驚畫角入雲高。"]', '["三軍版築脫金刀，黎庶翻慚將士勞。","不憶新城連嶂起，唯驚畫角入云高。"]', '诗', 'shi', '', NULL, '同王員外隴城絕句 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('165bf110-88b1-49a4-90c2-ef16d75281be', '過故洛城', '過故洛城', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["故城門外春日斜，故城門裏無人家。","市朝欲認不知處，漠漠野田空草花。"]', '["故城门外春日斜，故城门裏無人家。","市朝欲認不知处，漠漠野田空草花。"]', '诗', 'shi', '', NULL, '過故洛城 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce5bf0e4-244b-47f2-88fe-9d9a0ab89aa2', '校獵曲', '校獵曲', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["長楊殺氣連雲飛，漢主秋畋正掩圍。","重門日晏紅塵出，數騎胡人獵獸歸。"]', '["长楊殺氣連云飞，漢主秋畋正掩圍。","重门日晏紅塵出，數騎胡人獵獸归。"]', '诗', 'shi', '', NULL, '校獵曲 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fabfce9-658e-432b-bd5e-a289140e78d7', '晚過橫灞寄張藍田', '晚過橫灞寄張藍田', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["亂水東流落照時，黃花滿徑客行遲。","林端忽見南山色，馬上還吟陶令詩。"]', '["亂水东流落照时，黄花满徑客行遲。","林端忽见南山色，马上還吟陶令诗。"]', '诗', 'shi', '', NULL, '晚過橫灞寄張藍田 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4e43f9b-d3b8-498f-9807-0d741f09ebf5', '九日田舍', '九日田舍', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["今日陶家野興偏，東籬黃菊映秋田。","浮雲暝鳥飛將盡，始達青山新月前。"]', '["今日陶家野兴偏，东籬黄菊映秋田。","浮云暝鸟飞將尽，始達青山新月前。"]', '诗', 'shi', '', NULL, '九日田舍 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cc12f04-d1df-4531-a479-3d566e41e35c', '長安落第', '长安落第', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["花繁柳暗九門深，對飲悲歌淚滿襟。","數日鶯花皆落羽，一回春至一傷心。"]', '["花繁柳暗九门深，对饮悲歌泪满襟。","數日鶯花皆落羽，一回春至一傷心。"]', '诗', 'shi', '', NULL, '長安落第 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31012621-1bac-4c06-9d83-39e1dd2bf304', '二風詩   一', '二风诗   一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["猗皇至聖兮，至惠至仁。","德施蘊蘊，蘊蘊如何。","不全不缺，莫知所貺。"]', '["猗皇至聖兮，至惠至仁。","德施蘊蘊，蘊蘊如何。","不全不缺，莫知所貺。"]', '诗', 'shi', '', NULL, '二風詩   一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e17941fc-e05a-4c23-9f3b-7ca461c66d78', '二風詩   二', '二风诗   二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["猗皇至聖兮，至儉至明。","化流瀛瀛，瀛瀛如何。","不虢不赩，莫知其極。"]', '["猗皇至聖兮，至儉至明。","化流瀛瀛，瀛瀛如何。","不虢不赩，莫知其極。"]', '诗', 'shi', '', NULL, '二風詩   二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('633d9d0c-bc4e-4042-b97d-d23bdbdc2f9a', '二風詩   一', '二风诗   一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["至化之深兮，猗猗娭娭。","如煦如吹，如負如持。","而不知其慈，故莫周莫止，靜和而止。"]', '["至化之深兮，猗猗娭娭。","如煦如吹，如負如持。","而不知其慈，故莫周莫止，静和而止。"]', '诗', 'shi', '', NULL, '二風詩   一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae9fe376-c4b4-4483-a9d6-0aacd8c46635', '二風詩   二', '二风诗   二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["至化之極兮，瀛瀛溶溶。","如涵如封，如隨如從。","而不知其功，故莫由莫己，順時而理。"]', '["至化之極兮，瀛瀛溶溶。","如涵如封，如隨如從。","而不知其功，故莫由莫己，順时而理。"]', '诗', 'shi', '', NULL, '二風詩   二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afa55dab-a4d9-4b0e-a50b-3d005af8225a', '二風詩   一', '二风诗   一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["至哉勤績，不盈不延。","誰能頌之，我請頌焉。","於戲勞王，勤亦何極。","濟爾九土，山川溝洫。"]', '["至哉勤績，不盈不延。","誰能頌之，我請頌焉。","於戲勞王，勤亦何極。","濟爾九土，山川溝洫。"]', '诗', 'shi', '', NULL, '二風詩   一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('627f459c-0528-4528-af44-653bf07b8401', '二風詩   二', '二风诗   二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["至哉儉德，不豐不敷。","誰能頌之，我請頌夫。","於戲勞王，儉亦何深。","戒爾萬代，奢侈荒淫。"]', '["至哉儉德，不豐不敷。","誰能頌之，我請頌夫。","於戲勞王，儉亦何深。","戒爾万代，奢侈荒淫。"]', '诗', 'shi', '', NULL, '二風詩   二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dfcdc1d-0ef3-4d04-8264-e45c2a2a1291', '二風詩   三', '二风诗   三', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["至哉茂功，不升不圯。","誰能頌之，我請頌矣。","於戲勞王，功亦何大。","去爾兆庶，洪湮災害。"]', '["至哉茂功，不升不圯。","誰能頌之，我請頌矣。","於戲勞王，功亦何大。","去爾兆庶，洪湮災害。"]', '诗', 'shi', '', NULL, '二風詩   三 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef4ef79e-b0f0-49b8-9e84-e48091c47b20', '二風詩', '二风诗', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["爲君之道，何以爲明。","功不濫賞，罪不濫刑。","讜言則聽，諂言不聽。","王至是然，可爲明焉。"]', '["爲君之道，何以爲明。","功不濫賞，罪不濫刑。","讜言則听，諂言不听。","王至是然，可爲明焉。"]', '诗', 'shi', '', NULL, '二風詩 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c927eca-8188-4df5-b23f-1c08d336101c', '二風詩', '二风诗', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["理何爲兮，系修文德。","加之清一，莫不順則。","意彼刑法，設以化人。","致使無之，而化益純。","所謂代刑，以道去殺。","嗚呼嗚呼，人不斯察。"]', '["理何爲兮，系修文德。","加之清一，莫不順則。","意彼刑法，設以化人。","致使無之，而化益純。","所謂代刑，以道去殺。","嗚呼嗚呼，人不斯察。"]', '诗', 'shi', '', NULL, '二風詩 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c8844aa-297a-4b71-945d-be7b76e9b861', '二風詩', '二风诗', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["國有世謨，仁信勤歟。","王實惛荒，終亡此乎。","焉有力恣諂惑，而不亡其國。","嗚呼亡王，忍爲此心。","敢正亡王，永爲世箴。"]', '["国有世謨，仁信勤歟。","王實惛荒，終亡此乎。","焉有力恣諂惑，而不亡其国。","嗚呼亡王，忍爲此心。","敢正亡王，永爲世箴。"]', '诗', 'shi', '', NULL, '二風詩 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd7aed72-22c2-4bc0-b14d-9cd6f81a61ee', '二風詩   一', '二风诗   一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["嘻乎王家，曾有凶王。","中世失國，豈非驕荒。","復復之難，令則可忘。"]', '["嘻乎王家，曾有凶王。","中世失国，豈非驕荒。","复复之难，令則可忘。"]', '诗', 'shi', '', NULL, '二風詩   一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0b6700d-4b71-4ec7-ad56-f36d19217aff', '二風詩   二', '二风诗   二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["嘻乎亂王，王心何思。","暴淫虐惑，無思不爲。","生人冤怨，言何極之。"]', '["嘻乎亂王，王心何思。","暴淫虐惑，無思不爲。","生人冤怨，言何極之。"]', '诗', 'shi', '', NULL, '二風詩   二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34c8fe9f-2b12-4a0d-946e-3521d1963454', '二風詩   一', '二风诗   一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["夫爲君上兮，慈順明恕。","可以化人，忍行昏恣。","獨樂其身，一徇所欲。"]', '["夫爲君上兮，慈順明恕。","可以化人，忍行昏恣。","独乐其身，一徇所欲。"]', '诗', 'shi', '', NULL, '二風詩   一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb2aa59e-c19b-4dfc-a7b2-b8950927b2ad', '二風詩   二', '二风诗   二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["夫爲君上兮，兢慎儉約。","可以保身，忍行荒惑。","虐暴於人，前世失國。"]', '["夫爲君上兮，兢慎儉約。","可以保身，忍行荒惑。","虐暴於人，前世失国。"]', '诗', 'shi', '', NULL, '二風詩   二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d5430c2-ffe3-4e11-8052-d3c76e65c984', '二風詩   一', '二风诗   一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["賢聖爲上兮，必儉約戒身。","鑒察化人，所以保福也。","如何不思，荒恣是爲。","上下隔塞，人神怨奰。","敖惡無厭，不畏顛墜。"]', '["賢聖爲上兮，必儉約戒身。","鑒察化人，所以保福也。","如何不思，荒恣是爲。","上下隔塞，人神怨奰。","敖惡無厭，不畏顛墜。"]', '诗', 'shi', '', NULL, '二風詩   一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0092551d-9fee-4aba-a7b0-cf7d4d88a9a8', '二風詩   二', '二风诗   二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["聖賢爲上兮，必用賢正。","黜姦佞之臣，所以長久也。","如何反是，以爲亂矣。","寵邪信惑，近佞好諛。","廢嫡立庶，忍爲禍謨。"]', '["聖賢爲上兮，必用賢正。","黜姦佞之臣，所以长久也。","如何反是，以爲亂矣。","寵邪信惑，近佞好諛。","廢嫡立庶，忍爲禍謨。"]', '诗', 'shi', '', NULL, '二風詩   二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6eab1b5c-be2b-448c-bf89-ccc3538b1f48', '二風詩', '二风诗', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["夫何傷兮，傷王乎。","欲何爲乎，將蠹枯矣。","無人救乎，蠹枯及矣。","不可救乎，嗟傷王。","自爲人君，變爲人奴。","爲人君者，忘戒乎。"]', '["夫何傷兮，傷王乎。","欲何爲乎，將蠹枯矣。","無人救乎，蠹枯及矣。","不可救乎，嗟傷王。","自爲人君，变爲人奴。","爲人君者，忘戒乎。"]', '诗', 'shi', '', NULL, '二風詩 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc9049ec-2403-4e98-ae90-0a5d1a43e0af', '補樂歌十首  一', '補乐歌十首  一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["吾人苦兮，水深深。","網罟設兮，水不深。"]', '["吾人苦兮，水深深。","網罟設兮，水不深。"]', '诗', 'shi', '', NULL, '補樂歌十首  一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98a88ab8-d2ee-4d0f-bfb8-9b8da55fbf87', '補樂歌十首  二', '補乐歌十首  二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["吾人苦兮，山幽幽。","網罟設兮，山不幽。"]', '["吾人苦兮，山幽幽。","網罟設兮，山不幽。"]', '诗', 'shi', '', NULL, '補樂歌十首  二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91ee9dce-e5b4-4475-8931-a7fa153c2517', '補樂歌十首  一', '補乐歌十首  一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["猗太帝兮，其智如神。","分草實兮，濟我生人。"]', '["猗太帝兮，其智如神。","分草實兮，濟我生人。"]', '诗', 'shi', '', NULL, '補樂歌十首  一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48a397ac-99aa-473d-97be-242f8cbfd656', '補樂歌十首  二', '補乐歌十首  二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["猗太帝兮，其功如天。","均四時兮，成我豐年。"]', '["猗太帝兮，其功如天。","均四时兮，成我豐年。"]', '诗', 'shi', '', NULL, '補樂歌十首  二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c7c3863-d174-4288-91b5-51fb9bfc0049', '補樂歌十首  一', '補乐歌十首  一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["玄雲溶溶兮，垂雨蒙蒙。","類我聖澤兮，涵濡不窮。"]', '["玄云溶溶兮，垂雨蒙蒙。","類我聖澤兮，涵濡不窮。"]', '诗', 'shi', '', NULL, '補樂歌十首  一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c55496ff-61fd-426c-bdbe-44f34dbc91ac', '補樂歌十首  二', '補乐歌十首  二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["玄雲漠漠兮，含暎逾光。","類我聖德兮，溥被無方。"]', '["玄云漠漠兮，含暎逾光。","類我聖德兮，溥被無方。"]', '诗', 'shi', '', NULL, '補樂歌十首  二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52b57a1a-491a-4bfd-b8fa-5beeb8258252', '補樂歌十首', '補乐歌十首', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["聖德至深兮，奫奫如淵。","生類娭娭兮，孰知其然。"]', '["聖德至深兮，奫奫如淵。","生類娭娭兮，孰知其然。"]', '诗', 'shi', '', NULL, '補樂歌十首 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('674e1155-eeba-4ff7-8a56-1a76b8909918', '補樂歌十首', '補乐歌十首', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["植植萬物兮，滔滔根莖。","五德涵柔兮，渢渢而生。","其生如何兮秞秞，天下皆自我君兮化成。"]', '["植植万物兮，滔滔根莖。","五德涵柔兮，渢渢而生。","其生如何兮秞秞，天下皆自我君兮化成。"]', '诗', 'shi', '', NULL, '補樂歌十首 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9fcd9a1-0683-42df-81a9-daeb1dd16e00', '補樂歌十首  一', '補乐歌十首  一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["我有金石兮，擊考崇崇。","與汝歌舞兮，上帝之風。","由六合兮，英華渢渢。"]', '["我有金石兮，擊考崇崇。","與汝歌舞兮，上帝之风。","由六合兮，英华渢渢。"]', '诗', 'shi', '', NULL, '補樂歌十首  一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b6faef7-0a07-4959-bbe7-fdbdbad2feed', '補樂歌十首  二', '補乐歌十首  二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["我有絲竹兮，韻和泠泠。","與汝歌舞兮，上帝之聲。","由六合兮，根底嬴嬴。"]', '["我有絲竹兮，韻和泠泠。","與汝歌舞兮，上帝之声。","由六合兮，根底嬴嬴。"]', '诗', 'shi', '', NULL, '補樂歌十首  二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27097d2b-436d-459f-9fb1-8c707bc2b17e', '補樂歌十首  一', '補乐歌十首  一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["元化油油兮，孰知其然。","至德汨汨兮，順之以先。"]', '["元化油油兮，孰知其然。","至德汨汨兮，順之以先。"]', '诗', 'shi', '', NULL, '補樂歌十首  一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6310a88f-cb65-4b15-a872-d01f6c26e160', '補樂歌十首  二', '補乐歌十首  二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["元化浘浘兮，孰知其然。","至道泱泱兮，由之以全。"]', '["元化浘浘兮，孰知其然。","至道泱泱兮，由之以全。"]', '诗', 'shi', '', NULL, '補樂歌十首  二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aff72fe0-de9c-456d-b120-eab05f9eda7d', '補樂歌十首  一', '補乐歌十首  一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["森森羣象兮，日見生成。","欲聞朕初兮，玄封冥冥。"]', '["森森羣象兮，日见生成。","欲闻朕初兮，玄封冥冥。"]', '诗', 'shi', '', NULL, '補樂歌十首  一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('928bf486-9360-4a41-a975-69ca93267685', '補樂歌十首  二', '補乐歌十首  二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["洋洋至化兮，日見深柔。","欲聞大濩兮，大淵油油。"]', '["洋洋至化兮，日见深柔。","欲闻大濩兮，大淵油油。"]', '诗', 'shi', '', NULL, '補樂歌十首  二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28d35608-b5e6-4d52-9699-31684e78ba1e', '補樂歌十首  一', '補乐歌十首  一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["茫茫下土兮，乃生九州。","山有長岑兮，川有深流。"]', '["茫茫下土兮，乃生九州。","山有长岑兮，川有深流。"]', '诗', 'shi', '', NULL, '補樂歌十首  一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aeefab6-e37b-44e4-9d17-d7e0e351afb2', '補樂歌十首  二', '補乐歌十首  二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["茫茫下土兮，乃均四方。","國有安乂兮，野有封疆。"]', '["茫茫下土兮，乃均四方。","国有安乂兮，野有封疆。"]', '诗', 'shi', '', NULL, '補樂歌十首  二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85e6b7ca-44ee-4eb2-a9cd-5a2a0acdfc60', '補樂歌十首  三', '補乐歌十首  三', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["茫茫下土兮，乃歌萬年。","上有茂功兮，下戴仁天。"]', '["茫茫下土兮，乃歌万年。","上有茂功兮，下戴仁天。"]', '诗', 'shi', '', NULL, '補樂歌十首  三 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca0b0804-ac39-4452-8947-6c85d7f8b49e', '補樂歌十首  一', '補乐歌十首  一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["萬姓苦兮，怨且哭。","不有聖人兮，誰護育。"]', '["万姓苦兮，怨且哭。","不有聖人兮，誰護育。"]', '诗', 'shi', '', NULL, '補樂歌十首  一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caf12362-3844-4689-a986-400da794c62e', '補樂歌十首  二', '補乐歌十首  二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["聖人生兮，天下和。","萬姓熙熙兮，舞且歌。"]', '["聖人生兮，天下和。","万姓熙熙兮，舞且歌。"]', '诗', 'shi', '', NULL, '補樂歌十首  二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5de3245d-8e8a-44df-88a4-d154aaca2983', '系樂府十二首 思太古', '系乐府十二首 思太古', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["東南三千里，沅湘爲太湖。","湖上山谷深，有人多似愚。","嬰孩寄樹顛，就水捕鷠鱸。","所歡同鳥獸，身意復何拘。","吾行遍九州，此風皆已無。","吁嗟聖賢敎，不覺久躊躕。"]', '["东南三千里，沅湘爲太湖。","湖上山谷深，有人多似愚。","嬰孩寄樹顛，就水捕鷠鱸。","所歡同鸟獸，身意复何拘。","吾行遍九州，此风皆已無。","吁嗟聖賢敎，不覺久躊躕。"]', '诗', 'shi', '', NULL, '系樂府十二首 思太古 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceb3818f-a14f-4399-9591-c9afbe18c38c', '系樂府十二首 隴上歎', '系乐府十二首 隴上歎', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["援車登隴坂，窮高遂停駕。","延望戎狄鄉，巡迴復悲咤。","滋移有情敎，草木猶可化。","聖賢禮讓風，何不遍西夏。","父子忍猜害，君臣敢欺詐。","所適今若斯，悠悠欲安舍。"]', '["援车登隴坂，窮高遂停駕。","延望戎狄乡，巡迴复悲咤。","滋移有情敎，草木猶可化。","聖賢禮讓风，何不遍西夏。","父子忍猜害，君臣敢欺詐。","所適今若斯，悠悠欲安舍。"]', '诗', 'shi', '', NULL, '系樂府十二首 隴上歎 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('225c1ea9-a830-4f1f-a636-22f707d6ee94', '系樂府十二首 頌東夷', '系乐府十二首 頌东夷', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["嘗聞古天子，朝會張新樂。","金石無全聲，宮商亂清濁。","東驚且悲歎，節變何煩數。","始知中國人，耽此亡純朴。","爾爲外方客，何爲獨能覺。","其音若或在，蹈海吾將學。"]', '["嘗闻古天子，朝會張新乐。","金石無全声，宮商亂清濁。","东驚且悲歎，節变何煩數。","始知中国人，耽此亡純朴。","爾爲外方客，何爲独能覺。","其音若或在，蹈海吾將学。"]', '诗', 'shi', '', NULL, '系樂府十二首 頌東夷 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebccd8ed-9a95-4ea7-b6ff-b86b1785a3ba', '系樂府十二首 賤士吟', '系乐府十二首 賤士吟', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["南風發天和，和氣天下流。","能使萬物榮，不能變羈愁。","爲愁亦何爾，自請說此由。","諂競實多路，苟邪皆共求。","嘗聞古君子，指以爲深羞。","正方終莫可，江海有滄洲。"]', '["南风發天和，和氣天下流。","能使万物榮，不能变羈愁。","爲愁亦何爾，自請说此由。","諂競實多路，苟邪皆共求。","嘗闻古君子，指以爲深羞。","正方終莫可，江海有滄洲。"]', '诗', 'shi', '', NULL, '系樂府十二首 賤士吟 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99a389e7-18b4-4296-84b9-8e997cab2700', '系樂府十二首 欸乃曲', '系乐府十二首 欸乃曲', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["誰能聽欸乃，欸乃感人情。","不恨湘波深，不怨湘水清。","所嗟豈敢道，空羨江月明。","昔聞扣斷舟，引釣歌此聲。","始歌悲風起，歌竟愁雲生。","遺曲今何在，逸爲漁父行。"]', '["誰能听欸乃，欸乃感人情。","不恨湘波深，不怨湘水清。","所嗟豈敢道，空羨江月明。","昔闻扣斷舟，引釣歌此声。","始歌悲风起，歌竟愁云生。","遺曲今何在，逸爲漁父行。"]', '诗', 'shi', '', NULL, '系樂府十二首 欸乃曲 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50381aa5-f88e-4886-a498-18f45e97639b', '系樂府十二首 貧婦詞', '系乐府十二首 貧婦词', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["誰知苦貧夫，家有愁怨妻。","請君聽其詞，能不爲酸悽。","所憐抱中兒，不如山下麑。","空念庭前地，化爲人吏蹊。","出門望山澤，回頭心復迷。","何時見府主，長跪向之啼。"]', '["誰知苦貧夫，家有愁怨妻。","請君听其词，能不爲酸悽。","所怜抱中兒，不如山下麑。","空念庭前地，化爲人吏蹊。","出门望山澤，回头心复迷。","何时见府主，长跪向之啼。"]', '诗', 'shi', '', NULL, '系樂府十二首 貧婦詞 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21ada893-7d16-4468-937b-0a7a8ee748a3', '系樂府十二首 去鄉悲', '系乐府十二首 去乡悲', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["躊躕古塞關，悲歌爲誰長。","日行見孤老，羸弱相提將。","聞其呼怨聲，聞聲問其方。","方言無患苦，豈棄父母鄉。","非不見其心，仁惠誠所望。","念之何可說，獨立爲悽傷。"]', '["躊躕古塞关，悲歌爲誰长。","日行见孤老，羸弱相提將。","闻其呼怨声，闻声问其方。","方言無患苦，豈棄父母乡。","非不见其心，仁惠誠所望。","念之何可说，独立爲悽傷。"]', '诗', 'shi', '', NULL, '系樂府十二首 去鄉悲 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfa4d6c9-c2db-4f82-b023-0307f930d079', '系樂府十二首 壽翁興', '系乐府十二首 壽翁兴', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["借問多壽翁，何方自修育。","惟云順所然，忘情學草木。","始知世上術，勞苦化金玉。","不見充所求，空聞肆耽欲。","清和存王母，潛濩無亂黷。","誰正好長生，此言堪佩服。"]', '["借问多壽翁，何方自修育。","惟云順所然，忘情学草木。","始知世上術，勞苦化金玉。","不见充所求，空闻肆耽欲。","清和存王母，潛濩無亂黷。","誰正好长生，此言堪佩服。"]', '诗', 'shi', '', NULL, '系樂府十二首 壽翁興 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5e45181-f322-4a49-9d21-550e336a52bc', '系樂府十二首 農臣怨', '系乐府十二首 農臣怨', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["農臣何所怨，乃欲干人主。","不識天地心，徒然怨風雨。","將論草木患，欲說昆蟲苦。","巡迴宮闕傍，其意無由吐。","一朝哭都市，淚盡歸田畝。","謠頌若采之，此言當可取。"]', '["農臣何所怨，乃欲干人主。","不識天地心，徒然怨风雨。","將論草木患，欲说昆蟲苦。","巡迴宮闕傍，其意無由吐。","一朝哭都市，泪尽归田畝。","謠頌若采之，此言當可取。"]', '诗', 'shi', '', NULL, '系樂府十二首 農臣怨 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c95d62a4-e333-4701-b69f-2f57ce986cd6', '系樂府十二首 謝大龜', '系乐府十二首 謝大龟', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["客來自江漢，云得雙大龜。","且言龜甚靈，問我君何疑。","自昔保方正，顧嘗無妄私。","順和固鄙分，全守真常規。","行之恐不及，此外將何爲。","惠恩如可謝，占問敢終辭。"]', '["客来自江漢，云得雙大龟。","且言龟甚靈，问我君何疑。","自昔保方正，顧嘗無妄私。","順和固鄙分，全守真常規。","行之恐不及，此外將何爲。","惠恩如可謝，占问敢終辞。"]', '诗', 'shi', '', NULL, '系樂府十二首 謝大龜 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c9669ce-7d0f-4971-b8ae-454bf357c24a', '系樂府十二首 古遺歎', '系乐府十二首 古遺歎', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["古昔有遺歎，所歎何所爲。","有國遺賢臣，萬事爲冤悲。","所遺非遺望，所遺非可遺。","所遺非遺用，所遺在遺之。","嗟嗟山海客，全獨竟何辭。","心非膏濡類，安得無不遺。"]', '["古昔有遺歎，所歎何所爲。","有国遺賢臣，万事爲冤悲。","所遺非遺望，所遺非可遺。","所遺非遺用，所遺在遺之。","嗟嗟山海客，全独竟何辞。","心非膏濡類，安得無不遺。"]', '诗', 'shi', '', NULL, '系樂府十二首 古遺歎 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dabbc6bb-8c93-4605-b262-6aa32751bc54', '系樂府十二首 下客謠', '系乐府十二首 下客謠', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["下客無黃金，豈思主人憐。","客言勝黃金，主人然不然。","珠玉成彩翠，綺羅如嬋娟。","終恐見斯好，有時去君前。","豈知保忠信，長使令德全。","風聲與時茂，歌頌萬千年。"]', '["下客無黄金，豈思主人怜。","客言勝黄金，主人然不然。","珠玉成彩翠，綺羅如嬋娟。","終恐见斯好，有时去君前。","豈知保忠信，长使令德全。","风声與时茂，歌頌万千年。"]', '诗', 'shi', '', NULL, '系樂府十二首 下客謠 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5755fd35-e989-4652-947c-50f1de083f8e', '漫歌八曲 故城東', '漫歌八曲 故城东', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["漫惜故城東，良田野草生。","說向縣大夫，大夫勸我耕。","耕者我爲先，耕者相次焉。","誰愛故城東，今爲近郭田。"]', '["漫惜故城东，良田野草生。","说向縣大夫，大夫勸我耕。","耕者我爲先，耕者相次焉。","誰愛故城东，今爲近郭田。"]', '诗', 'shi', '', NULL, '漫歌八曲 故城東 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('372431b1-0e60-4753-9431-0e5bcf1efa9c', '漫歌八曲 西陽城', '漫歌八曲 西陽城', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["江北有大洲，洲上堪力耕。","此中宜五穀，不及西陽城。","城畔多野桑，城中多古荒。","衣食可力求，此外何所望。"]', '["江北有大洲，洲上堪力耕。","此中宜五穀，不及西陽城。","城畔多野桑，城中多古荒。","衣食可力求，此外何所望。"]', '诗', 'shi', '', NULL, '漫歌八曲 西陽城 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1e68d61-a599-4f76-9fab-3eb4b4780564', '漫歌八曲 大回中', '漫歌八曲 大回中', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["樊水欲東流，大江又北來。","樊山當其南，此中爲大回。","回中魚好遊，回中多釣舟。","漫欲作漁人，終焉無所求。"]', '["樊水欲东流，大江又北来。","樊山當其南，此中爲大回。","回中鱼好游，回中多釣舟。","漫欲作漁人，終焉無所求。"]', '诗', 'shi', '', NULL, '漫歌八曲 大回中 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c0c4d2b-a459-4a8b-9597-4d479f018863', '漫歌八曲 小回中', '漫歌八曲 小回中', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["叢石橫大江，人言是釣臺。","水石相衝激，此中爲小回。","回中浪不惡，復在武昌郭。","來客去客船，皆向此中泊。"]', '["叢石橫大江，人言是釣台。","水石相衝激，此中爲小回。","回中浪不惡，复在武昌郭。","来客去客船，皆向此中泊。"]', '诗', 'shi', '', NULL, '漫歌八曲 小回中 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7834822-cd95-4e21-b8b3-62cedc27237d', '漫歌八曲 將牛何處去二首 一', '漫歌八曲 將牛何处去二首 一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["將牛何處去，耕彼故城東。","相伴有田父，相歡惟牧童。"]', '["將牛何处去，耕彼故城东。","相伴有田父，相歡惟牧童。"]', '诗', 'shi', '', NULL, '漫歌八曲 將牛何處去二首 一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be507efa-076a-4e9b-9e70-429ee5397a15', '漫歌八曲 將牛何處去二首 二', '漫歌八曲 將牛何处去二首 二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["將牛何處去，耕彼西陽城。","叔閑修農具，直者伴我耕。"]', '["將牛何处去，耕彼西陽城。","叔闲修農具，直者伴我耕。"]', '诗', 'shi', '', NULL, '漫歌八曲 將牛何處去二首 二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb987de1-0ad9-48da-9e95-889ae8a67633', '漫歌八曲 將船何處去二首 一', '漫歌八曲 將船何处去二首 一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["將船何處去，釣彼大回中。","叔靜能鼓橈，正者隨弱翁。"]', '["將船何处去，釣彼大回中。","叔静能鼓橈，正者隨弱翁。"]', '诗', 'shi', '', NULL, '漫歌八曲 將船何處去二首 一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eed9dc8-bbda-4944-be74-875d0b45493a', '漫歌八曲 將船何處去二首 二', '漫歌八曲 將船何处去二首 二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["將船何處去，送客小回南。","有時逢惡客，還家亦少酣。"]', '["將船何处去，送客小回南。","有时逢惡客，還家亦少酣。"]', '诗', 'shi', '', NULL, '漫歌八曲 將船何處去二首 二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11ebef0c-519d-4391-9edb-e6bac07a8b8e', '引極三首 思元極', '引極三首 思元極', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["天曠莽兮杳泱茫，氣浩浩兮色蒼蒼。","上何有兮人不測，積清寥兮成元極。","彼元極兮靈且異，思一見兮藐難至。","思不從兮空自傷，心慅𢜱兮意惶懹。","思假翼兮鸞鳳，乘長風兮上羾。","揖元氣兮本深實，餐至和兮永終日。"]', '["天曠莽兮杳泱茫，氣浩浩兮色蒼蒼。","上何有兮人不測，積清寥兮成元極。","彼元極兮靈且異，思一见兮藐难至。","思不從兮空自傷，心慅𢜱兮意惶懹。","思假翼兮鸾鳳，乘长风兮上羾。","揖元氣兮本深實，餐至和兮永終日。"]', '诗', 'shi', '', NULL, '引極三首 思元極 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e66faec-7b74-49a9-a93e-56d6dd41f4dc', '引極三首 望仙府', '引極三首 望仙府', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["山鑿落兮眇嶔岑，雲溶溶兮木棽棽。","中何有兮人不覩，遠欹差兮閟仙府。","彼仙府兮深且幽，望一至兮藐無由。","望不從兮知如何，心混混兮意渾和。","思假足兮虎豹，超阻絕兮凌趠。","詣仙府兮從羽人，餌五靈兮保清真。"]', '["山鑿落兮眇嶔岑，云溶溶兮木棽棽。","中何有兮人不覩，远欹差兮閟仙府。","彼仙府兮深且幽，望一至兮藐無由。","望不從兮知如何，心混混兮意渾和。","思假足兮虎豹，超阻絕兮凌趠。","詣仙府兮從羽人，餌五靈兮保清真。"]', '诗', 'shi', '', NULL, '引極三首 望仙府 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e9d26c9-bc53-452b-a4aa-6c4f7651983d', '引極三首 懷潛君', '引極三首 懷潛君', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["海浩淼兮汩洪溶，流蘊蘊兮濤洶洶。","下何有兮人不聞，深溢漭兮居潛君。","彼潛君兮聖且神，思一見兮藐無因。","思不從兮空踟躕，心回迷兮意縈紆。","思假鱗兮鯤龍，激沆浪兮奔從。","拜潛君兮索玄寶，佩元符兮軌皇道。"]', '["海浩淼兮汩洪溶，流蘊蘊兮濤洶洶。","下何有兮人不闻，深溢漭兮居潛君。","彼潛君兮聖且神，思一见兮藐無因。","思不從兮空踟躕，心回迷兮意縈紆。","思假鱗兮鯤龙，激沆浪兮奔從。","拜潛君兮索玄寶，佩元符兮軌皇道。"]', '诗', 'shi', '', NULL, '引極三首 懷潛君 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3df458a9-2e7c-47af-85aa-844731ab9bd3', '演興四首 招太靈', '演兴四首 招太靈', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["招太靈兮山之巔，山屹𡵉兮水淪漣。","祠之櫴兮眇何年，木修修兮草鮮鮮。","嗟魑魅兮淫厲，自古昔兮崇祭。","禧太靈兮端清，予願致夫精誠。","久愵兮㤝㤝，招捃𢹝兮呼風。","風之聲兮起颸颸，吹玄雲兮散而浮。","望太靈兮儼而安，澹油溶兮都清閑。"]', '["招太靈兮山之巔，山屹𡵉兮水淪漣。","祠之櫴兮眇何年，木修修兮草鲜鲜。","嗟魑魅兮淫厲，自古昔兮崇祭。","禧太靈兮端清，予願致夫精誠。","久愵兮㤝㤝，招捃𢹝兮呼风。","风之声兮起颸颸，吹玄云兮散而浮。","望太靈兮儼而安，澹油溶兮都清闲。"]', '诗', 'shi', '', NULL, '演興四首 招太靈 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32a0cecf-b0fc-4415-8294-2c31f20d5f52', '演興四首 初祀', '演兴四首 初祀', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["山之乳兮葺太祠，木孫爲桷兮木母榱。","雲纓爲𣓍兮愚木栭，洞淵禪兮揭巍巍。","塗木蘭兮蒔糅蔫，被弱草兮禘礿聯。","仡渾洪兮馥闐闐，管化石兮洞刳天。","翹修釤兮掉蕪殳，靈巫𧮢兮舞顒干。","薦天𩷨兮酒陽泉，獻水芸兮飯霜秈，與太靈兮千萬年。"]', '["山之乳兮葺太祠，木孫爲桷兮木母榱。","云纓爲𣓍兮愚木栭，洞淵禪兮揭巍巍。","塗木蘭兮蒔糅蔫，被弱草兮禘礿聯。","仡渾洪兮馥闐闐，管化石兮洞刳天。","翹修釤兮掉蕪殳，靈巫𧮢兮舞顒干。","薦天𩷨兮酒陽泉，獻水芸兮飯霜秈，與太靈兮千万年。"]', '诗', 'shi', '', NULL, '演興四首 初祀 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8b5697a-7d05-4f21-9508-0577f5a0afcf', '演興四首 訟木魅', '演兴四首 訟木魅', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["登高峰兮俯幽谷，心悴悴兮念羣木。","見樗栲兮相陰覆，憐梫榕兮不豐茂。","見榛梗之森梢，閔樅橎兮合蠹。","槢橈橈兮未堅，椲桹桹兮可屈。","櫁林樽兮不香，拔丰茸兮已實。","豈元化之不均兮，非雨露之偏殊。","諒理性之不等於順時兮，不如瘞吾心以冥想。","終念此兮不怡，佁予莫識天地之意兮。","願截惡木之根，傾梟獍之古巢。","取囗童以爲薪，割大木使飛焰。","徯枯腐之燒焚，實非吾心之不仁惠也。","豈恥夫善惡之相紛，且欲畚三河之膏壤。","裨濟水之清漣，將封灌乎善木。","令橚橚以梴梴，尚畏乎衆善之未茂兮。","爲衆惡之所挑凌，思聚義以爲曹。","令敷扶以相勝，取方所以柯如兮。","吾將出於南荒，求壽藤與蟠木。","吾將出於東方，祈有德而來歸。","輔神檉與堅香，且憂顒之翩翩。","又愁㺠奔馳，及陰陽兮不和。","惡此土之失時，今神檉兮不茂。","使堅香兮不滋，重嗟惋兮何補。","每齊心以精意，切援祝於神明。","冀感通於天地，猶恐衆妖兮木魅。","魍魎兮山精，山誤惑於靈心。","經紿于言兮不聽，敢引佩以指水，誓吾心兮自明。"]', '["登高峰兮俯幽谷，心悴悴兮念羣木。","见樗栲兮相陰覆，怜梫榕兮不豐茂。","见榛梗之森梢，閔樅橎兮合蠹。","槢橈橈兮未堅，椲桹桹兮可屈。","櫁林樽兮不香，拔丰茸兮已實。","豈元化之不均兮，非雨露之偏殊。","諒理性之不等於順时兮，不如瘞吾心以冥想。","終念此兮不怡，佁予莫識天地之意兮。","願截惡木之根，傾梟獍之古巢。","取囗童以爲薪，割大木使飞焰。","徯枯腐之燒焚，實非吾心之不仁惠也。","豈恥夫善惡之相紛，且欲畚三河之膏壤。","裨濟水之清漣，將封灌乎善木。","令橚橚以梴梴，尚畏乎衆善之未茂兮。","爲衆惡之所挑凌，思聚義以爲曹。","令敷扶以相勝，取方所以柯如兮。","吾將出於南荒，求壽藤與蟠木。","吾將出於东方，祈有德而来归。","輔神檉與堅香，且憂顒之翩翩。","又愁㺠奔驰，及陰陽兮不和。","惡此土之失时，今神檉兮不茂。","使堅香兮不滋，重嗟惋兮何補。","每齊心以精意，切援祝於神明。","冀感通於天地，猶恐衆妖兮木魅。","魍魎兮山精，山誤惑於靈心。","經紿于言兮不听，敢引佩以指水，誓吾心兮自明。"]', '诗', 'shi', '', NULL, '演興四首 訟木魅 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a45108e0-a158-4982-875b-d2c52bb6868b', '演興四首 閔嶺中', '演兴四首 閔嶺中', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["囗羣山以延想，吾獨閔乎嶺中。","彼嶺中兮何有，有天含之玉峰。","殊閟絕之極顛，上聞產乎翠茸。","欲采之以將壽，眇不知夫所從。","大淵蘊蘊兮絕嶘岌岌，非梯梁以通險。","當無路兮可入，彼猛毒兮曹聚。","必憑託乎阻修，常儗儗兮伺人。","又如何兮不愁，彼妖精兮變怪。","必假見於風雨，常閃閃而伺人。","又如何兮不苦，欲仗仁兮託信。","將徑往兮不難，久懹懹以㥄惋。","却遲迴而永歎，懼大靈兮不知。","以予心爲永惟，若不可乎遂已。","吾終保夫直方，則必蒙皮篥以爲矢。","弦毋筱以爲弧，化毒銅以爲戟。","刺棘竹以爲殳，得猛烈之材。","獲與之而並驅，且舂刺乎惡毒。","又引射夫妖怪，盡羣類兮使無。","令善仁兮不害，然後采梫榕以駕深。","收樅橞兮梯險，躋予身之飄飄。","承予步之𨁹𨁹，入嶺中而登玉峰。","極閟絕而求翠茸，將吾壽兮隨所從。","思未得兮馬如龍，獨翳蔽於山顛。","久低迴而慍瘀，空仰訟於上玄。","彼至精兮必應，寧古有而今無。","將與身而皆亡，豈言之而已乎。"]', '["囗羣山以延想，吾独閔乎嶺中。","彼嶺中兮何有，有天含之玉峰。","殊閟絕之極顛，上闻產乎翠茸。","欲采之以將壽，眇不知夫所從。","大淵蘊蘊兮絕嶘岌岌，非梯梁以通險。","當無路兮可入，彼猛毒兮曹聚。","必憑託乎阻修，常儗儗兮伺人。","又如何兮不愁，彼妖精兮变怪。","必假见於风雨，常閃閃而伺人。","又如何兮不苦，欲仗仁兮託信。","將徑往兮不难，久懹懹以㥄惋。","却遲迴而永歎，懼大靈兮不知。","以予心爲永惟，若不可乎遂已。","吾終保夫直方，則必蒙皮篥以爲矢。","弦毋筱以爲弧，化毒銅以爲戟。","刺棘竹以爲殳，得猛烈之材。","獲與之而並驱，且舂刺乎惡毒。","又引射夫妖怪，尽羣類兮使無。","令善仁兮不害，然後采梫榕以駕深。","收樅橞兮梯險，躋予身之飄飄。","承予步之𨁹𨁹，入嶺中而登玉峰。","極閟絕而求翠茸，將吾壽兮隨所從。","思未得兮马如龙，独翳蔽於山顛。","久低迴而慍瘀，空仰訟於上玄。","彼至精兮必應，寧古有而今無。","將與身而皆亡，豈言之而已乎。"]', '诗', 'shi', '', NULL, '演興四首 閔嶺中 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dff2314f-d61f-4047-b361-4ef09d69caad', '閔荒詩一首', '閔荒诗一首', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["煬皇嗣君位，隋德滋昏幽。","日作及身禍，以爲長世謀。","居常恥前王，不思天子遊。","意欲出明堂，便登浮海舟。","令行山川改，功與玄造侔。","河淮可支合，峰𡻮生回溝。","封隕下澤中，作山防逸流。","船𦫃狀龍鷁，若負宮闕浮。","荒娛未央極，始到滄海頭。","忽見海門山，思作望海樓。","不知新都城，已爲征戰丘。","當時有遺歌，歌曲太冤愁。","四海非天獄，何爲非天囚。","天囚正凶忍，爲我萬姓讐。","人將引天釤，人將持天鎪。","所欲充其心，相與絕悲憂。","自得隋人歌，每爲隋君羞。","欲歌當陽春，似覺天下秋。","更歌曲未終，如有怨氣浮。","奈何昏王心，不覺此怨尤。","遂令一夫唱，四海欣提矛。","吾聞古賢君，其道常靜柔。","慈惠恐不足，端和忘所求。","嗟嗟有隋氏，惛惛誰與儔。"]', '["煬皇嗣君位，隋德滋昏幽。","日作及身禍，以爲长世謀。","居常恥前王，不思天子游。","意欲出明堂，便登浮海舟。","令行山川改，功與玄造侔。","河淮可支合，峰𡻮生回溝。","封隕下澤中，作山防逸流。","船𦫃狀龙鷁，若負宮闕浮。","荒娛未央極，始到滄海头。","忽见海门山，思作望海楼。","不知新都城，已爲征戰丘。","當时有遺歌，歌曲太冤愁。","四海非天獄，何爲非天囚。","天囚正凶忍，爲我万姓讐。","人將引天釤，人將持天鎪。","所欲充其心，相與絕悲憂。","自得隋人歌，每爲隋君羞。","欲歌當陽春，似覺天下秋。","更歌曲未終，如有怨氣浮。","奈何昏王心，不覺此怨尤。","遂令一夫唱，四海欣提矛。","吾闻古賢君，其道常静柔。","慈惠恐不足，端和忘所求。","嗟嗟有隋氏，惛惛誰與儔。"]', '诗', 'shi', '', NULL, '閔荒詩一首 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0ed1ba3-07a4-43a1-bb5f-6f987c1ae54c', '忝官引', '忝官引', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["天下昔無事，僻居養愚鈍。","山野性所安，熙然自全順。","忽逢暴兵起，閭巷見軍陣。","將家瀛海濱，自棄同芻糞。","往在乾元初，聖人啓休運。","公車詣魏闕，天子垂清問。","敢誦王者箴，亦獻當時論。","朝廷愛方直，明主嘉忠信。","屢授不次官，曾與專征印。","兵家未曾學，榮利非所徇。","偶得兇醜降，功勞媿方寸。","爾來將四歲，慙恥言可盡。","請取冤者辭，爲吾忝官引。","冤辭何者苦，萬邑餘灰燼。","冤辭何者悲，生人盡鋒刃。","冤辭何者甚，力役遇勞困。","冤辭何者深，孤弱亦哀恨。","無謀救冤者，祿位安可近。","而可愛軒裳，其心又干進。","此言非所戒，此言敢貽訓。","實欲辭無能，歸耕守吾分。"]', '["天下昔無事，僻居養愚鈍。","山野性所安，熙然自全順。","忽逢暴兵起，閭巷见軍陣。","將家瀛海濱，自棄同芻糞。","往在乾元初，聖人啓休運。","公车詣魏闕，天子垂清问。","敢誦王者箴，亦獻當时論。","朝廷愛方直，明主嘉忠信。","屢授不次官，曾與專征印。","兵家未曾学，榮利非所徇。","偶得兇醜降，功勞媿方寸。","爾来將四歲，慙恥言可尽。","請取冤者辞，爲吾忝官引。","冤辞何者苦，万邑餘灰燼。","冤辞何者悲，生人尽鋒刃。","冤辞何者甚，力役遇勞困。","冤辞何者深，孤弱亦哀恨。","無謀救冤者，祿位安可近。","而可愛軒裳，其心又干進。","此言非所戒，此言敢貽訓。","實欲辞無能，归耕守吾分。"]', '诗', 'shi', '', NULL, '忝官引 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70a9345f-ef55-49e7-bf2e-73f08951e9d4', '舂陵行', '舂陵行', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["軍國多所需，切責在有司。","有司臨郡縣，刑法競欲施。","供給豈不憂，徴斂又可悲。","州小經亂亡，遺人實困疲。","大鄉無十家，大族命單羸。","朝餐是草根，暮食仍木皮。","出言氣欲絕，意速行步遲。","追呼尚不忍，況乃鞭撲之。","郵亭傳急符，來往跡相追。","更無寬大恩，但有迫促期。","欲令鬻兒女，言發恐亂隨。","悉使索其家，而又無生資。","聽彼道路言，怨傷誰復知。","去冬山賊來，殺奪幾無遺。","所願見王官，撫養以惠慈。","奈何重驅逐，不使存活爲。","安人天子命，符節我所持。","州縣忽亂亡，得罪復是誰。","逋緩違詔令，蒙責固其宜。","前賢重守分，惡以禍福移。","亦云貴守官，不愛能適時。","顧惟孱弱者，正直當不虧。","何人采國風，吾欲獻此辭。"]', '["軍国多所需，切責在有司。","有司臨郡縣，刑法競欲施。","供給豈不憂，徴斂又可悲。","州小經亂亡，遺人實困疲。","大乡無十家，大族命單羸。","朝餐是草根，暮食仍木皮。","出言氣欲絕，意速行步遲。","追呼尚不忍，況乃鞭撲之。","郵亭傳急符，来往跡相追。","更無寬大恩，但有迫促期。","欲令鬻兒女，言發恐亂隨。","悉使索其家，而又無生資。","听彼道路言，怨傷誰复知。","去冬山賊来，殺奪幾無遺。","所願见王官，撫養以惠慈。","奈何重驱逐，不使存活爲。","安人天子命，符節我所持。","州縣忽亂亡，得罪复是誰。","逋緩違詔令，蒙責固其宜。","前賢重守分，惡以禍福移。","亦云貴守官，不愛能適时。","顧惟孱弱者，正直當不虧。","何人采国风，吾欲獻此辞。"]', '诗', 'shi', '', NULL, '舂陵行 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ce94bde-41ec-42b8-abef-e1e1be55be7c', '賊退示官吏', '賊退示官吏', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["昔歲逢太平，山林二十年。","泉源在庭戶，洞壑當門前。","井稅有常期，日[晏]猶得眠。","忽然遭世變，數歲親戎旃。","今來典斯郡，山夷又紛然。","城小賊不屠，人貧傷可憐。","是以陷隣境，此州獨見全。","使臣將王命，豈不如賊焉。","今彼徴斂者，迫之如火煎。","誰能絕人命，以作時世賢。","思欲委符節，引竿自刺船。","將家就魚麥，歸老江湖邊。"]', '["昔歲逢太平，山林二十年。","泉源在庭戶，洞壑當门前。","井稅有常期，日[晏]猶得眠。","忽然遭世变，數歲親戎旃。","今来典斯郡，山夷又紛然。","城小賊不屠，人貧傷可怜。","是以陷隣境，此州独见全。","使臣將王命，豈不如賊焉。","今彼徴斂者，迫之如火煎。","誰能絕人命，以作时世賢。","思欲委符節，引竿自刺船。","將家就鱼麦，归老江湖邊。"]', '诗', 'shi', '', NULL, '賊退示官吏 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71d967c8-59de-4234-971d-b79f9d8c7d8d', '寄源休', '寄源休', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["天下未偃兵，儒生預戎事。","功勞安可問，且有忝官累。","昔常以荒浪，不敢學爲吏。","況當在兵家，言之豈容易。","忽然向三嶺，境外爲偏帥。","時多尚矯詐，進退多欺貳。","縱有一直方，則上似姦智。","誰爲明信者，能辨此勞畏。"]', '["天下未偃兵，儒生預戎事。","功勞安可问，且有忝官累。","昔常以荒浪，不敢学爲吏。","況當在兵家，言之豈容易。","忽然向三嶺，境外爲偏帥。","时多尚矯詐，進退多欺貳。","縱有一直方，則上似姦智。","誰爲明信者，能辨此勞畏。"]', '诗', 'shi', '', NULL, '寄源休 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5d6d028-bd4e-4bd4-ad0e-95fa09027379', '雪中懷孟武昌', '雪中懷孟武昌', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["冬來三度雪，農者歡歲稔。","我麥根已濡，各得在倉廩。","天寒未能起，孺子驚人寢。","云有山客來，籃中見冬簟。","燒柴爲溫酒，煮鱖爲作瀋。","客亦愛桮尊，思君共桮飲。","所嗟山路閑，時節寒又甚。","不能苦相邀，興盡還就枕。"]', '["冬来三度雪，農者歡歲稔。","我麦根已濡，各得在倉廩。","天寒未能起，孺子驚人寢。","云有山客来，籃中见冬簟。","燒柴爲溫酒，煮鱖爲作瀋。","客亦愛桮尊，思君共桮饮。","所嗟山路闲，时節寒又甚。","不能苦相邀，兴尽還就枕。"]', '诗', 'shi', '', NULL, '雪中懷孟武昌 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62f02b7c-271e-40dc-bae5-d37bd604d87a', '與党評事', '與党評事', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["自顧無功勞，一歲官再遷。","跼身班次中，常竊媿恥焉。","加以久荒浪，惛愚性頗全。","未知在冠冕，不合無拘牽。","勤強所不及，於人或未然。","豈忘惠君子，恕之識見偏。","且欲因我心，順爲理化先。","彼云萬物情，有願隨所便。","愛君得自遂，令我空淵禪。"]', '["自顧無功勞，一歲官再遷。","跼身班次中，常竊媿恥焉。","加以久荒浪，惛愚性頗全。","未知在冠冕，不合無拘牽。","勤強所不及，於人或未然。","豈忘惠君子，恕之識见偏。","且欲因我心，順爲理化先。","彼云万物情，有願隨所便。","愛君得自遂，令我空淵禪。"]', '诗', 'shi', '', NULL, '與党評事 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1eb6703-a927-458a-aa4c-b9d6c1cbbf62', '與党侍御', '與党侍御', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["衆坐吾獨歡，或問歡爲誰。","高人党茂宗，復來官憲司。","昔吾順元和，與世行自遺。","茂宗正作吏，日有趨走疲。","及吾汙冠冕，茂宗方矯時。","誚吾順讓者，乃是干進資。","今將問茂宗，茂宗欲何辭。","若云吾無心，此來復何爲。","若云吾有羞，於此還見嗤。","誰言萬類心，閑之不可窺。","吾欲喻茂宗，茂宗宜聽之。","長轅有修轍，馭者令爾馳。","山谷安可怨，筋力當自悲。","嗟嗟党茂宗，可爲識者規。"]', '["衆坐吾独歡，或问歡爲誰。","高人党茂宗，复来官憲司。","昔吾順元和，與世行自遺。","茂宗正作吏，日有趨走疲。","及吾汙冠冕，茂宗方矯时。","誚吾順讓者，乃是干進資。","今將问茂宗，茂宗欲何辞。","若云吾無心，此来复何爲。","若云吾有羞，於此還见嗤。","誰言万類心，闲之不可窺。","吾欲喻茂宗，茂宗宜听之。","长轅有修轍，馭者令爾驰。","山谷安可怨，筋力當自悲。","嗟嗟党茂宗，可爲識者規。"]', '诗', 'shi', '', NULL, '與党侍御 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c5764dc-acd1-4d0b-b286-ee42f02fe138', '與瀼溪鄰里', '與瀼溪鄰里', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["昔年苦逆亂，舉族來南奔。","日行幾十里，愛君此山村。","峰谷呀回映，誰家無泉源。","修竹多夾路，扁舟皆到門。","瀼溪中曲濱，其陽有閑園。","鄰里昔贈我，許之及子孫。","我嘗有匱乏，鄰里能相分。","我嘗有不安，鄰里能相存。","斯人轉貧弱，力役非無冤。","終以瀼濱訟，無令天下論。"]', '["昔年苦逆亂，舉族来南奔。","日行幾十里，愛君此山村。","峰谷呀回映，誰家無泉源。","修竹多夾路，扁舟皆到门。","瀼溪中曲濱，其陽有闲园。","鄰里昔贈我，許之及子孫。","我嘗有匱乏，鄰里能相分。","我嘗有不安，鄰里能相存。","斯人轉貧弱，力役非無冤。","終以瀼濱訟，無令天下論。"]', '诗', 'shi', '', NULL, '與瀼溪鄰里 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46c03530-4479-4300-a884-aa4c01ea91a2', '招孟武昌', '招孟武昌', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["風霜枯萬物，退谷如春時。","窮冬涸江海，桮湖澄清漪。","湖盡到谷口，單船近堦墀。","湖中更何好，坐見大江水。","欹石爲水涯，半山在湖裏。","谷口更何好，絕壑流寒泉。","松桂蔭茅舍，白雲生坐邊。","武昌不干進，武昌人不厭。","退谷正可遊，桮湖任來泛。","湖上有水鳥，見人不飛鳴。","谷口有山獸，往往隨人行。","莫將車馬來，令我鳥獸驚。"]', '["风霜枯万物，退谷如春时。","窮冬涸江海，桮湖澄清漪。","湖尽到谷口，單船近堦墀。","湖中更何好，坐见大江水。","欹石爲水涯，半山在湖裏。","谷口更何好，絕壑流寒泉。","松桂蔭茅舍，白云生坐邊。","武昌不干進，武昌人不厭。","退谷正可游，桮湖任来泛。","湖上有水鸟，见人不飞鳴。","谷口有山獸，往往隨人行。","莫將车马来，令我鸟獸驚。"]', '诗', 'shi', '', NULL, '招孟武昌 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('003f1ce0-0730-4b63-8254-dcc5cb1f07af', '招陶別駕家陽華作', '招陶別駕家陽华作', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["海內厭兵革，騷騷十二年。","陽華洞中人，似不知亂焉。","誰能家此地，終老可自全。","草堂背巖洞，幾峰軒戶前。","清渠匝庭堂，出門仍灌田。","半崖盤石徑，高亭臨極巔。","引望見何處，迤逶隴北川。","杉松幾萬株，蒼蒼滿前山。","巖高瞹華陽，飛溜何潺潺。","洞深迷遠近，但覺多洄淵。","晝遊興未盡，日暮不欲眠。","探燭飲洞中，醉昏漱寒泉。","始知天下心，耽愛各有偏。","陶家世高逸，公忍不獨然。","無或畢婚嫁，竟爲俗務牽。"]', '["海內厭兵革，騷騷十二年。","陽华洞中人，似不知亂焉。","誰能家此地，終老可自全。","草堂背巖洞，幾峰軒戶前。","清渠匝庭堂，出门仍灌田。","半崖盤石徑，高亭臨極巔。","引望见何处，迤逶隴北川。","杉松幾万株，蒼蒼满前山。","巖高瞹华陽，飞溜何潺潺。","洞深迷远近，但覺多洄淵。","晝游兴未尽，日暮不欲眠。","探燭饮洞中，醉昏漱寒泉。","始知天下心，耽愛各有偏。","陶家世高逸，公忍不独然。","無或畢婚嫁，竟爲俗務牽。"]', '诗', 'shi', '', NULL, '招陶別駕家陽華作 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4da9f13e-bb20-4c1f-bbbe-002875780fe7', '遊石溪示學者', '游石溪示学者', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["小溪在城下，形勝堪賞愛。","尤宜春水滿，水石更殊怪。","長山勢迴合，井邑相縈帶。","石林繞舜祠，西南正相對。","階庭無爭訟，郊境罷守衛。","時時溪上來，勸引辭學輩。","今誰不務武，儒雅道將廢。","豈忘二三子，旦夕相勉勵。"]', '["小溪在城下，形勝堪賞愛。","尤宜春水满，水石更殊怪。","长山勢迴合，井邑相縈带。","石林繞舜祠，西南正相对。","階庭無爭訟，郊境罷守衛。","时时溪上来，勸引辞学輩。","今誰不務武，儒雅道將廢。","豈忘二三子，旦夕相勉勵。"]', '诗', 'shi', '', NULL, '遊石溪示學者 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d17336b-4ae9-4f78-95c2-587ef08a2b1f', '遊潓泉示泉上學者', '游潓泉示泉上学者', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["顧吾漫浪久，不欲有所拘。","每到潓泉上，情性可安舒。","草堂在山曲，澄瀾涵階除。","松竹陰幽徑，清源湧坐隅。","築塘列圃畦，引流灌時蔬。","復在郊郭外，正堪靜者居。","愜心則自適，喜尚人或殊。","此中若可安，不服銅虎符。"]', '["顧吾漫浪久，不欲有所拘。","每到潓泉上，情性可安舒。","草堂在山曲，澄瀾涵階除。","松竹陰幽徑，清源湧坐隅。","築塘列圃畦，引流灌时蔬。","复在郊郭外，正堪静者居。","愜心則自適，喜尚人或殊。","此中若可安，不服銅虎符。"]', '诗', 'shi', '', NULL, '遊潓泉示泉上學者 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a726b574-1dd4-405a-89bd-65de7eff48ec', '喻瀼溪鄉舊遊', '喻瀼溪乡旧游', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["往年在瀼濱，瀼人皆忘情。","今來遊瀼鄉，瀼人見我驚。","我心與瀼人，豈有辱與榮。","瀼人異其心，應爲我冠纓。","昔賢惡如此，所以辭公卿。","貧窮老鄉里，自休還力耕。","況曾經逆亂，日厭聞戰爭。","尤愛一溪水，而能存讓名。","終當來其濱，飲啄全此生。"]', '["往年在瀼濱，瀼人皆忘情。","今来游瀼乡，瀼人见我驚。","我心與瀼人，豈有辱與榮。","瀼人異其心，應爲我冠纓。","昔賢惡如此，所以辞公卿。","貧窮老乡里，自休還力耕。","況曾經逆亂，日厭闻戰爭。","尤愛一溪水，而能存讓名。","終當来其濱，饮啄全此生。"]', '诗', 'shi', '', NULL, '喻瀼溪鄉舊遊 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b7815a3-4caf-4ca1-ad20-ddc9a43c1861', '喻舊部曲', '喻旧部曲', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["漫遊樊水陰，忽見舊部曲。","尚言軍中好，猶望有所屬。","故令爭者心，至死終不足。","與之一桮酒，喻使燒戎服。","兵興向十年，所見堪歎哭。","相逢是遺人，當合識榮辱。","勸汝學全生，隨我畬退谷。"]', '["漫游樊水陰，忽见旧部曲。","尚言軍中好，猶望有所屬。","故令爭者心，至死終不足。","與之一桮酒，喻使燒戎服。","兵兴向十年，所见堪歎哭。","相逢是遺人，當合識榮辱。","勸汝学全生，隨我畬退谷。"]', '诗', 'shi', '', NULL, '喻舊部曲 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bed27c62-2af7-44cb-9323-1921228e336f', '喻常吾直', '喻常吾直', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["山澤多飢人，閭里多壞屋。","戰爭且未息，徴斂何時足。","不能救人患，不合食天粟。","何況假一官，而苟求其祿。","近年更長吏，數月未爲速。","來者罷而官，豈得不爲辱。","勸爲辭府主，從我遊退谷。","谷中有寒泉，爲爾洗塵服。"]', '["山澤多飢人，閭里多壞屋。","戰爭且未息，徴斂何时足。","不能救人患，不合食天粟。","何況假一官，而苟求其祿。","近年更长吏，數月未爲速。","来者罷而官，豈得不爲辱。","勸爲辞府主，從我游退谷。","谷中有寒泉，爲爾洗塵服。"]', '诗', 'shi', '', NULL, '喻常吾直 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('026e96c8-4a76-4b8c-8c06-d07cff6d8ea3', '漫問相里黃州', '漫问相里黄州', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["東鄰有漁父，西鄰有山僧。","各問其性情，變之俱不能。","公爲二千石，我爲山海客。","志業豈不同，今已殊名跡。","相里不相類，相友且相異。","何況天下人，而欲同其意。","人意苟不同，分寸不相容。","漫問軒裳客，何如耕釣翁。"]', '["东鄰有漁父，西鄰有山僧。","各问其性情，变之俱不能。","公爲二千石，我爲山海客。","志業豈不同，今已殊名跡。","相里不相類，相友且相異。","何況天下人，而欲同其意。","人意苟不同，分寸不相容。","漫问軒裳客，何如耕釣翁。"]', '诗', 'shi', '', NULL, '漫問相里黃州 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('402d45dc-7d64-4a0a-b731-79551c95ba91', '詶裴雲客', '詶裴云客', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["自厭久荒浪，於時無所任。","耕釣以爲事，來家樊水陰。","甚醉或漫歌，甚閑亦漫吟。","不知愚僻意，稱得雲客心。","雲客方持斧，與人正相臨。","符印隨坐起，守位常森森。","縱能有相招，豈暇來山林。"]', '["自厭久荒浪，於时無所任。","耕釣以爲事，来家樊水陰。","甚醉或漫歌，甚闲亦漫吟。","不知愚僻意，稱得云客心。","云客方持斧，與人正相臨。","符印隨坐起，守位常森森。","縱能有相招，豈暇来山林。"]', '诗', 'shi', '', NULL, '詶裴雲客 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05dda800-bd7b-43f0-b0f4-6edeafa87e5f', '酬孟武昌苦雪', '酬孟武昌苦雪', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["積[雪]閑山路，有人到庭前。","云是孟武昌，令獻苦雪篇。","長吟未及終，不覺爲淒然。","古之賢達者，與世竟何異。","不能救時患，諷諭以全意。","知公惜春物，豈非愛時和。","知公苦陰雪，傷彼災患多。","姦兇正驅馳，不合問君子。","林鶯與野獸，無乃怨於此。","兵興向九歲，稼穡誰能憂。","何時不發卒，何日不殺牛。","耕者日已少，耕牛日已希。","皇天復何忍，更又恐斃之。","自經危亂來，觸物堪傷歎。","見君問我意，只益胸中亂。","山禽飢不飛，山木凍皆折。","懸泉化爲冰，寒水近不熱。","出門望天地，天地皆昏昏。","時見雙峰下，雪中生白雲。"]', '["積[雪]闲山路，有人到庭前。","云是孟武昌，令獻苦雪篇。","长吟未及終，不覺爲淒然。","古之賢達者，與世竟何異。","不能救时患，諷諭以全意。","知公惜春物，豈非愛时和。","知公苦陰雪，傷彼災患多。","姦兇正驱驰，不合问君子。","林鶯與野獸，無乃怨於此。","兵兴向九歲，稼穡誰能憂。","何时不發卒，何日不殺牛。","耕者日已少，耕牛日已希。","皇天复何忍，更又恐斃之。","自經危亂来，觸物堪傷歎。","见君问我意，只益胸中亂。","山禽飢不飞，山木凍皆折。","懸泉化爲冰，寒水近不熱。","出门望天地，天地皆昏昏。","时见雙峰下，雪中生白云。"]', '诗', 'shi', '', NULL, '酬孟武昌苦雪 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc7dd19a-d828-4de2-98fe-74df8749af86', '漫酬賈沔州', '漫酬賈沔州', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["往年壯心在，嘗欲濟時難。","奉詔舉州兵，令得誅暴叛。","上將屢顛覆，偏師嘗救亂。","未曾弛戈甲，終日領簿案。","出入四五年，憂勞忘昏旦。","無謀靜兇醜，自覺愚且愞。","豈欲皁櫪中，爭食麧與藖。","去年辭職事，所懼貽憂患。","天子許安親，官又得閑散。","自家樊水上，性情尤荒慢。","雲山與水木，似不憎吾漫。","以茲忘時世，日益無畏憚。","漫醉人不嗔，漫眠人不喚。","漫遊無遠近，漫樂無早晏。","漫中漫亦忘，名利誰能算。","聞君勸我意，爲君一長歎。","人誰年八十，我已過其半。","家中孤弱子，長子未及冠。","且爲兒童主，種藥老谿澗。"]', '["往年壯心在，嘗欲濟时难。","奉詔舉州兵，令得誅暴叛。","上將屢顛覆，偏師嘗救亂。","未曾弛戈甲，終日領簿案。","出入四五年，憂勞忘昏旦。","無謀静兇醜，自覺愚且愞。","豈欲皁櫪中，爭食麧與藖。","去年辞職事，所懼貽憂患。","天子許安親，官又得闲散。","自家樊水上，性情尤荒慢。","云山與水木，似不憎吾漫。","以茲忘时世，日益無畏憚。","漫醉人不嗔，漫眠人不喚。","漫游無远近，漫乐無早晏。","漫中漫亦忘，名利誰能算。","闻君勸我意，爲君一长歎。","人誰年八十，我已過其半。","家中孤弱子，长子未及冠。","且爲兒童主，種藥老谿澗。"]', '诗', 'shi', '', NULL, '漫酬賈沔州 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaed3490-f5ca-49a9-ab8f-71f1076ecde7', '送孟校書往南海', '送孟校书往南海', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["吾聞近南海，乃是魑魅鄉。","忽見孟夫子，歡然遊此方。","忽喜海風來，海帆又欲張。","漂漂隨所去，不念歸路長。","君有失母兒，愛之似阿陽。","始解隨人行，不欲離君傍。","相勸早旋歸，此言慎勿忘。"]', '["吾闻近南海，乃是魑魅乡。","忽见孟夫子，歡然游此方。","忽喜海风来，海帆又欲張。","漂漂隨所去，不念归路长。","君有失母兒，愛之似阿陽。","始解隨人行，不欲離君傍。","相勸早旋归，此言慎勿忘。"]', '诗', 'shi', '', NULL, '送孟校書往南海 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9938bb6d-a473-47ef-85ab-593cdd20df75', '別何員外', '別何員外', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["誰能守清躅，誰能嗣世儒。","吾見何君饒，爲人有是夫。","黜官二十年，未曾暫崎嶇。","終不病貧賤，寥寥無所拘。","忽然逢知己，數月領官符。","猶是尚書郎，收賦來江湖。","人皆悉蒼生，隨意極所須。","比盜無兵甲，似偷又不如。","公能獨寬大，使之力自輸。","吾欲探時謠，爲公伏奏書。","但恐抵忌諱，未知肯聽無。","不然且相送，醉歡於坐隅。"]', '["誰能守清躅，誰能嗣世儒。","吾见何君饒，爲人有是夫。","黜官二十年，未曾暫崎嶇。","終不病貧賤，寥寥無所拘。","忽然逢知己，數月領官符。","猶是尚书郎，收賦来江湖。","人皆悉蒼生，隨意極所須。","比盜無兵甲，似偷又不如。","公能独寬大，使之力自輸。","吾欲探时謠，爲公伏奏书。","但恐抵忌諱，未知肯听無。","不然且相送，醉歡於坐隅。"]', '诗', 'shi', '', NULL, '別何員外 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c91f7e8-ba76-47bd-ac59-4233162a86a4', '宴湖上亭作', '宴湖上亭作', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["廣亭蓋小湖，湖亭實清曠。","軒窗幽水石，怪異尤難狀。","石尊能寒酒，寒水宜初漲。","岸曲坐客稀，桮浮上搖漾。","遠水入簾幕，淅[瀝]吹酒舫。","欲去未回時，飄飄正堪望。","酣興思共醉，促酒更相向。","舫去若驚鳧，溶瀛滿湖浪。","朝來暮忘返，暮歸獨惆悵。","誰肯愛林泉，從吾老湖上。"]', '["廣亭蓋小湖，湖亭實清曠。","軒窗幽水石，怪異尤难狀。","石尊能寒酒，寒水宜初漲。","岸曲坐客稀，桮浮上搖漾。","远水入簾幕，淅[瀝]吹酒舫。","欲去未回时，飄飄正堪望。","酣兴思共醉，促酒更相向。","舫去若驚鳧，溶瀛满湖浪。","朝来暮忘返，暮归独惆悵。","誰肯愛林泉，從吾老湖上。"]', '诗', 'shi', '', NULL, '宴湖上亭作 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1db1e6c-cd83-41be-888b-1b0b90fada97', '夜宴石魚湖作', '夜宴石鱼湖作', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["風霜雖慘然，出遊熙天正。","登臨日暮歸，置酒湖上亭。","高燭照泉深，光華溢軒楹。","如見海底日，曈曈始欲生。","夜寒閉窗戶，石溜何清泠。","若在深洞中，半崖聞水聲。","醉人疑舫影，呼指遞相驚。","何故有雙魚，隨吾酒舫行。","醉昏能誕語，勸醉能忘情。","坐無拘忌人，勿限醉與醒。"]', '["风霜雖慘然，出游熙天正。","登臨日暮归，置酒湖上亭。","高燭照泉深，光华溢軒楹。","如见海底日，曈曈始欲生。","夜寒閉窗戶，石溜何清泠。","若在深洞中，半崖闻水声。","醉人疑舫影，呼指遞相驚。","何故有雙鱼，隨吾酒舫行。","醉昏能誕語，勸醉能忘情。","坐無拘忌人，勿限醉與醒。"]', '诗', 'shi', '', NULL, '夜宴石魚湖作 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2285ba09-f9ff-4059-8767-5ecbd1564e9c', '劉侍御月夜讌會', '劉侍御月夜讌會', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["我從蒼梧來，將耕舊山田。","踟躕爲故人，且復停歸船。","日夕得相從，轉覺和樂全。","愚愛涼風來，明月正滿天。","河漢望不見，幾星猶粲然。","中夜興欲酣，改坐臨清川。","未醉恐天旦，更歌促繁弦。","歡娛不可逢，請君莫言旋。"]', '["我從蒼梧来，將耕旧山田。","踟躕爲故人，且复停归船。","日夕得相從，轉覺和乐全。","愚愛涼风来，明月正满天。","河漢望不见，幾星猶粲然。","中夜兴欲酣，改坐臨清川。","未醉恐天旦，更歌促繁弦。","歡娛不可逢，請君莫言旋。"]', '诗', 'shi', '', NULL, '劉侍御月夜讌會 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05766fb0-03b0-4a47-99f3-77c0328e8b12', '樊上漫作', '樊上漫作', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["漫家郎亭下，復在樊水邊。","去郭五六里，扁舟到門前。","山竹繞茅舍，庭中有寒泉。","西邊雙石峰，引望堪忘年。","四鄰皆漁父，近渚多閑田。","且欲學耕釣，於斯求老焉。"]', '["漫家郎亭下，复在樊水邊。","去郭五六里，扁舟到门前。","山竹繞茅舍，庭中有寒泉。","西邊雙石峰，引望堪忘年。","四鄰皆漁父，近渚多闲田。","且欲学耕釣，於斯求老焉。"]', '诗', 'shi', '', NULL, '樊上漫作 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbfa8be1-1e8f-467a-9fb4-d761158c4f69', '登殊亭作', '登殊亭作', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["時節方大暑，試來登殊亭。","憑軒未及息，忽若秋氣生。","主人既多閑，有酒共我傾。","坐中不相異，豈恨醉與醒。","漫歌無人聽，浪語無人驚。","時復一回望，心目出四溟。","誰能守纓佩，日與災患幷。","請君誦此意，令彼惑者聽。"]', '["时節方大暑，試来登殊亭。","憑軒未及息，忽若秋氣生。","主人既多闲，有酒共我傾。","坐中不相異，豈恨醉與醒。","漫歌無人听，浪語無人驚。","时复一回望，心目出四溟。","誰能守纓佩，日與災患幷。","請君誦此意，令彼惑者听。"]', '诗', 'shi', '', NULL, '登殊亭作 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b06bff50-6bb7-41ca-8381-ef41b3916169', '石魚湖上作', '石鱼湖上作', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["吾愛石魚湖，石魚在湖裏。","魚背有酒樽，繞魚是湖水。","兒童坐小舫，載酒勝一桮。","座中令酒舫，空去復滿來。","湖岸多欹石，石下流寒泉。","醉中一盥漱，快意無比焉。","金玉吾不須，軒冕吾不愛。","且欲坐湖畔，石魚長相對。"]', '["吾愛石鱼湖，石鱼在湖裏。","鱼背有酒樽，繞鱼是湖水。","兒童坐小舫，載酒勝一桮。","座中令酒舫，空去复满来。","湖岸多欹石，石下流寒泉。","醉中一盥漱，快意無比焉。","金玉吾不須，軒冕吾不愛。","且欲坐湖畔，石鱼长相对。"]', '诗', 'shi', '', NULL, '石魚湖上作 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e574bdd-9a0c-4eff-9be6-c135b92da944', '引東泉作', '引东泉作', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["東泉人未知，在我左山東。","引之傍山來，垂流落庭中。","宿霧含朝光，掩映如殘虹。","有時散成雨，飄灑隨清風。","衆源發淵竇，殊怪皆不同。","此流又高懸，{汸番}{汸番}在長空。","山林何處無，茲地不可逢。","吾欲解纓佩，便爲泉上翁。"]', '["东泉人未知，在我左山东。","引之傍山来，垂流落庭中。","宿霧含朝光，掩映如殘虹。","有时散成雨，飄灑隨清风。","衆源發淵竇，殊怪皆不同。","此流又高懸，{汸番}{汸番}在长空。","山林何处無，茲地不可逢。","吾欲解纓佩，便爲泉上翁。"]', '诗', 'shi', '', NULL, '引東泉作 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe939b59-a6d6-4460-b5d6-aa2f66de38c1', '登白雲亭', '登白云亭', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["出門見南山，喜逐松徑行。","窮高欲極遠，始到白雲亭。","長山繞井邑，登望宜新晴。","州渚曲湘水，縈迴隨郡城。","九疑千萬峰，嵺嵺天外青。","煙雲無遠近，皆傍林嶺生。","俯視松竹間，石水何幽清。","涵映滿軒戶，娟娟如鏡明。","何人病惛濃，積醉且未醒。","與我一登臨，爲君安性情。"]', '["出门见南山，喜逐松徑行。","窮高欲極远，始到白云亭。","长山繞井邑，登望宜新晴。","州渚曲湘水，縈迴隨郡城。","九疑千万峰，嵺嵺天外青。","煙云無远近，皆傍林嶺生。","俯視松竹间，石水何幽清。","涵映满軒戶，娟娟如镜明。","何人病惛濃，積醉且未醒。","與我一登臨，爲君安性情。"]', '诗', 'shi', '', NULL, '登白雲亭 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9b9a7fe-021b-4460-93f3-1e21f675b99f', '潓陽亭作', '潓陽亭作', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["問吾常讌息，泉上何處好。","獨有潓陽亭，令人可終老。","前軒臨潓泉，憑几漱清流。","外物自相擾，淵淵還復休。","有時出東戶，更欲簷下坐。","非我意不行，石渠能留我。","峰石若鱗次，欹垂復旋迴。","爲我引潓泉，泠泠簷下來。","天寒宜泉溫，泉寒宜天暑。","誰到潓陽亭，其心肯思去。"]', '["问吾常讌息，泉上何处好。","独有潓陽亭，令人可終老。","前軒臨潓泉，憑几漱清流。","外物自相擾，淵淵還复休。","有时出东戶，更欲簷下坐。","非我意不行，石渠能留我。","峰石若鱗次，欹垂复旋迴。","爲我引潓泉，泠泠簷下来。","天寒宜泉溫，泉寒宜天暑。","誰到潓陽亭，其心肯思去。"]', '诗', 'shi', '', NULL, '潓陽亭作 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a608d961-74ee-4db7-83b9-b5687a702d26', '登九疑第二峰', '登九疑第二峰', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["九疑第二峰，其上有仙壇。","杉松映飛泉，蒼蒼在雲端。","何人居此處，云是魯女冠。","不知幾百歲，燕坐餌金丹。","相傳羽化時，雲鶴滿峰巒。","婦中有高人，相望空長歎。"]', '["九疑第二峰，其上有仙壇。","杉松映飞泉，蒼蒼在云端。","何人居此处，云是魯女冠。","不知幾百歲，燕坐餌金丹。","相傳羽化时，云鹤满峰巒。","婦中有高人，相望空长歎。"]', '诗', 'shi', '', NULL, '登九疑第二峰 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8507a4df-995b-4ba7-b026-58011fa4cf69', '題孟中丞茅閣', '題孟中丞茅閣', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["小山爲郡城，隨水能縈紆。","亭亭最高處，今是西南隅。","杉大老猶在，蒼蒼數十株。","垂陰滿城上，枝葉何扶疎。","乃知四海中，遺事誰謂無。","及觀茅閣成，始覺形勝殊。","憑軒望熊湘，雲榭連蒼梧。","天下正炎熱，此然冰雪俱。","客有在中坐，頌歌復何如。","公欲舉遺材，如此佳木歟。","公方庇蒼生，又如斯閣乎。","請達謠頌聲，願公且踟躕。"]', '["小山爲郡城，隨水能縈紆。","亭亭最高处，今是西南隅。","杉大老猶在，蒼蒼數十株。","垂陰满城上，枝葉何扶疎。","乃知四海中，遺事誰謂無。","及观茅閣成，始覺形勝殊。","憑軒望熊湘，云榭連蒼梧。","天下正炎熱，此然冰雪俱。","客有在中坐，頌歌复何如。","公欲舉遺材，如此佳木歟。","公方庇蒼生，又如斯閣乎。","請達謠頌声，願公且踟躕。"]', '诗', 'shi', '', NULL, '題孟中丞茅閣 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('973ff843-3249-4773-9dc6-5ea401a75d33', '窊尊詩', '窊尊诗', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["巉巉小山石，數峰對窊亭。","窊石堪爲樽，狀類不可名。","巡迴數尺間，如見小蓬瀛。","尊中酒初漲，始有島嶼生。","豈無日觀峰，直下臨滄溟。","愛之不覺醉，醉臥還自醒。","醒醉在尊畔，始爲吾性情。","若以形勝論，坐隅臨郡城。","平湖近階砌，近山復青青。","異木幾十株，林條冒簷楹。","盤根滿石上，皆作龍蛇形。","酒堂貯釀器，戶牖皆罌缾。","此尊可常滿，誰是陶淵明。"]', '["巉巉小山石，數峰对窊亭。","窊石堪爲樽，狀類不可名。","巡迴數尺间，如见小蓬瀛。","尊中酒初漲，始有島嶼生。","豈無日观峰，直下臨滄溟。","愛之不覺醉，醉臥還自醒。","醒醉在尊畔，始爲吾性情。","若以形勝論，坐隅臨郡城。","平湖近階砌，近山复青青。","異木幾十株，林條冒簷楹。","盤根满石上，皆作龙蛇形。","酒堂貯釀器，戶牖皆罌缾。","此尊可常满，誰是陶淵明。"]', '诗', 'shi', '', NULL, '窊尊詩 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd6566e5-d270-4f8f-b728-1d1caf612932', '朝陽巖下歌', '朝陽巖下歌', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["朝陽巖下湘水深，朝陽洞口寒泉清。","零陵城郭夾湘岸，巖洞幽奇帶郡城。","荒蕪自古人不見，零陵徒有先賢傳。","水石爲娛安可羨，長歌一曲留相勸。"]', '["朝陽巖下湘水深，朝陽洞口寒泉清。","零陵城郭夾湘岸，巖洞幽奇带郡城。","荒蕪自古人不见，零陵徒有先賢傳。","水石爲娛安可羨，长歌一曲留相勸。"]', '诗', 'shi', '', NULL, '朝陽巖下歌 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f87dae1d-ff4d-4bfe-bd72-5537690b2242', '無爲洞口作', '無爲洞口作', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["無爲洞口春水滿，無爲洞傍春雲白。","愛此踟躕不能去，令人悔作衣冠客。","洞傍山僧皆學禪，無求無欲亦忘年。","欲問其心不能問，我到山中得無悶。"]', '["無爲洞口春水满，無爲洞傍春云白。","愛此踟躕不能去，令人悔作衣冠客。","洞傍山僧皆学禪，無求無欲亦忘年。","欲问其心不能问，我到山中得無悶。"]', '诗', 'shi', '', NULL, '無爲洞口作 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27d1ca25-fd7f-4df5-b442-c7a3a88b1865', '宿無爲觀', '宿無爲观', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["九疑山深幾千里，峰谷崎嶇人不到。","山中舊有仙姥家，十里飛泉遶丹竈。","如今道士三四人，茹芝鍊玉學輕身。","霓裳羽蓋傍臨壑，飄颻似欲來雲鶴。"]', '["九疑山深幾千里，峰谷崎嶇人不到。","山中旧有仙姥家，十里飞泉遶丹竈。","如今道士三四人，茹芝鍊玉学轻身。","霓裳羽蓋傍臨壑，飄颻似欲来云鹤。"]', '诗', 'shi', '', NULL, '宿無爲觀 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56443d34-cb16-4ab9-ab21-87e5b005d71a', '宿洄溪翁宅', '宿洄溪翁宅', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["長松萬株遶茅舍，怪石寒泉近巖下。","老翁八十猶能行，將領兒孫行拾稼。","吾羨老翁居處幽，吾愛老翁無所求。","時俗是非何足道，得似老翁吾即休。"]', '["长松万株遶茅舍，怪石寒泉近巖下。","老翁八十猶能行，將領兒孫行拾稼。","吾羨老翁居处幽，吾愛老翁無所求。","时俗是非何足道，得似老翁吾即休。"]', '诗', 'shi', '', NULL, '宿洄溪翁宅 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2d84f66-1a8b-4780-aa15-84c95ab8c2a9', '說洄溪招退者', '说洄溪招退者', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["長松亭亭滿四山，山間乳竇流清泉。","洄溪正在此山裏，乳水松膏常灌田。","松膏乳水田肥良，稻苗如蒲米粒長。","糜色如珈玉液酒，酒熟猶聞松節香。","溪邊老翁年幾許，長男頭白孫嫁女。","問言只食松田米，無藥無方向人語。","浯溪石下多泉源，盛暑大寒冬大溫。","屠蘇宜在水中石，洄溪一曲自當門。","吾今欲作洄溪翁，誰能住我舍西東。","勿憚山深與地僻，羅浮尚有葛仙翁。"]', '["长松亭亭满四山，山间乳竇流清泉。","洄溪正在此山裏，乳水松膏常灌田。","松膏乳水田肥良，稻苗如蒲米粒长。","糜色如珈玉液酒，酒熟猶闻松節香。","溪邊老翁年幾許，长男头白孫嫁女。","问言只食松田米，無藥無方向人語。","浯溪石下多泉源，盛暑大寒冬大溫。","屠蘇宜在水中石，洄溪一曲自當门。","吾今欲作洄溪翁，誰能住我舍西东。","勿憚山深與地僻，羅浮尚有葛仙翁。"]', '诗', 'shi', '', NULL, '說洄溪招退者 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18f86499-351b-42bd-90d6-45436c1a5f21', '宿丹崖翁宅', '宿丹崖翁宅', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["扁舟欲到瀧口湍，春水湍瀧上水難。","投竿來泊丹崖下，得與崖翁盡一歡。","丹崖之亭當石顛，破竹半山引寒泉。","泉流掩映在木杪，有若白鳥飛林間。","往往隨風作霧雨，濕人巾履滿庭前。","丹崖翁，愛丹崖，棄官幾年崖下家。","兒孫棹船抱酒甕，醉裏長歌揮釣車。","吾將求退與翁遊，學翁歌醉在魚舟。","官吏隨人往未得，却望丹崖慙復羞。"]', '["扁舟欲到瀧口湍，春水湍瀧上水难。","投竿来泊丹崖下，得與崖翁尽一歡。","丹崖之亭當石顛，破竹半山引寒泉。","泉流掩映在木杪，有若白鸟飞林间。","往往隨风作霧雨，濕人巾履满庭前。","丹崖翁，愛丹崖，棄官幾年崖下家。","兒孫棹船抱酒甕，醉裏长歌揮釣车。","吾將求退與翁游，学翁歌醉在鱼舟。","官吏隨人往未得，却望丹崖慙复羞。"]', '诗', 'shi', '', NULL, '宿丹崖翁宅 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8af643c9-a8b0-49b7-b8e9-88920ab0bbd8', '石魚湖上醉歌', '石鱼湖上醉歌', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["石魚湖，似洞庭，夏水欲滿君山青。","山爲樽，水爲沼，酒徒歷歷坐洲島。","長風連日作大浪，不能廢人運酒舫。","我持長瓢坐巴丘，酌飲四坐以散愁。"]', '["石鱼湖，似洞庭，夏水欲满君山青。","山爲樽，水爲沼，酒徒歷歷坐洲島。","长风連日作大浪，不能廢人運酒舫。","我持长瓢坐巴丘，酌饮四坐以散愁。"]', '诗', 'shi', '', NULL, '石魚湖上醉歌 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a35aca1e-b114-43f9-b3ef-60f276460fbe', '橘井', '橘井', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["靈橘無根井有泉，世間如夢又千年。","鄉園不見重歸鶴，姓字今爲第幾仙。","風[泠]露壇人悄悄，地閑荒徑草綿綿。","如何躡得蘇君跡，白日霓旌擁上天。"]', '["靈橘無根井有泉，世间如梦又千年。","乡园不见重归鹤，姓字今爲第幾仙。","风[泠]露壇人悄悄，地闲荒徑草綿綿。","如何躡得蘇君跡，白日霓旌擁上天。"]', '诗', 'shi', '', NULL, '橘井 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab39fe05-ff7b-4e2a-afaa-c064c943f9b2', '石宮四詠 一', '石宮四詠 一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["石宮春雲白，白雲宜蒼苔。","拂雲踐石徑，俗士誰能來。"]', '["石宮春云白，白云宜蒼苔。","拂云踐石徑，俗士誰能来。"]', '诗', 'shi', '', NULL, '石宮四詠 一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b4f2085-e64e-4cbe-812c-48267789e2f8', '石宮四詠 二', '石宮四詠 二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["石宮夏水寒，寒水宜高林。","遠風吹蘿蔓，野客熙清陰。"]', '["石宮夏水寒，寒水宜高林。","远风吹蘿蔓，野客熙清陰。"]', '诗', 'shi', '', NULL, '石宮四詠 二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f913afb-aba1-4188-a0bb-6cd4eb41b45a', '石宮四詠 三', '石宮四詠 三', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["石宮秋氣清，清氣宜山谷。","落葉逐霜風，幽人愛松竹。"]', '["石宮秋氣清，清氣宜山谷。","落葉逐霜风，幽人愛松竹。"]', '诗', 'shi', '', NULL, '石宮四詠 三 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3762be96-0fc5-4f02-86ee-c436b45777d3', '石宮四詠 四', '石宮四詠 四', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["石宮冬日煖，煖日宜溫泉。","晨光靜水霧，逸者猶安眠。"]', '["石宮冬日煖，煖日宜溫泉。","晨光静水霧，逸者猶安眠。"]', '诗', 'shi', '', NULL, '石宮四詠 四 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97b3b7ab-d951-4223-8b87-db0511992cd5', '欸乃曲五首 一', '欸乃曲五首 一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["偶存名跡在人間，順俗與時未安閑。","來謁大官兼問政，扁舟却入九疑山。"]', '["偶存名跡在人间，順俗與时未安闲。","来謁大官兼问政，扁舟却入九疑山。"]', '诗', 'shi', '', NULL, '欸乃曲五首 一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28b0c472-6417-4d62-b24e-ad9332d1f453', '欸乃曲五首 二', '欸乃曲五首 二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["湘江二月春水平，滿月和風宜夜行。","唱橈欲過平陽戍，守吏相呼問姓名。"]', '["湘江二月春水平，满月和风宜夜行。","唱橈欲過平陽戍，守吏相呼问姓名。"]', '诗', 'shi', '', NULL, '欸乃曲五首 二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4883ae05-25e9-430c-8f05-31a773c50032', '欸乃曲五首 三', '欸乃曲五首 三', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["千里楓林煙雨深，無朝無暮有猨吟。","停橈靜聽曲中意，好是雲山韶濩音。"]', '["千里楓林煙雨深，無朝無暮有猨吟。","停橈静听曲中意，好是云山韶濩音。"]', '诗', 'shi', '', NULL, '欸乃曲五首 三 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64fd365f-f13a-4771-aa8e-34608d876bc2', '欸乃曲五首 四', '欸乃曲五首 四', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["零陵郡北湘水東，浯溪形勝滿湘中。","溪口石顛堪自逸，誰能相伴作漁翁。"]', '["零陵郡北湘水东，浯溪形勝满湘中。","溪口石顛堪自逸，誰能相伴作漁翁。"]', '诗', 'shi', '', NULL, '欸乃曲五首 四 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b936eede-f4f1-452b-9e76-36296458d3ff', '欸乃曲五首 五', '欸乃曲五首 五', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["下瀧船似入深淵，上瀧船似欲昇天。","瀧南始到九疑郡，應絕高人乘興船。"]', '["下瀧船似入深淵，上瀧船似欲昇天。","瀧南始到九疑郡，應絕高人乘兴船。"]', '诗', 'shi', '', NULL, '欸乃曲五首 五 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a45549d8-eb02-40aa-a886-6931685485b7', '郢城西樓吟', '郢城西楼吟', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["連山盡塞水縈迴，山上戍門臨水開。","珠簾直下一百丈，日暖遊鱗自相向。","昔人愛險閉層城，今人復愛閑江清。","沙洲楓岸無來客，草綠花開山鳥鳴。"]', '["連山尽塞水縈迴，山上戍门臨水开。","珠簾直下一百丈，日暖游鱗自相向。","昔人愛險閉層城，今人复愛闲江清。","沙洲楓岸無来客，草綠花开山鸟鳴。"]', '诗', 'shi', '', NULL, '郢城西樓吟 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cd07518-64b9-42ea-9712-9f2ad7b621c6', '登丹陽樓', '登丹陽楼', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["寒臯那可望，旅客又初還。","迢遰高樓上，蕭疎涼野間。","暮晴依遠水，秋興屬連山。","浮客時相見，霜彫朱翠顏。"]', '["寒臯那可望，旅客又初還。","迢遰高楼上，蕭疎涼野间。","暮晴依远水，秋兴屬連山。","浮客时相见，霜彫朱翠顏。"]', '诗', 'shi', '', NULL, '登丹陽樓 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94a669b6-d2e4-4411-b892-d65089ae39ee', '春夜皇甫冉宅歡宴', '春夜皇甫冉宅歡宴', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["流落時相見，悲歡共此情。","興因尊酒洽，愁爲故人輕。","暗滴花莖露，斜暉月過城。","那知橫吹笛，江外作邊聲。"]', '["流落时相见，悲歡共此情。","兴因尊酒洽，愁爲故人轻。","暗滴花莖露，斜暉月過城。","那知橫吹笛，江外作邊声。"]', '诗', 'shi', '', NULL, '春夜皇甫冉宅歡宴 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e43130c5-2867-4e65-bba6-25f689b13576', '會稽秋晚奉呈于太守', '會稽秋晚奉呈于太守', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["寂寂訟庭幽，森森戟戶秋。","山光隱危堞，湖色上高樓。","禹穴探書罷，天台作賦遊。","雲浮將越客，歲晚共淹留。"]', '["寂寂訟庭幽，森森戟戶秋。","山光隐危堞，湖色上高楼。","禹穴探书罷，天台作賦游。","云浮將越客，歲晚共淹留。"]', '诗', 'shi', '', NULL, '會稽秋晚奉呈于太守 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('900be949-2749-4c74-a8d1-532e99efa64f', '題嚴陵釣臺', '題嚴陵釣台', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["舊隱人如在，清風亦似秋。","客星沈夜壑，釣石俯春流。","鳥向喬枝聚，魚依淺瀨遊。","古來芳餌下，誰是不吞鉤。"]', '["旧隐人如在，清风亦似秋。","客星沈夜壑，釣石俯春流。","鸟向喬枝聚，鱼依淺瀨游。","古来芳餌下，誰是不吞鉤。"]', '诗', 'shi', '', NULL, '題嚴陵釣臺 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55b05ee5-c0de-46ce-8265-ec644b42ec4c', '清明日自西午橋至瓜巖村有懷', '清明日自西午橋至瓜巖村有懷', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["晚霽龍門雨，春生汝穴風。","鳥啼官路靜，花發毀垣空。","鳴玉慙時輩，垂絲學老翁。","舊遊人不見，惆悵洛城東。"]', '["晚霽龙门雨，春生汝穴风。","鸟啼官路静，花發毀垣空。","鳴玉慙时輩，垂絲学老翁。","旧游人不见，惆悵洛城东。"]', '诗', 'shi', '', NULL, '清明日自西午橋至瓜巖村有懷 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5f74cd1-e8a6-4018-9367-2b57c1447ef2', '洛陽作', '洛陽作', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["洛陽天子縣，金谷石崇鄉。","草色侵官道，花枝出苑牆。","書成休逐客，賦罷遂爲郎。","貧賤非吾事，西遊思自強。"]', '["洛陽天子縣，金谷石崇乡。","草色侵官道，花枝出苑牆。","书成休逐客，賦罷遂爲郎。","貧賤非吾事，西游思自強。"]', '诗', 'shi', '', NULL, '洛陽作 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85260447-8d31-45e4-ab91-1cfd4b3972d7', '晚次淮陽', '晚次淮陽', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["微涼風葉下，楚俗轉清閑。","候館臨秋水，郊扉掩暮山。","月明潮漸近，露濕雁初還。","浮客了無定，萍流淮海間。"]', '["微涼风葉下，楚俗轉清闲。","候館臨秋水，郊扉掩暮山。","月明潮漸近，露濕雁初還。","浮客了無定，萍流淮海间。"]', '诗', 'shi', '', NULL, '晚次淮陽 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8304ab24-253c-401b-8bf4-37266799553f', '送竇十九判官使江南', '送竇十九判官使江南', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["遊客淹星紀，裁詩鍊土風。","今看乘傳去，那與問津同。","南郡迎徐子，臨川謁謝公。","思歸一惆悵，於越古亭中。"]', '["游客淹星紀，裁诗鍊土风。","今看乘傳去，那與问津同。","南郡迎徐子，臨川謁謝公。","思归一惆悵，於越古亭中。"]', '诗', 'shi', '', NULL, '送竇十九判官使江南 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10cd87b1-fae0-4741-b32e-140d49041c4f', '江上送客遊廬山', '江上送客游廬山', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["楚客自相送，霑裳春水邊。","晚來風信好，併發上江船。","花映新林岸，雲開瀑布泉。","愜心應在此，佳句向誰傳。"]', '["楚客自相送，霑裳春水邊。","晚来风信好，併發上江船。","花映新林岸，云开瀑布泉。","愜心應在此，佳句向誰傳。"]', '诗', 'shi', '', NULL, '江上送客遊廬山 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e621e1c0-04bc-4870-89e7-7936572f2929', '酬張二十員外前國子博士竇叔向', '酬張二十員外前国子博士竇叔向', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["故交日零落，心賞寄何人。","幸與馮唐遇，心同跡復親。","語言未終夕，離別又傷春。","結念湓城下，聞猨詩興新。"]', '["故交日零落，心賞寄何人。","幸與馮唐遇，心同跡复親。","語言未終夕，離別又傷春。","結念湓城下，闻猨诗兴新。"]', '诗', 'shi', '', NULL, '酬張二十員外前國子博士竇叔向 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff93ce4f-fb1c-4295-9e35-b6fc630bff5d', '會稽郡樓雪霽', '會稽郡楼雪霽', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["江城昨夜雪如花，郢客登樓齊望華。","夏禹壇前仍聚玉，西施浦上更飛沙。","簾櫳向晚寒風度，睥睨初晴落景斜。","數處微明銷不盡，湖山清映越人家。"]', '["江城昨夜雪如花，郢客登楼齊望华。","夏禹壇前仍聚玉，西施浦上更飞沙。","簾櫳向晚寒风度，睥睨初晴落景斜。","數处微明銷不尽，湖山清映越人家。"]', '诗', 'shi', '', NULL, '會稽郡樓雪霽 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c0cb286-827a-4a68-8d6d-1f6b986645ac', '馮翊西樓', '馮翊西楼', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["城上西樓倚暮天，樓中歸望正淒然。","近郭亂山橫古渡，野莊喬木帶新烟。","北風吹雁聲能苦，遠客辭家月再圓。","陶令好文常對酒，相招那惜醉爲眠。"]', '["城上西楼倚暮天，楼中归望正淒然。","近郭亂山橫古渡，野莊喬木带新烟。","北风吹雁声能苦，远客辞家月再圓。","陶令好文常对酒，相招那惜醉爲眠。"]', '诗', 'shi', '', NULL, '馮翊西樓 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d926ce6f-a80f-40e2-b740-242f9ea05735', '送鄒判官往陳留', '送鄒判官往陳留', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["齊宋傷心地，頻年此用兵。","女停襄邑杼，農廢汶陽耕。","國使乘軺去，諸侯擁節迎。","深仁荷君子，薄賦恤黎甿。","火燎原猶熱，波搖海未平。","應將否泰理，一問魯諸生。"]', '["齊宋傷心地，頻年此用兵。","女停襄邑杼，農廢汶陽耕。","国使乘軺去，諸侯擁節迎。","深仁荷君子，薄賦恤黎甿。","火燎原猶熱，波搖海未平。","應將否泰理，一问魯諸生。"]', '诗', 'shi', '', NULL, '送鄒判官往陳留 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('844ec228-a176-473b-bd71-09b4dd21c294', '酬李書記校書越城秋夜見贈', '酬李书記校书越城秋夜见贈', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["東越秋城夜，西人白髮年。","寒城警刁斗，孤憤抱龍泉。","鳳輦棲岐下，鯨波鬬洛川。","量空海陵粟，賜乏水衡錢。","投閣嗤揚子，飛書代魯連。","蒼蒼不可問，余亦賦思玄。"]', '["东越秋城夜，西人白髮年。","寒城警刁斗，孤憤抱龙泉。","鳳輦棲岐下，鯨波鬬洛川。","量空海陵粟，賜乏水衡錢。","投閣嗤揚子，飞书代魯連。","蒼蒼不可问，余亦賦思玄。"]', '诗', 'shi', '', NULL, '酬李書記校書越城秋夜見贈 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43ba68f8-c518-49e0-8f27-77e8ffabc5e5', '感懷', '感懷', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["調與時人背，心將靜者論。","終年帝城裏，不識五侯門。"]', '["調與时人背，心將静者論。","終年帝城裏，不識五侯门。"]', '诗', 'shi', '', NULL, '感懷 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91291a8c-47e3-4a46-9e15-6c27b10e8fff', '長相思', '长相思', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["遼陽望河縣，白首無由見。","海上珊瑚枝，年年寄春燕。"]', '["遼陽望河縣，白首無由见。","海上珊瑚枝，年年寄春燕。"]', '诗', 'shi', '', NULL, '長相思 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a59763dd-5f7d-4638-9cf2-7602de1c7945', '奉寄皇甫補闕', '奉寄皇甫補闕', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["京口情人別久，揚州估客來疎。","潮至潯陽回去，相思無處通書。"]', '["京口情人別久，揚州估客来疎。","潮至潯陽回去，相思無处通书。"]', '诗', 'shi', '', NULL, '奉寄皇甫補闕 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cda5a92-ffa2-4af0-9217-97ce36113705', '楓橋夜泊', '楓橋夜泊', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["月落烏啼霜滿天，江楓漁父對愁眠。","姑蘇城外寒山寺，夜半鐘聲到客船。"]', '["月落烏啼霜满天，江楓漁父对愁眠。","姑蘇城外寒山寺，夜半鐘声到客船。"]', '诗', 'shi', '', NULL, '楓橋夜泊 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9942866-5b89-4e55-9d2e-9f3dea01aa2f', '閶門即事', '閶门即事', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["耕夫召募逐樓船，春草青青萬頃田。","試上吳門窺郡郭，清明幾處有新煙。"]', '["耕夫召募逐楼船，春草青青万頃田。","試上吳门窺郡郭，清明幾处有新煙。"]', '诗', 'shi', '', NULL, '閶門即事 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea3f7ed0-3704-4ff2-aa5e-1727b20e3a7c', '安公房問法', '安公房问法', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["流年一日復一日，世事何時是了時。","試向東林問禪伯，遣將心地學琉璃。"]', '["流年一日复一日，世事何时是了时。","試向东林问禪伯，遣將心地学琉璃。"]', '诗', 'shi', '', NULL, '安公房問法 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3830974-b0c2-41cb-8682-8e519d571754', '上清詞', '上清词', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["紫陽宮女捧丹砂，王母令過漢帝家。","春風不肯停仙馭，却向蓬萊看杏花。"]', '["紫陽宮女捧丹砂，王母令過漢帝家。","春风不肯停仙馭，却向蓬萊看杏花。"]', '诗', 'shi', '', NULL, '上清詞 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a9c46cb-b60d-439c-885e-c4dc8522940f', '送顧況泗上覲叔父', '送顧況泗上覲叔父', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["吳鄉歲貢足嘉賓，後進之中見此人。","別業更臨洙泗上，擬將書卷對殘春。"]', '["吳乡歲貢足嘉賓，後進之中见此人。","別業更臨洙泗上，擬將书卷对殘春。"]', '诗', 'shi', '', NULL, '送顧況泗上覲叔父 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31f400e2-15f2-42d3-a337-51ee398fe760', '留別', '留別', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["何事千年遇聖君，坐令雙鬢老江雲。","南行更入山深淺，岐路悠悠水自分。"]', '["何事千年遇聖君，坐令雙鬢老江云。","南行更入山深淺，岐路悠悠水自分。"]', '诗', 'shi', '', NULL, '留別 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ddba990-be61-4c15-8acc-5cfa2ad30d80', '送張中丞歸使幕', '送張中丞归使幕', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["獨受主恩歸，當朝似者稀。","玉壺分御酒，金殿賜春衣。","拂席流鶯醉，鳴鞭駿馬肥。","滿臺簪白筆，捧手戀清輝。"]', '["独受主恩归，當朝似者稀。","玉壺分御酒，金殿賜春衣。","拂席流鶯醉，鳴鞭駿马肥。","满台簪白笔，捧手戀清輝。"]', '诗', 'shi', '', NULL, '送張中丞歸使幕 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a91dc5b-5b7b-44f8-ba5b-e426951e84f5', '華州夜宴庾侍御宅', '华州夜宴庾侍御宅', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["世故他年別，心期此夜同。","千峰孤燭外，片雨一更中。","酒客逢山簡，詩人得謝公。","自憐驅匹馬，拂曙向關東。"]', '["世故他年別，心期此夜同。","千峰孤燭外，片雨一更中。","酒客逢山簡，诗人得謝公。","自怜驱匹马，拂曙向关东。"]', '诗', 'shi', '', NULL, '華州夜宴庾侍御宅 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dd18e2a-6500-4f6a-8361-ef2413521581', '贈章八元', '贈章八元', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["相見談經史，江樓坐夜闌。","風聲吹戶響，燈影照人寒。","俗薄交游盡，時危出處難。","衰年逢二妙，亦得悶懷寬。"]', '["相见談經史，江楼坐夜闌。","风声吹戶响，灯影照人寒。","俗薄交游尽，时危出处难。","衰年逢二妙，亦得悶懷寬。"]', '诗', 'shi', '', NULL, '贈章八元 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aca6f047-eeed-483f-8d9f-9c83f4f00a7b', '城西虎跑寺', '城西虎跑寺', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["石勢虎蹲伏，山形龍屈盤。","寺開梁殿閣，墳掩晉衣冠。","出澗泉聲細，斜陽塔影寒。","近城多囗囗，棲息此中安。"]', '["石勢虎蹲伏，山形龙屈盤。","寺开梁殿閣，墳掩晉衣冠。","出澗泉声細，斜陽塔影寒。","近城多囗囗，棲息此中安。"]', '诗', 'shi', '', NULL, '城西虎跑寺 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce5a5c50-315f-4168-8918-f9ddbbe533a2', '禇主簿宅會畢庶子錢員外郎使君', '禇主簿宅會畢庶子錢員外郎使君', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["開甕臘酒熟，主人心賞同。","斜陽疎竹上，殘雪亂山中。","更喜宣城印，朝廷與謝公。"]', '["开甕臘酒熟，主人心賞同。","斜陽疎竹上，殘雪亂山中。","更喜宣城印，朝廷與謝公。"]', '诗', 'shi', '', NULL, '禇主簿宅會畢庶子錢員外郎使君 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4035127-0cb0-4e48-a911-a3562f2dab57', '奉送王相公赴幽州', '奉送王相公赴幽州', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["黃閣開幃幄，丹墀拜冕旒。","位高湯左相，權總漢諸侯。","不改周南化，仍分趙北憂。","雙旌過易水，千騎入幽州。","塞草連天幕，邊風動地愁。","無因隨遠道，結束佩吳鉤。"]', '["黄閣开幃幄，丹墀拜冕旒。","位高湯左相，權總漢諸侯。","不改周南化，仍分趙北憂。","雙旌過易水，千騎入幽州。","塞草連天幕，邊风动地愁。","無因隨远道，結束佩吳鉤。"]', '诗', 'shi', '', NULL, '奉送王相公赴幽州 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ed10709-e340-479a-9c93-8e29d8277300', '重經巴丘', '重經巴丘', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["昔年高接李膺歡，日泛仙舟醉碧瀾。","詩句亂隨青草落，酒腸俱逐洞庭寬。","浮生聚散雲相似，往事冥微夢一般。","今日片帆城下去，秋風回首淚闌干。"]', '["昔年高接李膺歡，日泛仙舟醉碧瀾。","诗句亂隨青草落，酒腸俱逐洞庭寬。","浮生聚散云相似，往事冥微梦一般。","今日片帆城下去，秋风回首泪闌干。"]', '诗', 'shi', '', NULL, '重經巴丘 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3475f453-0fc1-42c6-910a-ec8484e603fa', '九日巴丘楊公臺上宴集', '九日巴丘楊公台上宴集', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["淒淒霜日上高臺，水國秋涼客思哀。","萬疊銀山寒浪起，一行斜字早鴻來。","誰家搗練孤城暮，何處題衣遠信回。","江漢路長身不定，菊花三笑旅懷開。"]', '["淒淒霜日上高台，水国秋涼客思哀。","万叠銀山寒浪起，一行斜字早鴻来。","誰家捣練孤城暮，何处題衣远信回。","江漢路长身不定，菊花三笑旅懷开。"]', '诗', 'shi', '', NULL, '九日巴丘楊公臺上宴集 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('876ff9cb-ace3-47e6-9d04-5a22a5752168', '遊靈巖', '游靈巖', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["靈巖有路入煙霞，臺殿高低釋子家。","風滿迴廊飄墜葉，水流絕澗泛秋花。","青松閱世風霜古，翠竹題詩歲月賒。","誰謂無生真可學，山中亦自有年華。"]', '["靈巖有路入煙霞，台殿高低釋子家。","风满迴廊飄墜葉，水流絕澗泛秋花。","青松閱世风霜古，翠竹題诗歲月賒。","誰謂無生真可学，山中亦自有年华。"]', '诗', 'shi', '', NULL, '遊靈巖 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4112dcaf-c39a-44b0-9fb1-ab4c5fdc6ec1', '河間獻王墓', '河间獻王墓', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["漢家宗室獨稱賢，遺事閑中見舊編。","偶過河間尋往跡，却憐荒冢帶寒煙。","頻求千古書連帙，獨對三雍策幾篇。","雅樂未興人已逝，雄歌依舊大風傳。"]', '["漢家宗室独稱賢，遺事闲中见旧編。","偶過河间尋往跡，却怜荒冢带寒煙。","頻求千古书連帙，独对三雍策幾篇。","雅乐未兴人已逝，雄歌依旧大风傳。"]', '诗', 'shi', '', NULL, '河間獻王墓 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fe0c679-7ec9-4b3a-86a6-9518c8718428', '秋日道中', '秋日道中', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["齊魯西風草樹秋，川原高下過東州。","道邊白鶴來華表，陌上蒼麟臥古丘。","九曲半應非禹跡，三山何處是仙洲。","徑行俯仰成今古，却憶當年賦遠遊。"]', '["齊魯西风草樹秋，川原高下過东州。","道邊白鹤来华表，陌上蒼麟臥古丘。","九曲半應非禹跡，三山何处是仙洲。","徑行俯仰成今古，却憶當年賦远游。"]', '诗', 'shi', '', NULL, '秋日道中 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9947ed4-f396-410d-a04a-c6858a730c3c', '華清宮', '华清宮', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["天寶承平奈樂何，華清宮殿鬱嵯峩。","朝元閣峻臨秦嶺，羯鼓樓高俯渭河。","玉樹長飄雲外曲，霓裳閑舞月中歌。","只今惟有溫泉水，嗚咽聲中感慨多。"]', '["天寶承平奈乐何，华清宮殿鬱嵯峩。","朝元閣峻臨秦嶺，羯鼓楼高俯渭河。","玉樹长飄云外曲，霓裳闲舞月中歌。","只今惟有溫泉水，嗚咽声中感慨多。"]', '诗', 'shi', '', NULL, '華清宮 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ee0bf7f-f501-49a3-a15b-77159956f8bf', '春申君祠', '春申君祠', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["春申祠宇空山裏，古柏陰陰石泉水。","日暮江南無主人，彌令過客思公子。","蕭條寒景傍山村，寂寞誰知楚相尊。","當時珠履三千客，趙使懷慚不敢言。"]', '["春申祠宇空山裏，古柏陰陰石泉水。","日暮江南無主人，彌令過客思公子。","蕭條寒景傍山村，寂寞誰知楚相尊。","當时珠履三千客，趙使懷慚不敢言。"]', '诗', 'shi', '', NULL, '春申君祠 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('163c87f2-5544-458c-9e88-31719dc59127', '人日代客子是日立春', '人日代客子是日立春', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["人日兼春日，長懷復短懷。","遙知雙彩勝，併在一金釵。"]', '["人日兼春日，长懷复短懷。","遙知雙彩勝，併在一金釵。"]', '诗', 'shi', '', NULL, '人日代客子是日立春 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae33fbbe-2f0e-4a1f-b2de-af3fd985ed3b', '寄鄭員外', '寄鄭員外', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["經月愁聞雨，新年苦憶君。","何時共登眺，整屐待晴雲。"]', '["經月愁闻雨，新年苦憶君。","何时共登眺，整屐待晴云。"]', '诗', 'shi', '', NULL, '寄鄭員外 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f71c2d0-da57-4878-852c-a720cba83ae5', '飲李十二宅', '饮李十二宅', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["重門敞春夕，燈燭靄餘輝。","醉我百尊酒，留連夜未歸。"]', '["重门敞春夕，灯燭靄餘輝。","醉我百尊酒，留連夜未归。"]', '诗', 'shi', '', NULL, '飲李十二宅 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8610a25-205d-458c-a6d7-610300ad65b8', '山家', '山家', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["板橋人渡泉聲，茅檐日午雞鳴。","莫嗔焙茶煙暗，却喜曬穀天晴。"]', '["板橋人渡泉声，茅檐日午雞鳴。","莫嗔焙茶煙暗，却喜曬穀天晴。"]', '诗', 'shi', '', NULL, '山家 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('572278ce-3eea-4123-b65f-648dde36642d', '歸山', '归山', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["心事數莖白髮，生涯一片青山。","空林有雪相待，古道無人獨還。"]', '["心事數莖白髮，生涯一片青山。","空林有雪相待，古道無人独還。"]', '诗', 'shi', '', NULL, '歸山 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89c9f595-69f0-40d4-a615-e167b06ef75d', '金谷園', '金谷园', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["綵樓歌館正融融，一騎星飛錦帳空。","老盡名花春不管，年年啼鳥怨東風。"]', '["綵楼歌館正融融，一騎星飞錦帳空。","老尽名花春不管，年年啼鸟怨东风。"]', '诗', 'shi', '', NULL, '金谷園 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4946eef1-7a7c-4ae4-a6b2-637c75497ce3', '郵亭', '郵亭', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["雲淡山橫日欲斜，郵亭下馬對殘花。","自從身逐征西府，每到開時不在家。"]', '["云淡山橫日欲斜，郵亭下马对殘花。","自從身逐征西府，每到开时不在家。"]', '诗', 'shi', '', NULL, '郵亭 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a973f96-694c-4be6-af39-769b046af14f', '宿白馬寺', '宿白马寺', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["白馬馱經事已空，斷碑殘剎見遺蹤。","蕭蕭茅屋秋風起，一夜雨聲羈思濃。"]', '["白马馱經事已空，斷碑殘剎见遺蹤。","蕭蕭茅屋秋风起，一夜雨声羈思濃。"]', '诗', 'shi', '', NULL, '宿白馬寺 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36f57d25-83c2-4f54-967c-07bac26a113e', '明德宮', '明德宮', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["碧瓦朱楹白晝閑，金衣寶扇曉風寒。","摩雲觀閣高如許，長對河流出斷山。"]', '["碧瓦朱楹白晝闲，金衣寶扇晓风寒。","摩云观閣高如許，长对河流出斷山。"]', '诗', 'shi', '', NULL, '明德宮 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37041167-72dc-4eb2-a545-f078fa57b755', '讀嶧山碑', '读嶧山碑', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["六國平來四海家，相君當代擅才華。","誰知頌德山頭石，却與他人戒後車。"]', '["六国平来四海家，相君當代擅才华。","誰知頌德山头石，却與他人戒後车。"]', '诗', 'shi', '', NULL, '讀嶧山碑 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9ae435b-f153-407f-bbb0-960493b8ae80', '句', '句', '713926e0-43a4-40d0-912e-174819513b1f', '唐', '["漢月經時掩，胡塵與歲深。"]', '["漢月經时掩，胡塵與歲深。"]', '诗', 'shi', '', NULL, '句 張繼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa4b7824-0d42-4c9d-ae3c-6431180ae9ad', '令狐員外宅宴寄中丞', '令狐員外宅宴寄中丞', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["寒色凝羅幕，同人清夜期。","玉杯留醉處，銀燭送歸時。","獨坐隔千里，空吟對雪詩。"]', '["寒色凝羅幕，同人清夜期。","玉杯留醉处，銀燭送归时。","独坐隔千里，空吟对雪诗。"]', '诗', 'shi', '', NULL, '令狐員外宅宴寄中丞 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ac2eff6-b6c7-4207-82df-2d34070e5637', '禇主簿宅會畢庶子錢員外郎使君', '禇主簿宅會畢庶子錢員外郎使君', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["開甕臘酒熟，主人心賞同。","斜陽疎竹上，殘雪亂天中。","更喜宣城印，朝廷與謝公。"]', '["开甕臘酒熟，主人心賞同。","斜陽疎竹上，殘雪亂天中。","更喜宣城印，朝廷與謝公。"]', '诗', 'shi', '', NULL, '禇主簿宅會畢庶子錢員外郎使君 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c74950d3-3194-4abe-a37c-03a623d03636', '送李明府赴滑州', '送李明府赴滑州', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["渭城寒食罷，送客歸遠道。","烏帽背斜暉，青驪踏春草。","酒醒孤燭夜，衣冷千山早。","去事沈尚書，應憐詞賦好。"]', '["渭城寒食罷，送客归远道。","烏帽背斜暉，青驪踏春草。","酒醒孤燭夜，衣冷千山早。","去事沈尚书，應怜词賦好。"]', '诗', 'shi', '', NULL, '送李明府赴滑州 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a59a323a-a14b-4b70-824a-fe3ace60a2b6', '送李司直赴江西使幕', '送李司直赴江西使幕', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["斂版辭漢廷，進帆歸楚幕。","三江城上轉，九里人家泊。","好酒近宜城，能詩謝康樂。","雨晴西山樹，日出南昌郭。","竹露點衣巾，湖煙濕扃鑰。","主人蒼玉佩，後騎黃金絡。","高視領八州，相期同一鶚。","行當報知己，從此飛寥廓。"]', '["斂版辞漢廷，進帆归楚幕。","三江城上轉，九里人家泊。","好酒近宜城，能诗謝康乐。","雨晴西山樹，日出南昌郭。","竹露点衣巾，湖煙濕扃鑰。","主人蒼玉佩，後騎黄金絡。","高視領八州，相期同一鶚。","行當報知己，從此飞寥廓。"]', '诗', 'shi', '', NULL, '送李司直赴江西使幕 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ec8ecbf-4fa2-43d9-9784-c2ad286783a8', '祭嶽回重贈孟都督', '祭嶽回重贈孟都督', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["封作天齊王，清祠太山下。","魯公秋賽畢，曉日回高駕。","從騎盡幽幷，同人皆沈謝。","自矜文武足，一醉寒溪夜。"]', '["封作天齊王，清祠太山下。","魯公秋賽畢，晓日回高駕。","從騎尽幽幷，同人皆沈謝。","自矜文武足，一醉寒溪夜。"]', '诗', 'shi', '', NULL, '祭嶽回重贈孟都督 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfc88940-1d1b-4fb9-bae8-f45ffa0c50bf', '送南少府歸壽春', '送南少府归壽春', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["人言壽春遠，此去先秋到。","孤客小翼舟，諸生高翅帽。","淮風生竹簟，楚雨移茶竈。","若在八公山，題詩一相報。"]', '["人言壽春远，此去先秋到。","孤客小翼舟，諸生高翅帽。","淮风生竹簟，楚雨移茶竈。","若在八公山，題诗一相報。"]', '诗', 'shi', '', NULL, '送南少府歸壽春 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3b05afb-8775-4a13-9f16-849263f9bfb7', '贈別崔司直赴江東兼簡常州獨孤使君', '贈別崔司直赴江东兼簡常州独孤使君', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["愛君青袍色，芳草能相似。","官重法家流，名高墨曹吏。","春衣淮上宿，美酒江邊醉。","楚酪沃雕胡，湘羹糝香餌。","前朝山水國，舊日風流地。","蘇山逐青驄，江家驅白鼻。","右軍尚少年，三領東方騎。","亦過小丹陽，應知百城貴。"]', '["愛君青袍色，芳草能相似。","官重法家流，名高墨曹吏。","春衣淮上宿，美酒江邊醉。","楚酪沃雕胡，湘羹糝香餌。","前朝山水国，旧日风流地。","蘇山逐青驄，江家驱白鼻。","右軍尚少年，三領东方騎。","亦過小丹陽，應知百城貴。"]', '诗', 'shi', '', NULL, '贈別崔司直赴江東兼簡常州獨孤使君 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c239cd63-cdb7-4686-abdb-81ff57b34097', '經月巖山', '經月巖山', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["驅車過閩越，路出饒陽西。","仙山翠如畫，簇簇生虹蜺。","羣峯若侍從，衆阜如嬰提。","巖巒互吞吐，嶺岫相追攜。","中有月輪滿，皎潔如圓珪。","玉皇恣遊覽，到此神應迷。","嫦娥曳霞帔，引我同攀躋。","騰騰上天半，玉鏡懸飛梯。","瑤池何悄悄，鸞鶴煙中棲。","回頭望塵事，露下寒淒淒。"]', '["驱车過閩越，路出饒陽西。","仙山翠如畫，簇簇生虹蜺。","羣峯若侍從，衆阜如嬰提。","巖巒互吞吐，嶺岫相追携。","中有月輪满，皎潔如圓珪。","玉皇恣游覽，到此神應迷。","嫦娥曳霞帔，引我同攀躋。","腾腾上天半，玉镜懸飞梯。","瑤池何悄悄，鸾鹤煙中棲。","回头望塵事，露下寒淒淒。"]', '诗', 'shi', '', NULL, '經月巖山 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14aa9c1f-54ae-4f29-a17c-b6036a3e1bca', '送客之江寧', '送客之江寧', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["春流送客不應賒，南入徐州見柳花。","朱雀橋邊看淮水，烏衣巷裏問王家。","千閭萬井無多事，闢戶開門向山翠。","楚雲朝下石頭城，江燕雙飛瓦棺寺。","吳士風流甚可親，相逢嘉賞日應新。","從來此地夸羊酪，自有蓴羹定却人。"]', '["春流送客不應賒，南入徐州见柳花。","朱雀橋邊看淮水，烏衣巷裏问王家。","千閭万井無多事，闢戶开门向山翠。","楚云朝下石头城，江燕雙飞瓦棺寺。","吳士风流甚可親，相逢嘉賞日應新。","從来此地夸羊酪，自有蓴羹定却人。"]', '诗', 'shi', '', NULL, '送客之江寧 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a38dec81-0d4f-4006-83d4-db613d6b837b', '送山陰姚丞攜妓之任兼寄山陰蘇少府', '送山陰姚丞携妓之任兼寄山陰蘇少府', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["東風香草路，南客心容與。","白皙吳王孫，青蛾柳家女。","都門數騎出，河口片帆舉。","夜簟眠橘洲，春衫傍楓嶼。","山陰政簡甚從容，到罷唯求物外蹤。","落日花邊剡溪水，晴烟竹裏會稽峯。","才子風流蘇伯玉，同官曉暮應相逐。","加餐共愛鱸魚肥，醒酒仍憐甘蔗熟。","知君鍊思本清新，季子如今德有鄰。","他日如尋始寧墅，題詩早晚寄西人。"]', '["东风香草路，南客心容與。","白皙吳王孫，青蛾柳家女。","都门數騎出，河口片帆舉。","夜簟眠橘洲，春衫傍楓嶼。","山陰政簡甚從容，到罷唯求物外蹤。","落日花邊剡溪水，晴烟竹裏會稽峯。","才子风流蘇伯玉，同官晓暮應相逐。","加餐共愛鱸鱼肥，醒酒仍怜甘蔗熟。","知君鍊思本清新，季子如今德有鄰。","他日如尋始寧墅，題诗早晚寄西人。"]', '诗', 'shi', '', NULL, '送山陰姚丞攜妓之任兼寄山陰蘇少府 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e46030b-de70-4088-a6f1-46e61fdabf1d', '和高平朱參軍思歸作', '和高平朱參軍思归作', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["髯參軍，髯參軍。","身爲北州吏，心寄東山雲。","坐見淒淒芳草綠，遙思往日晴江曲。","刺船頻向剡中回，捧被曾過越人宿。","花裏鶯啼白日高，春樓把酒送車螯。","狂歌好愛陶彭澤，佳句唯稱謝法曹。","平生樂事多如此，忍爲浮名隔千里。","一雁南飛動客心，思歸何待秋風起。"]', '["髯參軍，髯參軍。","身爲北州吏，心寄东山云。","坐见淒淒芳草綠，遙思往日晴江曲。","刺船頻向剡中回，捧被曾過越人宿。","花裏鶯啼白日高，春楼把酒送车螯。","狂歌好愛陶彭澤，佳句唯稱謝法曹。","平生乐事多如此，忍爲浮名隔千里。","一雁南飞动客心，思归何待秋风起。"]', '诗', 'shi', '', NULL, '和高平朱參軍思歸作 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8eafbe3-395b-4dc4-9ae3-42003a5466e4', '贈別成明府赴劒南', '贈別成明府赴劒南', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["朝爲三室印，晚爲三蜀人。","遙知下車日，正及巴山春。","縣道橘花裏，驛流江水濱。","公門輙無事，賞地能相親。","解衣初醉綠芳夕，應採蹲鴟薦佳客。","霽水遠暎西川時，閑望碧雞飛古祠。","愛君樂事佳興發，天外銅梁多夢思。"]', '["朝爲三室印，晚爲三蜀人。","遙知下车日，正及巴山春。","縣道橘花裏，驛流江水濱。","公门輙無事，賞地能相親。","解衣初醉綠芳夕，應採蹲鴟薦佳客。","霽水远暎西川时，闲望碧雞飞古祠。","愛君乐事佳兴發，天外銅梁多梦思。"]', '诗', 'shi', '', NULL, '贈別成明府赴劒南 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('954bc2e7-212b-4af0-afc2-f9230822a784', '送孫潑赴雲中', '送孫潑赴云中', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["黃驄少年舞雙戟，目視旁人皆辟易。","百戰能誇隴上兒，一身復作雲中客。","寒風動地氣蒼茫，橫吹先悲出塞長。","敲石軍中傳夜火，斧冰河畔汲朝漿。","前鋒直指陰山外，虜騎紛紛膽應碎。","匈奴破盡人看歸，金印酬功如斗大。"]', '["黄驄少年舞雙戟，目視旁人皆辟易。","百戰能誇隴上兒，一身复作云中客。","寒风动地氣蒼茫，橫吹先悲出塞长。","敲石軍中傳夜火，斧冰河畔汲朝漿。","前鋒直指陰山外，虜騎紛紛膽應碎。","匈奴破尽人看归，金印酬功如斗大。"]', '诗', 'shi', '', NULL, '送孫潑赴雲中 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('106fa284-594d-40c0-8b5a-e5a46200ce6a', '送客還江東', '送客還江东', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["還家不落春風後，數日應沽越人酒。","池畔花深鬬鴨欄，橋邊雨洗藏鴉柳。","遙憐內舍著新衣，復向鄰家醉落暉。","把手閑歌香橘下，空山一望鷓鴣飛。"]', '["還家不落春风後，數日應沽越人酒。","池畔花深鬬鴨欄，橋邊雨洗藏鴉柳。","遙怜內舍著新衣，复向鄰家醉落暉。","把手闲歌香橘下，空山一望鷓鴣飞。"]', '诗', 'shi', '', NULL, '送客還江東 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('237ab4c2-46bc-41a0-9251-aab124a09103', '送夏侯侍郎', '送夏侯侍郎', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["元戎車右早飛聲，御史府中新正名。","翰墨已齊鍾大理，風流好繼謝宣城。","從軍曉別龍驤幕，六騎先驅嘶近郭。","前路應留白玉臺，行人輙美黃金絡。","使君下馬愛瀛洲，簡貴將求物外遊。","聽訟不聞烏布帳，迎賓暫著紫綈裘。","公庭日夕羅山翠，功遂心閑無一事。","移書或問島邊人，立仗時呼鈴下吏。","事業初傳小夏侯，中年劒笏在西州。","浮雲飛鳥兩相忘，他日依依城上樓。"]', '["元戎车右早飞声，御史府中新正名。","翰墨已齊鍾大理，风流好繼謝宣城。","從軍晓別龙驤幕，六騎先驱嘶近郭。","前路應留白玉台，行人輙美黄金絡。","使君下马愛瀛洲，簡貴將求物外游。","听訟不闻烏布帳，迎賓暫著紫綈裘。","公庭日夕羅山翠，功遂心闲無一事。","移书或问島邊人，立仗时呼鈴下吏。","事業初傳小夏侯，中年劒笏在西州。","浮云飞鸟兩相忘，他日依依城上楼。"]', '诗', 'shi', '', NULL, '送夏侯侍郎 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b033c94b-3357-4241-af63-1a2196ee4c1d', '送李湜下第歸衛州便遊河北', '送李湜下第归衛州便游河北', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["莫嗟太常屈，便入蘇門嘯。","裏在應未遲，勿作我身料。","輕雲日下不成陰，出對流芳攪別心。","萬雉城東春水闊，千人鄉北晚花深。","舊竹青青常繞宅，到時疎曠應自適。","佳期縱得上宮遊，旅食還爲北邙客。","路出司州勝景長，西山翠色帶清漳。","仙人磯近茱萸澗，銅雀臺臨野馬岡。","屢道主人多愛士，何辭策馬千餘里。","高譚魏國訪先生，修刺平原過內史。","一舉青雲在早秋，恐君從此便淹留。","有錢莫向河間用，載筆須來闕下遊。"]', '["莫嗟太常屈，便入蘇门嘯。","裏在應未遲，勿作我身料。","轻云日下不成陰，出对流芳攪別心。","万雉城东春水闊，千人乡北晚花深。","旧竹青青常繞宅，到时疎曠應自適。","佳期縱得上宮游，旅食還爲北邙客。","路出司州勝景长，西山翠色带清漳。","仙人磯近茱萸澗，銅雀台臨野马岡。","屢道主人多愛士，何辞策马千餘里。","高譚魏国訪先生，修刺平原過內史。","一舉青云在早秋，恐君從此便淹留。","有錢莫向河间用，載笔須来闕下游。"]', '诗', 'shi', '', NULL, '送李湜下第歸衛州便遊河北 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('031187e0-1ef2-4f5a-82c8-c2d0f20f4369', '張山人草堂會王方士', '張山人草堂會王方士', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["嶼花晚，山日長，蕙帶麻襦食草堂。","一片水光飛入戶，千竿竹影亂登牆。","園梅熟，家醞香。","新溼頭巾不復篸，相看醉倒臥藜牀。"]', '["嶼花晚，山日长，蕙带麻襦食草堂。","一片水光飞入戶，千竿竹影亂登牆。","园梅熟，家醞香。","新溼头巾不复篸，相看醉倒臥藜牀。"]', '诗', 'shi', '', NULL, '張山人草堂會王方士 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c8d0bf9-b654-4546-9019-8bae5e3de2e3', '送蓨縣劉主簿楚', '送蓨縣劉主簿楚', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["起家得事平原侯，晚出都門辭舊遊。","草色連綿幾千里，青驪躞蹀路旁子。","花深近縣宿河陽，竹暎春舟渡淇水。","鄴下淹留佳賞新，羣公舊日心相親。","金盤曉鱠朱衣鮒，玉簟霄迎翠羽人。","王程書使前期促，他日應知舉鞭速。","寒水浮瓜五月時，把君衣袖長河曲。"]', '["起家得事平原侯，晚出都门辞旧游。","草色連綿幾千里，青驪躞蹀路旁子。","花深近縣宿河陽，竹暎春舟渡淇水。","鄴下淹留佳賞新，羣公旧日心相親。","金盤晓鱠朱衣鮒，玉簟霄迎翠羽人。","王程书使前期促，他日應知舉鞭速。","寒水浮瓜五月时，把君衣袖长河曲。"]', '诗', 'shi', '', NULL, '送蓨縣劉主簿楚 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae355c43-35bf-4bcb-8381-6018739b2b48', '題玉山觀禪師蘭若', '題玉山观禪師蘭若', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["玉山宴坐移年月，錫杖承恩詣丹闕。","先朝親與會龍華，紫禁鳴鐘白日斜。","宮女焚香把經卷，天人就席禮袈裟。","禪牀久臥虎溪水，蘭若初開鳳城裏。","不出囂塵見遠公，道成何必青蓮宮。","朝持藥缽千家近，暮倚繩牀一室空。","掖垣揮翰君稱美，遠客陪遊問真理。","薄宦深知誤此心，回心願學雷居士。"]', '["玉山宴坐移年月，錫杖承恩詣丹闕。","先朝親與會龙华，紫禁鳴鐘白日斜。","宮女焚香把經卷，天人就席禮袈裟。","禪牀久臥虎溪水，蘭若初开鳳城裏。","不出囂塵见远公，道成何必青蓮宮。","朝持藥缽千家近，暮倚繩牀一室空。","掖垣揮翰君稱美，远客陪游问真理。","薄宦深知誤此心，回心願学雷居士。"]', '诗', 'shi', '', NULL, '題玉山觀禪師蘭若 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23073075-096d-449e-8467-acb59dbe4d9c', '贈別上元主簿張著', '贈別上元主簿張著', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["上書一見平津侯，劒笏斜齊秣陵尉。","朝垂綬帶迎遠客，暮鎖印囊飛上吏。","長樂花深萬井時，同官無事有歸期。","回船對酒三生渚，繫馬焚香五願祠。","日日澄江帶山翠，綠芳都在經過地。","行人看射領軍堂，遊女題詩光宅寺。","風流才調愛君偏，此別相逢定幾年。","惆悵浮雲迷遠道，張侯樓上月娟娟。"]', '["上书一见平津侯，劒笏斜齊秣陵尉。","朝垂綬带迎远客，暮鎖印囊飞上吏。","长乐花深万井时，同官無事有归期。","回船对酒三生渚，繫马焚香五願祠。","日日澄江带山翠，綠芳都在經過地。","行人看射領軍堂，游女題诗光宅寺。","风流才調愛君偏，此別相逢定幾年。","惆悵浮云迷远道，張侯楼上月娟娟。"]', '诗', 'shi', '', NULL, '贈別上元主簿張著 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac1bd837-2808-4935-b9da-9122efede732', '別氾水縣尉', '別氾水縣尉', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["未央宮殿金開鑰，詔引賢良卷珠箔。","花間賜食近丹墀，烟裏揮毫對青閣。","萬年枝影轉斜光，三道先成君激昂。","谷水直言身不顧，郄詵高第轉名香。","綠槐陰陰出關道，上有蟬聲下秋草。","奴子平頭駿馬肥，少年白皙登王畿。","五侯客舍偏留宿，一縣人家爭看歸。","南向千峯北臨水，佳期賞地應窮此。","賦詩或送鄭行人，舉酒常陪魏公子。","自憐寂寞會君稀，猶著前時博士衣。","我欲低眉問知己，若將無用廢東歸。"]', '["未央宮殿金开鑰，詔引賢良卷珠箔。","花间賜食近丹墀，烟裏揮毫对青閣。","万年枝影轉斜光，三道先成君激昂。","谷水直言身不顧，郄詵高第轉名香。","綠槐陰陰出关道，上有蟬声下秋草。","奴子平头駿马肥，少年白皙登王畿。","五侯客舍偏留宿，一縣人家爭看归。","南向千峯北臨水，佳期賞地應窮此。","賦诗或送鄭行人，舉酒常陪魏公子。","自怜寂寞會君稀，猶著前时博士衣。","我欲低眉问知己，若將無用廢东归。"]', '诗', 'shi', '', NULL, '別氾水縣尉 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fd231d3-c040-4a2c-9b0b-5b96297cb884', '別李明府', '別李明府', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["寵光五世要青組，出入珠宮引簫鼓。","醉舞雄王玳瑁牀，嬌嘶駿馬珊瑚柱。","胡兒夾鼓越婢隨，行捧玉盤嘗荔枝。","羅山道士請人送，林邑使臣調象騎。","愛君一身遊上國，闕下名公如舊識。","萬里初懷印綬歸，湘江過盡嶺花飛。","五侯焦石烹江筍，千戶沈香染客衣。","別後想君難可見，蒼梧雲裏空山縣。","汗苑芳菲入夏闌，待君障日蒲葵扇。"]', '["寵光五世要青組，出入珠宮引簫鼓。","醉舞雄王玳瑁牀，嬌嘶駿马珊瑚柱。","胡兒夾鼓越婢隨，行捧玉盤嘗荔枝。","羅山道士請人送，林邑使臣調象騎。","愛君一身游上国，闕下名公如旧識。","万里初懷印綬归，湘江過尽嶺花飞。","五侯焦石烹江筍，千戶沈香染客衣。","別後想君难可见，蒼梧云裏空山縣。","汗苑芳菲入夏闌，待君障日蒲葵扇。"]', '诗', 'shi', '', NULL, '別李明府 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1dc7007-90f2-438c-af82-c439fddf8907', '送中兄典邵州', '送中兄典邵州', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["官騎連西向楚雲，朱軒出餞晝紛紛。","百城兼領安南國，雙筆遙揮王左君。","一路諸侯爭館穀，洪池高會荆臺曲。","玉顏送酒銅[鞮]歌，金管留人石頭宿。","北雁初回江燕飛，南湖春暖著春衣。","湘君祠對空山掩，漁父焚香日暮歸。","百事無留到官後，重門寂寂垂高柳。","零陵過贈石香溪，洞口人來飲醇酒。","登樓暮結邵陽情，萬里蒼波煙靄生。","他日新詩應見報，還如宣遠在安城。"]', '["官騎連西向楚云，朱軒出餞晝紛紛。","百城兼領安南国，雙笔遙揮王左君。","一路諸侯爭館穀，洪池高會荆台曲。","玉顏送酒銅[鞮]歌，金管留人石头宿。","北雁初回江燕飞，南湖春暖著春衣。","湘君祠对空山掩，漁父焚香日暮归。","百事無留到官後，重门寂寂垂高柳。","零陵過贈石香溪，洞口人来饮醇酒。","登楼暮結邵陽情，万里蒼波煙靄生。","他日新诗應见報，還如宣远在安城。"]', '诗', 'shi', '', NULL, '送中兄典邵州 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('453c27da-982c-4f5f-90a7-0c7076edfff0', '送萬巨', '送万巨', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["漢相見王陵，揚州事張禹。","風帆木蘭檝，水國蓮花府。","百丈清江十月天，寒城鼓角曉鐘前。","金爐促膝諸曹吏，玉管繁華美少年。","有時過向長干地，遠對湖光近山翠。","好逢南苑看人歸，也向西池留客醉。","高柳垂煙橘帶霜，朝遊石渚暮橫塘。","紅牋色奪風流座，白苧詞傾翰墨場。","夫子前年入朝後，高名籍籍時賢口。","共憐詩興轉清新，繼遠家聲在此身。","屈指待爲青瑣客，回頭莫羨白亭人。"]', '["漢相见王陵，揚州事張禹。","风帆木蘭檝，水国蓮花府。","百丈清江十月天，寒城鼓角晓鐘前。","金爐促膝諸曹吏，玉管繁华美少年。","有时過向长干地，远对湖光近山翠。","好逢南苑看人归，也向西池留客醉。","高柳垂煙橘带霜，朝游石渚暮橫塘。","紅牋色奪风流座，白苧词傾翰墨場。","夫子前年入朝後，高名籍籍时賢口。","共怜诗兴轉清新，繼远家声在此身。","屈指待爲青瑣客，回头莫羨白亭人。"]', '诗', 'shi', '', NULL, '送萬巨 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc77ee9a-1a6e-41a7-8f73-f53658d9b362', '送巴州楊使君', '送巴州楊使君', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["白雲縣北千山口，青歲欲開殘雪後。","前驅錦帶魚皮鞮，側佩金璋虎頭綬。","南鄭侯家醉落暉，東關陌上著鞭歸。","愁看野馬隨官騎，笑取秦人帶客旗。","使者下車憂疾苦，豪吏銷聲出公府。","萬里歌鐘相慶時，巴童聲節渝兒舞。"]', '["白云縣北千山口，青歲欲开殘雪後。","前驱錦带鱼皮鞮，側佩金璋虎头綬。","南鄭侯家醉落暉，东关陌上著鞭归。","愁看野马隨官騎，笑取秦人带客旗。","使者下车憂疾苦，豪吏銷声出公府。","万里歌鐘相慶时，巴童声節渝兒舞。"]', '诗', 'shi', '', NULL, '送巴州楊使君 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('401c0315-b40c-4e97-a5ab-170e5f89d34b', '送王侍御赴江西兼寄李袁州', '送王侍御赴江西兼寄李袁州', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["中朝理章服，南國隨旌旆。","臘酒湘城隅，春衣楚江外。","垂簾白角簟，下筯鱸魚鱠。","雄筆佐名公，虛舟應時輩。","按俗承流幾路清，平明山靄春江雲。","湓城詩贈魚司馬，汝水人逢王右軍。","綠蘋白芷遙相引，孤興幽尋知不近。","井上銅人行見無，湖中石燕飛應盡。","禮門前直事仙郎，腰垂青綬領咸陽。","花間五馬迎君日，雨霽煙開玉女岡。"]', '["中朝理章服，南国隨旌旆。","臘酒湘城隅，春衣楚江外。","垂簾白角簟，下筯鱸鱼鱠。","雄笔佐名公，虛舟應时輩。","按俗承流幾路清，平明山靄春江云。","湓城诗贈鱼司马，汝水人逢王右軍。","綠蘋白芷遙相引，孤兴幽尋知不近。","井上銅人行见無，湖中石燕飞應尽。","禮门前直事仙郎，腰垂青綬領咸陽。","花间五马迎君日，雨霽煙开玉女岡。"]', '诗', 'shi', '', NULL, '送王侍御赴江西兼寄李袁州 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fbf4e85-efba-44ca-9b46-2801503c0981', '寄雍丘竇明府', '寄雍丘竇明府', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["少年結綬騁金羈，許下如看瓊樹枝。","入里親過朗陵伯，出門高視潁川兒。","西遊太府東乘傳，泗上諸侯誰不羨。","時輩寧將白筆期，高流竚向丹霄見。","何事飜飛不及羣，虎班突騎來紛紛。","吳江垂釣楚山醉，身寄滄波心白雲。","中歲胡塵靜如掃，一官又罷行將老。","薛公薦士得君初，囗領黃金千室餘。","機盡獨親沙上鳥，家貧唯向釜中魚。","囗囗囗囗囗囗囗，囗出重門煙樹裏。","感物吟詩對暮天，懷人倚杖臨秋水。","別離幾日問前期，鳴雁亭邊人去時。","獨坐不堪朝與夕，高風蕭索亂蟬悲。"]', '["少年結綬騁金羈，許下如看瓊樹枝。","入里親過朗陵伯，出门高視潁川兒。","西游太府东乘傳，泗上諸侯誰不羨。","时輩寧將白笔期，高流竚向丹霄见。","何事飜飞不及羣，虎班突騎来紛紛。","吳江垂釣楚山醉，身寄滄波心白云。","中歲胡塵静如掃，一官又罷行將老。","薛公薦士得君初，囗領黄金千室餘。","機尽独親沙上鸟，家貧唯向釜中鱼。","囗囗囗囗囗囗囗，囗出重门煙樹裏。","感物吟诗对暮天，懷人倚杖臨秋水。","別離幾日问前期，鳴雁亭邊人去时。","独坐不堪朝與夕，高风蕭索亂蟬悲。"]', '诗', 'shi', '', NULL, '寄雍丘竇明府 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98d0d315-550f-4d8b-8ace-cdd49236425d', '贈衮州孟都督', '贈衮州孟都督', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["少年親事冠軍侯，中歲仍遷北衮州。","露冕寧夸漢車服，下帷常討魯春秋。","後齋草色連高閣，車簡人稀獨行樂。","閑心近掩陶使君，詩興遙齊謝康樂。","遠山重疊水逶迤，落日東城閑望時。","不見雙親辦豐膳，能留五馬盡佳期。","北場爭轉黃金勒，愛客華亭賞秋色。","卷簾滿地鋪氍毹，吹角鳴弦開玉壺。","願學平原十日飲，此時不忍歌驪駒。"]', '["少年親事冠軍侯，中歲仍遷北衮州。","露冕寧夸漢车服，下帷常討魯春秋。","後斋草色連高閣，车簡人稀独行乐。","闲心近掩陶使君，诗兴遙齊謝康乐。","远山重叠水逶迤，落日东城闲望时。","不见雙親辦豐膳，能留五马尽佳期。","北場爭轉黄金勒，愛客华亭賞秋色。","卷簾满地鋪氍毹，吹角鳴弦开玉壺。","願学平原十日饮，此时不忍歌驪駒。"]', '诗', 'shi', '', NULL, '贈衮州孟都督 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb457113-7980-48ef-877e-c3de1b067021', '別孟都督', '別孟都督', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["平蕪霽色寒城下，美酒百壺爭勸把。","連呼寶劒銳頭兒，少駐金羈大頭馬。","一飲留歡分有餘，寸心懷思復何如。","他時相憶若相問，青瑣門前開素書。"]', '["平蕪霽色寒城下，美酒百壺爭勸把。","連呼寶劒銳头兒，少駐金羈大头马。","一饮留歡分有餘，寸心懷思复何如。","他时相憶若相问，青瑣门前开素书。"]', '诗', 'shi', '', NULL, '別孟都督 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7248b9c-2699-4a66-ba2e-01a0807a39c8', '送別鄭明府', '送別鄭明府', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["長頭大鼻鬢如雪，早歲連兵劒鋒折。","千金盡去無斗儲，雙袖破來空百結。","獨戀郊扉已十春，高陽酒徒連此身。","路傍誰識鄭公子，谷口應知漢逸人。","兒女相悲探井臼，前功豈在他人後。","勸君不得學淵明，且策驢車辭五柳。"]', '["长头大鼻鬢如雪，早歲連兵劒鋒折。","千金尽去無斗儲，雙袖破来空百結。","独戀郊扉已十春，高陽酒徒連此身。","路傍誰識鄭公子，谷口應知漢逸人。","兒女相悲探井臼，前功豈在他人後。","勸君不得学淵明，且策驢车辞五柳。"]', '诗', 'shi', '', NULL, '送別鄭明府 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ee323cc-a68c-4f34-8e4a-0672602e2752', '贈別王侍御赴上都', '贈別王侍御赴上都', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["翩翩馬上郎，執簡佩銀章。","西向洛陽歸鄠杜，回頭結念蓮花府。","朝辭芳草萬歲街，暮宿春山一泉塢。","青青樹色傍行衣，乳燕流鶯相間飛。","遠過三峯臨八水，幽尋佳賞偏如此。","殘花片片細柳風，落日疎鐘小槐雨。","相思掩泣復何如，公子門前人漸疎。","幸有心期當小暑，葛衣紗帽望回車。"]', '["翩翩马上郎，執簡佩銀章。","西向洛陽归鄠杜，回头結念蓮花府。","朝辞芳草万歲街，暮宿春山一泉塢。","青青樹色傍行衣，乳燕流鶯相间飞。","远過三峯臨八水，幽尋佳賞偏如此。","殘花片片細柳风，落日疎鐘小槐雨。","相思掩泣复何如，公子门前人漸疎。","幸有心期當小暑，葛衣紗帽望回车。"]', '诗', 'shi', '', NULL, '贈別王侍御赴上都 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b157863a-33fe-47b1-9126-761e6f0f075d', '贈別太常李博士兼寄兩省舊遊', '贈別太常李博士兼寄兩省旧游', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["兩年戴武弁，趨侍明光殿。","一朝簪惠文，客事信陵君。","簡異當朝執，香非寓直熏。","差肩何記室，攜手李將軍。","玉鐙初回酸棗館，金鈿正舞石榴裙。","忽驚萬事隨流水，不見雙旌逐塞雲。","感舊撫心多寂寂，與君相遇頭初白。","暫誇五首軍中詩，還憶萬年枝下客。","昨日留歡今送歸，空披秋水暎斜暉。","閑吟佳句對孤鶴，惆悵寒霜落葉稀。"]', '["兩年戴武弁，趨侍明光殿。","一朝簪惠文，客事信陵君。","簡異當朝執，香非寓直熏。","差肩何記室，携手李將軍。","玉鐙初回酸棗館，金鈿正舞石榴裙。","忽驚万事隨流水，不见雙旌逐塞云。","感旧撫心多寂寂，與君相遇头初白。","暫誇五首軍中诗，還憶万年枝下客。","昨日留歡今送归，空披秋水暎斜暉。","闲吟佳句对孤鹤，惆悵寒霜落葉稀。"]', '诗', 'shi', '', NULL, '贈別太常李博士兼寄兩省舊遊 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e49be0f-69ae-44a6-a0d6-dcd636c6452f', '寄哥舒僕射', '寄哥舒僕射', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["萬里長城家，一生唯報國。","腰垂紫文綬，手控黃金勒。","高視黑頭翁，遙吞白騎賊。","先麾牙門將，轉鬬黃河北。","帳下親兵皆少年，錦衣承日繡行纏。","轆轤寶劒初出鞘，宛轉角弓初上弦。","步人抽箭大如笛，前把兩矛後雙戟。","左盤右射紅塵中，鶻入鴉羣有誰敵。","殺將破軍白日餘，回旃舞旆北風初。","郡公楯鼻好磨墨，走馬爲君飛羽書。"]', '["万里长城家，一生唯報国。","腰垂紫文綬，手控黄金勒。","高視黑头翁，遙吞白騎賊。","先麾牙门將，轉鬬黄河北。","帳下親兵皆少年，錦衣承日繡行纏。","轆轤寶劒初出鞘，宛轉角弓初上弦。","步人抽箭大如笛，前把兩矛後雙戟。","左盤右射紅塵中，鶻入鴉羣有誰敵。","殺將破軍白日餘，回旃舞旆北风初。","郡公楯鼻好磨墨，走马爲君飞羽书。"]', '诗', 'shi', '', NULL, '寄哥舒僕射 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deb7ecd2-0f91-4d70-ab88-1de2c571da6c', '贈別華陰道士', '贈別华陰道士', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["紫府先生舊同學，腰垂彤管貯靈藥。","耻論方士小還丹，好飲仙人太玄酪。","芙蓉山頂玉池西，一室平臨萬仞溪。","晝灑瑤臺五雲溼，夜行金燭七星齊。","回身暫下青冥裏，方外相尋有知己。","賣鮓市中何許人，釣魚坐上誰家子。","青青百草雲臺春，煙駕霓衣白角巾。","露葉獨歸仙掌去，迴風片雨謝時人。"]', '["紫府先生旧同学，腰垂彤管貯靈藥。","耻論方士小還丹，好饮仙人太玄酪。","芙蓉山頂玉池西，一室平臨万仞溪。","晝灑瑤台五云溼，夜行金燭七星齊。","回身暫下青冥裏，方外相尋有知己。","賣鮓市中何許人，釣鱼坐上誰家子。","青青百草云台春，煙駕霓衣白角巾。","露葉独归仙掌去，迴风片雨謝时人。"]', '诗', 'shi', '', NULL, '贈別華陰道士 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6629f32a-e163-4400-8684-a459c3b6bb52', '送崔秀才赴上元兼省叔父', '送崔秀才赴上元兼省叔父', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["寒塘斂暮雪，臘鼓迎春早。","匹馬五城人，重裘千里道。","淮山輕露溼，江樹狂風掃。","楚縣久醞醲，揚州百花好。","練湖東望接雲陽，女市西遊入建康。","行樂遠誇紅布旆，風流近賭紫香囊。","詩家行輩如君少，極目苦心懷謝朓。","煙開日上板橋南，吳岫青青出林表。"]', '["寒塘斂暮雪，臘鼓迎春早。","匹马五城人，重裘千里道。","淮山轻露溼，江樹狂风掃。","楚縣久醞醲，揚州百花好。","練湖东望接云陽，女市西游入建康。","行乐远誇紅布旆，风流近賭紫香囊。","诗家行輩如君少，極目苦心懷謝朓。","煙开日上板橋南，吳岫青青出林表。"]', '诗', 'shi', '', NULL, '送崔秀才赴上元兼省叔父 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a0f3730-bf09-4e6a-8fc4-d713b40149df', '贈別韋兵曹歸池州', '贈別韋兵曹归池州', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["南陵八月天，暮色遠峰前。","楚竹青陽路，吳江赤馬船。","籝金諸客貴，佩玉主人賢。","終日應相逐，歸期定幾年。"]', '["南陵八月天，暮色远峰前。","楚竹青陽路，吳江赤马船。","籝金諸客貴，佩玉主人賢。","終日應相逐，归期定幾年。"]', '诗', 'shi', '', NULL, '贈別韋兵曹歸池州 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e09998e4-ec09-4118-ac1b-92f7b53b2f7c', '寄武陵李少府', '寄武陵李少府', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["小縣春山口，公孫吏隱時。","楚歌催晚醉，蠻語入新詩。","桂水遙相憶，花源暗有期。","郢門千里外，莫怪尺書遲。"]', '["小縣春山口，公孫吏隐时。","楚歌催晚醉，蠻語入新诗。","桂水遙相憶，花源暗有期。","郢门千里外，莫怪尺书遲。"]', '诗', 'shi', '', NULL, '寄武陵李少府 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19cd68eb-40b6-45d2-8010-912fee03f160', '贈張建', '贈張建', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["結客平陵下，當年倚俠遊。","傳看轆轤劍，醉脫驦驌裘。","翠羽雙鬟妾，珠簾百尺樓。","春風坐相待，晚日莫淹留。"]', '["結客平陵下，當年倚俠游。","傳看轆轤劍，醉脫驦驌裘。","翠羽雙鬟妾，珠簾百尺楼。","春风坐相待，晚日莫淹留。"]', '诗', 'shi', '', NULL, '贈張建 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6723cc17-8c0f-4924-b703-bd1ae7e66bdc', '送監軍李判官', '送監軍李判官', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["上客佩雙劍，東城喜再遊。","舊從張博望，新事鄭長秋。","踏水回金勒，看風試錦裘。","知君不久住，漢將掃旄頭。"]', '["上客佩雙劍，东城喜再游。","旧從張博望，新事鄭长秋。","踏水回金勒，看风試錦裘。","知君不久住，漢將掃旄头。"]', '诗', 'shi', '', NULL, '送監軍李判官 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f75b9eb-4723-433f-9a55-3241ddd9c4ff', '送客歸廣平', '送客归廣平', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["家在趙邯鄲，歸心輙自歡。","晚杯狐腋暖，春雪馬毛寒。","孟月途中破，輕冰水上殘。","到時楊柳色，奈向故園看。"]', '["家在趙邯鄲，归心輙自歡。","晚杯狐腋暖，春雪马毛寒。","孟月途中破，轻冰水上殘。","到时楊柳色，奈向故园看。"]', '诗', 'shi', '', NULL, '送客歸廣平 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03aa2c0d-a012-4541-b8e6-e4661f8dd9ab', '送張儋水路歸北海', '送張儋水路归北海', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["千里東歸客，孤心憶舊游。","片帆依白水，高枕臥青州。","柏寢寒蕪變，梧臺宿雨收。","知君心興遠，每上海邊樓。"]', '["千里东归客，孤心憶旧游。","片帆依白水，高枕臥青州。","柏寢寒蕪变，梧台宿雨收。","知君心兴远，每上海邊楼。"]', '诗', 'shi', '', NULL, '送張儋水路歸北海 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78d01744-4b3b-4562-ac43-9832e61e0648', '送故人歸魯', '送故人归魯', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["魯客多歸興，居人悵別情。","雨餘衫袖冷，風急馬蹄輕。","秋草靈光殿，寒雲曲阜城。","知君拜親後，少婦下機迎。"]', '["魯客多归兴，居人悵別情。","雨餘衫袖冷，风急马蹄轻。","秋草靈光殿，寒云曲阜城。","知君拜親後，少婦下機迎。"]', '诗', 'shi', '', NULL, '送故人歸魯 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e7a1341-509d-4548-b45e-2d223e034977', '送故人歸蜀', '送故人归蜀', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["一騎西南遠，翩翩入劍門。","客衣筒布潤，山舍荔枝繁。","古廟祠金馬，春江帶白黿。","自應成旅逸，愛客有王孫。"]', '["一騎西南远，翩翩入劍门。","客衣筒布潤，山舍荔枝繁。","古廟祠金马，春江带白黿。","自應成旅逸，愛客有王孫。"]', '诗', 'shi', '', NULL, '送故人歸蜀 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce493923-7c4b-41a9-94e9-cf95741c018c', '酬程延秋夜即事見贈', '酬程延秋夜即事见贈', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["長簟迎風早，空城澹月華。","星河秋一雁，砧杵夜千家。","節候看應晚，心期臥亦賒。","向來吟秀句，不覺已鳴鴉。"]', '["长簟迎风早，空城澹月华。","星河秋一雁，砧杵夜千家。","節候看應晚，心期臥亦賒。","向来吟秀句，不覺已鳴鴉。"]', '诗', 'shi', '', NULL, '酬程延秋夜即事見贈 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e328454-fcde-4d6e-bfd6-578cc7a83c1e', '送郭贊府歸淮南', '送郭贊府归淮南', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["駿馬淮南客，歸時引望新。","江聲六合暮，楚色萬家春。","白苧歌西曲，黃苞寄北人。","不知心賞後，早晚見行塵。"]', '["駿马淮南客，归时引望新。","江声六合暮，楚色万家春。","白苧歌西曲，黄苞寄北人。","不知心賞後，早晚见行塵。"]', '诗', 'shi', '', NULL, '送郭贊府歸淮南 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e10aa405-b065-4c47-857e-335a1e41e935', '題龍興寺澹師房', '題龙兴寺澹師房', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["雙林彼上人，詩興轉相親。","竹裏經聲晚，門前山色春。","卷簾苔點淨，下筯藥苗新。","記取無生理，歸來問此身。"]', '["雙林彼上人，诗兴轉相親。","竹裏經声晚，门前山色春。","卷簾苔点淨，下筯藥苗新。","記取無生理，归来问此身。"]', '诗', 'shi', '', NULL, '題龍興寺澹師房 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9faf1d2f-d95e-4365-8987-6209027074af', '送客遊江南', '送客游江南', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["南使孤帆遠，東風任意吹。","楚雲殊不斷，江鳥暫相隨。","月淨鴛鴦水，春生豆蔻枝。","賞稱佳麗地，君去莫應知。"]', '["南使孤帆远，东风任意吹。","楚云殊不斷，江鸟暫相隨。","月淨鴛鴦水，春生豆蔻枝。","賞稱佳丽地，君去莫應知。"]', '诗', 'shi', '', NULL, '送客遊江南 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cf37fa7-e435-414d-b713-b6af827ebb54', '送高員外赴淄青使幕', '送高員外赴淄青使幕', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["遠水流春色，回風送落暉。","人趨雙節近，馬遞百花歸。","山驛嘗官酒，關城度客衣。","從來赤管筆，提向幕中稀。"]', '["远水流春色，回风送落暉。","人趨雙節近，马遞百花归。","山驛嘗官酒，关城度客衣。","從来赤管笔，提向幕中稀。"]', '诗', 'shi', '', NULL, '送高員外赴淄青使幕 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fab5b68-7192-44a7-80ef-7d8d88a8bb93', '尋胡處士不遇', '尋胡处士不遇', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["到來心自足，不見亦相親。","說法思居士，忘機憶丈人。","微風吹藥案，晴日照茶巾。","幽興殊未盡，東城飛暮塵。"]', '["到来心自足，不见亦相親。","说法思居士，忘機憶丈人。","微风吹藥案，晴日照茶巾。","幽兴殊未尽，东城飞暮塵。"]', '诗', 'shi', '', NULL, '尋胡處士不遇 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4596de8d-d072-4e80-b359-a4cc9905d8e0', '贈張道者', '贈張道者', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["採藥三山罷，乘風五日歸。","翦荷成舊屋，剉蘗染新衣。","玉粒指應久，丹砂驗不微。","坐看青節引，要與白雲飛。"]', '["採藥三山罷，乘风五日归。","翦荷成旧屋，剉蘗染新衣。","玉粒指應久，丹砂驗不微。","坐看青節引，要與白云飞。"]', '诗', 'shi', '', NULL, '贈張道者 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e55d4da1-30b7-4498-b456-650ec5ca908c', '題蘇許公林亭', '題蘇許公林亭', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["平津東閣在，別是竹林期。","萬葉秋聲裏，千家落照時。","門隨深巷靜，窗過遠鐘遲。","客舍苔生處，依依又賦詩。"]', '["平津东閣在，別是竹林期。","万葉秋声裏，千家落照时。","门隨深巷静，窗過远鐘遲。","客舍苔生处，依依又賦诗。"]', '诗', 'shi', '', NULL, '題蘇許公林亭 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d98b5dcd-5189-4e53-948a-9be6745b10d4', '送元詵還江東', '送元詵還江东', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["過江秋色在，詩興與歸心。","客路隨楓岸，人家掃橘林。","潮聲當晝起，山翠近南深。","幾日華陽洞，寒花引獨尋。"]', '["過江秋色在，诗兴與归心。","客路隨楓岸，人家掃橘林。","潮声當晝起，山翠近南深。","幾日华陽洞，寒花引独尋。"]', '诗', 'shi', '', NULL, '送元詵還江東 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4e73e49-bf61-4ef5-a45a-60feff913a4a', '送客遊江南', '送客游江南', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["桂水隨去遠，賞心知有餘。","衣香楚山橘，手鱠湘波魚。","芳芷不共把，浮雲悵離居。","遙想汩羅上，弔屈秋風初。"]', '["桂水隨去远，賞心知有餘。","衣香楚山橘，手鱠湘波鱼。","芳芷不共把，浮云悵離居。","遙想汩羅上，弔屈秋风初。"]', '诗', 'shi', '', NULL, '送客遊江南 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85cc7beb-8663-4cf2-9ae6-d02f2bc2035d', '送海州姚別駕', '送海州姚別駕', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["少年爲長史，東去事諸侯。","坐覺千閭靜，閑隨五馬遊。","行人楚國道，暮雪鬱林州。","他日知相憶，春風海上樓。"]', '["少年爲长史，东去事諸侯。","坐覺千閭静，闲隨五马游。","行人楚国道，暮雪鬱林州。","他日知相憶，春风海上楼。"]', '诗', 'shi', '', NULL, '送海州姚別駕 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11b6c062-596f-467a-89ab-ac3d2e52641d', '送夏侯審', '送夏侯審', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["謝公鄰里在，日夕問佳期。","春水人歸後，東田花盡時。","下樓閑待月，行樂笑題詩。","他日吳中路，千山入夢思。"]', '["謝公鄰里在，日夕问佳期。","春水人归後，东田花尽时。","下楼闲待月，行乐笑題诗。","他日吳中路，千山入梦思。"]', '诗', 'shi', '', NULL, '送夏侯審 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cfb41db-b6a7-4ec1-b254-6720d26601ae', '送趙評事赴洪州使幕', '送趙評事赴洪州使幕', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["孤舟行遠近，一路過湘東。","官屬張廷尉，身隨杜幼公。","山河映湘竹，水驛帶青楓。","萬里思君處，秋江夜雨中。"]', '["孤舟行远近，一路過湘东。","官屬張廷尉，身隨杜幼公。","山河映湘竹，水驛带青楓。","万里思君处，秋江夜雨中。"]', '诗', 'shi', '', NULL, '送趙評事赴洪州使幕 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ef99529-2556-4540-b085-b892572cd861', '送李侍御赴徐州行營', '送李侍御赴徐州行營', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["少年兼柱史，東至舊徐州。","遠屬平津閣，前驅博望侯。","向營淮水滿，吹角楚天秋。","客夢依依處，寒山對白樓。"]', '["少年兼柱史，东至旧徐州。","远屬平津閣，前驱博望侯。","向營淮水满，吹角楚天秋。","客梦依依处，寒山对白楼。"]', '诗', 'shi', '', NULL, '送李侍御赴徐州行營 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('146e6923-f487-44c2-b053-293bbb390b6a', '送李秀才歸江南', '送李秀才归江南', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["過淮芳草歇，千里又東歸。","野水吳山出，家林越鳥飛。","荷香隨去棹，梅雨點行衣。","無數滄江客，如君達者稀。"]', '["過淮芳草歇，千里又东归。","野水吳山出，家林越鸟飞。","荷香隨去棹，梅雨点行衣。","無數滄江客，如君達者稀。"]', '诗', 'shi', '', NULL, '送李秀才歸江南 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e96257fa-e83d-4c41-96f3-b78e53831550', '題僧房', '題僧房', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["披衣聞客至，關鎖此時開。","鳴罄夕陽盡，捲簾秋色來。","名香連竹徑，清梵出花臺。","身在心無住，他方到幾回。"]', '["披衣闻客至，关鎖此时开。","鳴罄夕陽尽，捲簾秋色来。","名香連竹徑，清梵出花台。","身在心無住，他方到幾回。"]', '诗', 'shi', '', NULL, '題僧房 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20de4d54-9f65-41e9-9c59-00f87670207a', '送壽州陳錄事', '送壽州陳錄事', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["壽陽南渡口，斂笏見諸侯。","五兩楚雲暮，千家淮水秋。","開簾對芳草，送客上春洲。","請問山中桂，王孫幾度遊。"]', '["壽陽南渡口，斂笏见諸侯。","五兩楚云暮，千家淮水秋。","开簾对芳草，送客上春洲。","請问山中桂，王孫幾度游。"]', '诗', 'shi', '', NULL, '送壽州陳錄事 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e11a480e-d654-42bd-9ffb-c73a36b28441', '送趙陸司兵歸使幕', '送趙陸司兵归使幕', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["客路青蕪遍，關城白日低。","身趨雙節近，名共五雲齊。","遠水公田上，春山郡舍西。","無因得攜手，東望轉悽悽。"]', '["客路青蕪遍，关城白日低。","身趨雙節近，名共五云齊。","远水公田上，春山郡舍西。","無因得携手，东望轉悽悽。"]', '诗', 'shi', '', NULL, '送趙陸司兵歸使幕 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81e75b1d-cebd-497a-9418-ba49ea11332b', '送蔣員外端公歸淮南', '送蔣員外端公归淮南', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["淮南芳草色，日夕引歸船。","御史王元貺，郎官顧彥先。","光風千日暖，寒食百花燃。","惆悵佳期近，澄江與暮天。"]', '["淮南芳草色，日夕引归船。","御史王元貺，郎官顧彥先。","光风千日暖，寒食百花燃。","惆悵佳期近，澄江與暮天。"]', '诗', 'shi', '', NULL, '送蔣員外端公歸淮南 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2c3957f-77eb-42bc-a2ae-0337b317a053', '題慈仁寺竹院', '題慈仁寺竹院', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["千峰對古寺，何異到西林。","幽罄蟬聲下，閑窗竹翠陰。","詩人謝客興，法侶遠公心。","寂寂爐煙裏，香花欲暮深。"]', '["千峰对古寺，何異到西林。","幽罄蟬声下，闲窗竹翠陰。","诗人謝客兴，法侶远公心。","寂寂爐煙裏，香花欲暮深。"]', '诗', 'shi', '', NULL, '題慈仁寺竹院 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fdca876-c4f1-470e-8a67-870d125662d5', '贈鄆州馬使君', '贈鄆州马使君', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["東方千馬騎，出望使君時。","暮雪行看盡，春城到莫遲。","路人趨墨幘，官柳度青絲。","他日鈴齋內，知君亦賦詩。"]', '["东方千马騎，出望使君时。","暮雪行看尽，春城到莫遲。","路人趨墨幘，官柳度青絲。","他日鈴斋內，知君亦賦诗。"]', '诗', 'shi', '', NULL, '贈鄆州馬使君 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7ba668e-13bd-43f5-8957-a35b65d22a69', '送張丞歸使幕', '送張丞归使幕', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["獨受主恩歸，當朝似者稀。","玉壺分御酒，金殿賜春衣。","拂席流鶯醉，鳴鞭駿馬肥。","滿臺簪白筆，捧手戀清暉。"]', '["独受主恩归，當朝似者稀。","玉壺分御酒，金殿賜春衣。","拂席流鶯醉，鳴鞭駿马肥。","满台簪白笔，捧手戀清暉。"]', '诗', 'shi', '', NULL, '送張丞歸使幕 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92d193cc-bb31-43b0-b068-47192b8b75ec', '贈長洲何主簿', '贈长洲何主簿', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["挂席逐歸流，依依望虎丘。","殘春過楚縣，夜雨宿吳洲。","野寺吟詩入，溪橋折筍游。","到官無一事，清靜有諸侯。"]', '["挂席逐归流，依依望虎丘。","殘春過楚縣，夜雨宿吳洲。","野寺吟诗入，溪橋折筍游。","到官無一事，清静有諸侯。"]', '诗', 'shi', '', NULL, '贈長洲何主簿 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ad4c6b9-3f4e-4bc6-b14d-d3aed0ce3bd7', '送崔過歸淄青幕府', '送崔過归淄青幕府', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["平陵車馬客，海上見旌旗。","舊驛千山下，殘花一路時。","春衣過水冷，暮雨出關遲。","莫道青州客，迢迢在夢思。"]', '["平陵车马客，海上见旌旗。","旧驛千山下，殘花一路时。","春衣過水冷，暮雨出关遲。","莫道青州客，迢迢在梦思。"]', '诗', 'shi', '', NULL, '送崔過歸淄青幕府 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa33df0c-ba55-4d68-b66e-5dc0ca6d4dfb', '田倉曹東亭夏夜飲得春字', '田倉曹东亭夏夜饮得春字', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["薛公門下人，公子又相親。","玉佩迎初夜，金壺醉老春。","葛衣香有露，羅幕靜無塵。","更羨風流外，文章是一秦。"]', '["薛公门下人，公子又相親。","玉佩迎初夜，金壺醉老春。","葛衣香有露，羅幕静無塵。","更羨风流外，文章是一秦。"]', '诗', 'shi', '', NULL, '田倉曹東亭夏夜飲得春字 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6e8b758-e69f-41c5-9aa7-a5581b95f176', '贈王逖', '贈王逖', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["端笏事龍樓，思閑輙告休。","新調赭白馬，暫試黑貂裘。","珠履迎佳客，金錢與莫愁。","座中豪貴滿，誰道不風流。"]', '["端笏事龙楼，思闲輙告休。","新調赭白马，暫試黑貂裘。","珠履迎佳客，金錢與莫愁。","座中豪貴满，誰道不风流。"]', '诗', 'shi', '', NULL, '贈王逖 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a1b96b6-a498-472c-95ea-db26750163f8', '送深州吳司馬歸使幕', '送深州吳司马归使幕', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["東門送遠客，車馬正紛紛。","舊識張京兆，新隨劉領軍。","行驄看暮雨，歸雁踏青雲。","一去藂臺北，佳聲幾日聞。"]', '["东门送远客，车马正紛紛。","旧識張京兆，新隨劉領軍。","行驄看暮雨，归雁踏青云。","一去藂台北，佳声幾日闻。"]', '诗', 'shi', '', NULL, '送深州吳司馬歸使幕 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd6ce904-eab8-49b5-b11d-59e879262177', '華亭夜宴庾侍御宅', '华亭夜宴庾侍御宅', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["世故他年別，心期此夜同。","千峰孤燭外，片雨一更中。","酒客逢山簡，詩人得謝公。","自憐驅匹馬，拂曙向關東。"]', '["世故他年別，心期此夜同。","千峰孤燭外，片雨一更中。","酒客逢山簡，诗人得謝公。","自怜驱匹马，拂曙向关东。"]', '诗', 'shi', '', NULL, '華亭夜宴庾侍御宅 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7241e2c5-7d41-4cbd-86d7-9be3e63208f7', '送客之上谷', '送客之上谷', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["北客悲秋色，田園憶去來。","披衣朝易水，匹馬夕燕臺。","風翦荷花碎，霜迎栗罅開。","賞心知不淺，累月故人杯。"]', '["北客悲秋色，田园憶去来。","披衣朝易水，匹马夕燕台。","风翦荷花碎，霜迎栗罅开。","賞心知不淺，累月故人杯。"]', '诗', 'shi', '', NULL, '送客之上谷 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15520925-c4b7-4f94-a3dd-e79e48420c45', '同中書劉舍人題青龍上房', '同中书劉舍人題青龙上房', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["西掖歸來後，東林靜者期。","遠峰春雪裏，寒竹暮天時。","笑說金人偈，閑聽寶月詩。","更憐茶興在，好出下方遲。"]', '["西掖归来後，东林静者期。","远峰春雪裏，寒竹暮天时。","笑说金人偈，闲听寶月诗。","更怜茶兴在，好出下方遲。"]', '诗', 'shi', '', NULL, '同中書劉舍人題青龍上房 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5011f528-4984-4fd1-a7dc-bb41a033c017', '宴吳王宅', '宴吳王宅', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["玉管簫聲合，金盃酒色殷。","聽歌吳季札，縱飲漢中山。","稱壽爭離席，留歡輙上關。","莫言辭客醉，猶得曳裾還。"]', '["玉管簫声合，金盃酒色殷。","听歌吳季札，縱饮漢中山。","稱壽爭離席，留歡輙上关。","莫言辞客醉，猶得曳裾還。"]', '诗', 'shi', '', NULL, '宴吳王宅 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bcfad28-8899-4e64-a87c-5d45a7dddd37', '題薦福寺衡嶽暕師房', '題薦福寺衡嶽暕師房', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["春城乞食還，高論此中閑。","僧臘堦前樹，禪心江上山。","疎簾看雪卷，深戶映花關。","晚送門人出，鐘聲杳靄間。"]', '["春城乞食還，高論此中闲。","僧臘堦前樹，禪心江上山。","疎簾看雪卷，深戶映花关。","晚送门人出，鐘声杳靄间。"]', '诗', 'shi', '', NULL, '題薦福寺衡嶽暕師房 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b444a852-7d07-490b-a0fd-a880e200216f', '送戴廸赴鳳翔幕府', '送戴廸赴鳳翔幕府', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["青春帶文綬，去事魏征西。","上路金羇出，中人玉筯齊。","當歌酒萬斛，看獵馬千蹄。","自有從軍樂，何須怨解攜。"]', '["青春带文綬，去事魏征西。","上路金羇出，中人玉筯齊。","當歌酒万斛，看獵马千蹄。","自有從軍乐，何須怨解携。"]', '诗', 'shi', '', NULL, '送戴廸赴鳳翔幕府 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c747b1e2-2035-40be-acfa-ec1ae2d352de', '送郢州郎使君', '送郢州郎使君', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["千人插羽迎，知是范宣城。","暮雪楚山冷，春江漢水清。","紅鮮供客飯，翠竹引舟行。","一別何時見，相思芳草生。"]', '["千人插羽迎，知是范宣城。","暮雪楚山冷，春江漢水清。","紅鲜供客飯，翠竹引舟行。","一別何时见，相思芳草生。"]', '诗', 'shi', '', NULL, '送郢州郎使君 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d94a7b3-72a6-46ff-859f-b92a2db403df', '送李中丞赴辰州', '送李中丞赴辰州', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["白羽逐青絲，翩翩南下時。","巴人迎道路，蠻帥引旌旗。","暮雨山開少，秋江葉落遲。","功成益地日，應見竹郎祠。"]', '["白羽逐青絲，翩翩南下时。","巴人迎道路，蠻帥引旌旗。","暮雨山开少，秋江葉落遲。","功成益地日，應见竹郎祠。"]', '诗', 'shi', '', NULL, '送李中丞赴辰州 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19a3c463-3ce0-4051-b182-578fe08cd3d9', '送劉侍御赴陝州', '送劉侍御赴陝州', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["金羈映驌驦，後騎佩干將。","把酒春城晚，鳴鞭曉路長。","帶冰新溜澀，間雪早梅香。","明日懷賢處，依依御史牀。"]', '["金羈映驌驦，後騎佩干將。","把酒春城晚，鳴鞭晓路长。","带冰新溜澀，间雪早梅香。","明日懷賢处，依依御史牀。"]', '诗', 'shi', '', NULL, '送劉侍御赴陝州 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c099d08d-a94e-43e2-9d4c-ed3718f6c64b', '李中丞宅夜宴送丘侍御赴江東便往辰州', '李中丞宅夜宴送丘侍御赴江东便往辰州', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["積雪臨階夜，重裘對酒時。","中丞違沈約，才子送丘遲。","一路三江上，孤舟萬里期。","辰州佳興在，他日寄新詩。"]', '["積雪臨階夜，重裘对酒时。","中丞違沈約，才子送丘遲。","一路三江上，孤舟万里期。","辰州佳兴在，他日寄新诗。"]', '诗', 'shi', '', NULL, '李中丞宅夜宴送丘侍御赴江東便往辰州 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0186b0f2-2b80-4b51-a488-dd8d9d3733d4', '送李侍御歸宣州使幕', '送李侍御归宣州使幕', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["春草東江外，翩翩北路歸。","官齊魏公子，身逐謝玄暉。","山色隨行騎，鶯聲傍客衣。","主人池上酌，攜手暮花飛。"]', '["春草东江外，翩翩北路归。","官齊魏公子，身逐謝玄暉。","山色隨行騎，鶯声傍客衣。","主人池上酌，携手暮花飞。"]', '诗', 'shi', '', NULL, '送李侍御歸宣州使幕 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e2768c1-3384-4c56-b865-dc2ab0e03210', '東城水亭宴李侍御副使', '东城水亭宴李侍御副使', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["東門留客處，沽酒用錢刀。","秋水牀下急，斜暉林外高。","金羇絡騕褭，玉匣閉豪曹。","去日隨戎幕，東風見伯勞。"]', '["东门留客处，沽酒用錢刀。","秋水牀下急，斜暉林外高。","金羇絡騕褭，玉匣閉豪曹。","去日隨戎幕，东风见伯勞。"]', '诗', 'shi', '', NULL, '東城水亭宴李侍御副使 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2dac645-ea92-432b-bc76-6656f5515a94', '送祕書謝監赴江西使幕', '送祕书謝監赴江西使幕', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["謝監憶山程，辭家萬里行。","寒衣傍楚色，孤枕宿潮聲。","小寇不足問，新詩應漸清。","府公相待日，引斾出江城。"]', '["謝監憶山程，辞家万里行。","寒衣傍楚色，孤枕宿潮声。","小寇不足问，新诗應漸清。","府公相待日，引斾出江城。"]', '诗', 'shi', '', NULL, '送祕書謝監赴江西使幕 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fb425e3-3a20-479a-b171-f4cc68a1825e', '送江陵元司錄', '送江陵元司錄', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["新領州從事，曾爲朝大夫。","江城竹使待，山路橘官扶。","片雨三江道，殘秋五葉湖。","能令詩思好，楚色與寒蕪。"]', '["新領州從事，曾爲朝大夫。","江城竹使待，山路橘官扶。","片雨三江道，殘秋五葉湖。","能令诗思好，楚色與寒蕪。"]', '诗', 'shi', '', NULL, '送江陵元司錄 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71a22c58-646f-4873-b4c2-37882778875b', '送李舍人攜家歸江東覲省', '送李舍人携家归江东覲省', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["二十青宮吏，成名似者稀。","承顏陸郎去，攜手謝娘歸。","夜月回孤燭，秋風試夾衣。","扁舟楚水上，來往速如飛。"]', '["二十青宮吏，成名似者稀。","承顏陸郎去，携手謝娘归。","夜月回孤燭，秋风試夾衣。","扁舟楚水上，来往速如飞。"]', '诗', 'shi', '', NULL, '送李舍人攜家歸江東覲省 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed4a9d77-5c29-469c-8165-6ea61fd94f1a', '送劉侍御赴令公行營', '送劉侍御赴令公行營', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["東城躍紫騮，西路大刀頭。","上客劉公幹，元戎郭細侯。","一軍偏許國，百戰又防秋。","請問蕭關道，胡塵早晚收。"]', '["东城躍紫騮，西路大刀头。","上客劉公幹，元戎郭細侯。","一軍偏許国，百戰又防秋。","請问蕭关道，胡塵早晚收。"]', '诗', 'shi', '', NULL, '送劉侍御赴令公行營 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30dafbe3-d073-47c6-8162-f13c61e9676d', '送蘇州姚長史', '送蘇州姚长史', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["江城驛路長，煙樹過雲陽。","舟領青絲纜，人歌白玉郎。","葛衣行柳翠，花簟宿荷香。","別有心期處，湖光滿訟堂。"]', '["江城驛路长，煙樹過云陽。","舟領青絲纜，人歌白玉郎。","葛衣行柳翠，花簟宿荷香。","別有心期处，湖光满訟堂。"]', '诗', 'shi', '', NULL, '送蘇州姚長史 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37fad560-b78b-470a-99c6-a557958d0b3c', '送金華王明府', '送金华王明府', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["縣舍江雲裏，心閑境又偏。","家貧陶令酒，月俸沈郎錢。","黃蘗香山路，青楓暮雨天。","時聞引車騎，竹外到銅泉。"]', '["縣舍江云裏，心闲境又偏。","家貧陶令酒，月俸沈郎錢。","黄蘗香山路，青楓暮雨天。","时闻引车騎，竹外到銅泉。"]', '诗', 'shi', '', NULL, '送金華王明府 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba3767e8-52a3-4a53-a56a-7f5dd77dee68', '送田倉曹汴州覲省', '送田倉曹汴州覲省', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["拜慶承天寵，朝來辭漢宮。","玉杯分湛露，金勒借追風。","古驛秋山下，平蕪暮雨中。","翩翩魏公子，人看渡關東。"]', '["拜慶承天寵，朝来辞漢宮。","玉杯分湛露，金勒借追风。","古驛秋山下，平蕪暮雨中。","翩翩魏公子，人看渡关东。"]', '诗', 'shi', '', NULL, '送田倉曹汴州覲省 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2da8b3fa-3e96-4b18-b529-24422f24f4ef', '送張渚赴越州', '送張渚赴越州', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["白面誰家郎，青驪照地光。","桃花開綬色，蘇合借衣香。","暮雪連峰近，春江海市長。","風流似張緒，別後見垂楊。"]', '["白面誰家郎，青驪照地光。","桃花开綬色，蘇合借衣香。","暮雪連峰近，春江海市长。","风流似張緒，別後见垂楊。"]', '诗', 'shi', '', NULL, '送張渚赴越州 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d11d2ba-6ffb-4f62-92f5-6e8e9b099e97', '奉和元相公家園即事寄王相公', '奉和元相公家园即事寄王相公', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["共列中台貴，能齊物外心。","回車青閣晚，解帶碧茸深。","寒水分畦入，晴花度竹尋。","題詩更相憶，一字重千金。"]', '["共列中台貴，能齊物外心。","回车青閣晚，解带碧茸深。","寒水分畦入，晴花度竹尋。","題诗更相憶，一字重千金。"]', '诗', 'shi', '', NULL, '奉和元相公家園即事寄王相公 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27deddfa-8ab0-426b-b849-b55405959d5b', '送道士姪歸池陽', '送道士姪归池陽', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["銀角桃枝杖，東門贈別初。","幽州尋馬客，灞岸送驢車。","野飯秋山靜，行衣落照餘。","燕南羣從少，此去意何如。"]', '["銀角桃枝杖，东门贈別初。","幽州尋马客，灞岸送驢车。","野飯秋山静，行衣落照餘。","燕南羣從少，此去意何如。"]', '诗', 'shi', '', NULL, '送道士姪歸池陽 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04d20df6-acac-4dcb-a54b-1be98c4e740e', '送劉長上歸城南別業', '送劉长上归城南別業', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["數刻是歸程，花間落照明。","春衣香不散，駿馬汗猶輕。","南渡春流淺，西風片雨晴。","朝還會相就，飯爾五侯鯖。"]', '["數刻是归程，花间落照明。","春衣香不散，駿马汗猶轻。","南渡春流淺，西风片雨晴。","朝還會相就，飯爾五侯鯖。"]', '诗', 'shi', '', NULL, '送劉長上歸城南別業 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13221990-df4d-4102-a1d6-381d15d089f8', '贈張五諲歸濠州別業', '贈張五諲归濠州別業', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["常知罷官意，果與世人疎。","復此涼風起，仍聞濠上居。","故山期採菊，秋水憶觀魚。","一去蓬蒿逕，羨君閑有餘。"]', '["常知罷官意，果與世人疎。","复此涼风起，仍闻濠上居。","故山期採菊，秋水憶观鱼。","一去蓬蒿逕，羨君闲有餘。"]', '诗', 'shi', '', NULL, '贈張五諲歸濠州別業 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f03a16fb-dbb5-438e-994b-c51f89e1efbb', '送營城李少府', '送營城李少府', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["懷錄兼就養，更懷趨府心。","晴山東里近，春水北門深。","新綬映芳草，舊家依遠林。","還乘鄭小駟，躞蹀縣城陰。"]', '["懷錄兼就養，更懷趨府心。","晴山东里近，春水北门深。","新綬映芳草，旧家依远林。","還乘鄭小駟，躞蹀縣城陰。"]', '诗', 'shi', '', NULL, '送營城李少府 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b26ec135-4929-4076-a792-be57d748e820', '魯中送魯使君歸鄭州', '魯中送魯使君归鄭州', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["城中金絡騎，出餞沈東陽。","九月寒露白，六關秋草黃。","齊謳聽處妙，魯酒把來香。","醉後著鞭去，梅山道路長。"]', '["城中金絡騎，出餞沈东陽。","九月寒露白，六关秋草黄。","齊謳听处妙，魯酒把来香。","醉後著鞭去，梅山道路长。"]', '诗', 'shi', '', NULL, '魯中送魯使君歸鄭州 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59c50aa1-116c-4c99-bad7-83468ccd958a', '送夏侯校書歸上都', '送夏侯校书归上都', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["後輩傳佳句，高流愛美名。","青春事賀監，黃卷問張生。","暮雪重裘醉，寒山匹馬行。","此回將詣闕，幾日諫書成。"]', '["後輩傳佳句，高流愛美名。","青春事賀監，黄卷问張生。","暮雪重裘醉，寒山匹马行。","此回將詣闕，幾日諫书成。"]', '诗', 'shi', '', NULL, '送夏侯校書歸上都 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a36d2096-432b-4a13-8527-0110a781f74f', '送李明府赴連州', '送李明府赴連州', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["萬里向南湘，孤舟入桂陽。","諸侯迎上客，小吏拜官郎。","春服橦花細，初筵木槿芳。","看承雨露速，不待荔枝香。"]', '["万里向南湘，孤舟入桂陽。","諸侯迎上客，小吏拜官郎。","春服橦花細，初筵木槿芳。","看承雨露速，不待荔枝香。"]', '诗', 'shi', '', NULL, '送李明府赴連州 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3318ab7f-2f67-47df-af04-a611064d22bb', '送盧大理趙侍御祭東嶽兼寄孟衮州', '送盧大理趙侍御祭东嶽兼寄孟衮州', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["東嶽昔有事，兩臣朝望歸。","驛亭開歲酒，齋舍著新衣。","上客鍾大理，主人陶武威。","仍隨御史馬，山路滿光輝。"]', '["东嶽昔有事，兩臣朝望归。","驛亭开歲酒，斋舍著新衣。","上客鍾大理，主人陶武威。","仍隨御史马，山路满光輝。"]', '诗', 'shi', '', NULL, '送盧大理趙侍御祭東嶽兼寄孟衮州 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afa6753b-8bdb-4e63-a41c-88a0f9294c6a', '送皇甫大夫赴浙東', '送皇甫大夫赴浙东', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["舟師分水國，漢將領秦官。","麾下同心吏，軍中囗囗端。","吳門秋露溼，楚驛暮天寒。","豪貴東山去，風流勝謝安。"]', '["舟師分水国，漢將領秦官。","麾下同心吏，軍中囗囗端。","吳门秋露溼，楚驛暮天寒。","豪貴东山去，风流勝謝安。"]', '诗', 'shi', '', NULL, '送皇甫大夫赴浙東 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d420df8-bf77-44be-9254-8b514a4f6b9b', '送韋秀才', '送韋秀才', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["東人相見罷，秋草獨歸時。","幾日孫弘閣，當年謝朓詩。","寒山葉落早，多雨路行遲。","好憶金門步，功名自有期。"]', '["东人相见罷，秋草独归时。","幾日孫弘閣，當年謝朓诗。","寒山葉落早，多雨路行遲。","好憶金门步，功名自有期。"]', '诗', 'shi', '', NULL, '送韋秀才 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a3afe60-f683-4e4f-a11d-ecfd38c7dc98', '送客一歸襄陽二歸潯陽', '送客一归襄陽二归潯陽', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["南驅匹馬會心期，東望扁舟愜夢思。","熨斗山前春色早，香爐峰頂暮煙時。","空林欲訪龐居士，古寺應懷遠法師。","兩地由來堪取興，三賢他日幸留詩。"]', '["南驱匹马會心期，东望扁舟愜梦思。","熨斗山前春色早，香爐峰頂暮煙时。","空林欲訪龐居士，古寺應懷远法師。","兩地由来堪取兴，三賢他日幸留诗。"]', '诗', 'shi', '', NULL, '送客一歸襄陽二歸潯陽 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d31a6edd-8609-47c6-9973-7f5c5fbb3eb7', '送故人赴江陵尋庾牧', '送故人赴江陵尋庾牧', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["主人持節拜荆州，走馬應從一路遊。","斑竹岡連山雨暗，枇杷門向楚天秋。","佳期笑把齋中酒，遠意閑登城上樓。","文體此時看又別，吾知小庾甚風流。"]', '["主人持節拜荆州，走马應從一路游。","斑竹岡連山雨暗，枇杷门向楚天秋。","佳期笑把斋中酒，远意闲登城上楼。","文體此时看又別，吾知小庾甚风流。"]', '诗', 'shi', '', NULL, '送故人赴江陵尋庾牧 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01a80b15-c6bc-4315-8dbc-fd2285f8b4aa', '送客水路歸陝', '送客水路归陝', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["相風竿影曉來斜，渭水東流去不賒。","枕上未醒秦地酒，舟前已見陝人家。","春橋楊柳應齊葉，古縣棠棃也作花。","好是吾賢佳賞地，行逢三月會連沙。"]', '["相风竿影晓来斜，渭水东流去不賒。","枕上未醒秦地酒，舟前已见陝人家。","春橋楊柳應齊葉，古縣棠棃也作花。","好是吾賢佳賞地，行逢三月會連沙。"]', '诗', 'shi', '', NULL, '送客水路歸陝 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64523283-a09b-490b-ae50-f88023ecff9e', '送丹陽劉太真', '送丹陽劉太真', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["長干道上落花朝，羨爾當年賞事饒。","下筯已憐鵝炙美，開籠不奈鴨媒嬌。","春衣晚入青楊巷，細馬初過皂莢橋。","相訪不辭千里遠，西風好借木蘭橈。"]', '["长干道上落花朝，羨爾當年賞事饒。","下筯已怜鵝炙美，开籠不奈鴨媒嬌。","春衣晚入青楊巷，細马初過皂莢橋。","相訪不辞千里远，西风好借木蘭橈。"]', '诗', 'shi', '', NULL, '送丹陽劉太真 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7641ad3-b54a-476a-a72a-097328b264c1', '送客歸江州', '送客归江州', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["東歸復得采真遊，江水迎君日夜流。","客舍不離青雀舫，人家舊在白鷗洲。","風吹山帶遙知雨，露溼荷裳已報秋。","聞道泉明居止近，籃輿相訪爲淹留。"]', '["东归复得采真游，江水迎君日夜流。","客舍不離青雀舫，人家旧在白鷗洲。","风吹山带遙知雨，露溼荷裳已報秋。","闻道泉明居止近，籃輿相訪爲淹留。"]', '诗', 'shi', '', NULL, '送客歸江州 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a4a17b2-9471-40ba-ab49-1b83297af8a8', '題張逸人園林', '題張逸人园林', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["花源一曲映茅堂，清論閑階坐夕陽。","麈尾手中毛已脫，蟹螯尊上味初香。","春深黃口傳窺樹，雨後青苔散點牆。","更道小山宜助賞，呼兒舒簟醉巖芳。"]', '["花源一曲映茅堂，清論闲階坐夕陽。","麈尾手中毛已脫，蟹螯尊上味初香。","春深黄口傳窺樹，雨後青苔散点牆。","更道小山宜助賞，呼兒舒簟醉巖芳。"]', '诗', 'shi', '', NULL, '題張逸人園林 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2203760-0a7a-4392-8da7-159116242be4', '又題張逸人園林', '又題張逸人园林', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["藏頭不復見時人，愛此雲山奉養真。","露色點衣孤嶼曉，花枝妨帽小園春。","時攜幼稚諸峰上，閑濯眉須一水濱。","興罷歸來還對酌，茅檐挂著紫荷巾。"]', '["藏头不复见时人，愛此云山奉養真。","露色点衣孤嶼晓，花枝妨帽小园春。","时携幼稚諸峰上，闲濯眉須一水濱。","兴罷归来還对酌，茅檐挂著紫荷巾。"]', '诗', 'shi', '', NULL, '又題張逸人園林 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12aea2eb-9568-42b6-860d-24b40fb86825', '送劉將軍', '送劉將軍', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["明光細甲照錏鍛，昨日承恩拜虎牙。","膽大欲期姜伯約，功多不讓李輕車。","青巾校尉遙相許，墨矟將軍莫大誇。","闕下來時親伏奏，胡塵未盡不爲家。"]', '["明光細甲照錏鍛，昨日承恩拜虎牙。","膽大欲期姜伯約，功多不讓李轻车。","青巾校尉遙相許，墨矟將軍莫大誇。","闕下来时親伏奏，胡塵未尽不爲家。"]', '诗', 'shi', '', NULL, '送劉將軍 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeea4c43-7ada-46ae-81a9-ad4975aec522', '送鄭員外', '送鄭員外', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["風流不減杜陵時，五十爲郎未是遲。","孺子亦知名下士，樂人爭唱卷中詩。","身齊吏部還多醉，心顧尚書自有期。","要路眼青知己在，不應窮巷久低眉。"]', '["风流不減杜陵时，五十爲郎未是遲。","孺子亦知名下士，乐人爭唱卷中诗。","身齊吏部還多醉，心顧尚书自有期。","要路眼青知己在，不應窮巷久低眉。"]', '诗', 'shi', '', NULL, '送鄭員外 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af2e4d75-735e-4f63-a81e-b1b9915d2c2c', '寄徐州鄭使君', '寄徐州鄭使君', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["江城五馬楚雲邊，不羨雍容畫省年。","才子舊稱何水部，使君還繼謝臨川。","射堂草遍收殘雨，官路人稀對夕天。","雖臥郡齋千里隔，與君同見月初圓。"]', '["江城五马楚云邊，不羨雍容畫省年。","才子旧稱何水部，使君還繼謝臨川。","射堂草遍收殘雨，官路人稀对夕天。","雖臥郡斋千里隔，與君同见月初圓。"]', '诗', 'shi', '', NULL, '寄徐州鄭使君 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbb1cb69-0620-43f0-ba72-ea57020358d9', '送襄垣王君歸南陽別墅', '送襄垣王君归南陽別墅', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["都門霽後不飛塵，草色萋萋滿路春。","雙兔坡東千室吏，三鴉水上一歸人。","愁眠客舍衣香滿，走渡河橋馬汗新。","少婦比來多遠望，應知蟢子上羅巾。"]', '["都门霽後不飞塵，草色萋萋满路春。","雙兔坡东千室吏，三鴉水上一归人。","愁眠客舍衣香满，走渡河橋马汗新。","少婦比来多远望，應知蟢子上羅巾。"]', '诗', 'shi', '', NULL, '送襄垣王君歸南陽別墅 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63f3c6dc-30dc-4c1f-98ac-744cfaf96abf', '送王誕渤海使赴李太守行營', '送王誕渤海使赴李太守行營', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["少年結客散黃金，中歲連兵掃綠林。","渤海名王曾折首，漢家諸將盡傾心。","行人去指徐州近，飲馬回看泗水深。","喜見明時鍾太尉，功名一似舊淮陰。"]', '["少年結客散黄金，中歲連兵掃綠林。","渤海名王曾折首，漢家諸將尽傾心。","行人去指徐州近，饮马回看泗水深。","喜见明时鍾太尉，功名一似旧淮陰。"]', '诗', 'shi', '', NULL, '送王誕渤海使赴李太守行營 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('174be7d0-c5ca-4f82-8e5f-1e08cac85403', '送王少府歸杭州', '送王少府归杭州', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["歸舟一路轉青蘋，更欲隨潮向富春。","吳郡陸機稱地主，錢塘蘇小是鄉親。","葛花滿把能消酒，梔子同心好贈人。","早晚重過魚浦宿，遙憐佳句篋中新。"]', '["归舟一路轉青蘋，更欲隨潮向富春。","吳郡陸機稱地主，錢塘蘇小是乡親。","葛花满把能消酒，梔子同心好贈人。","早晚重過鱼浦宿，遙怜佳句篋中新。"]', '诗', 'shi', '', NULL, '送王少府歸杭州 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('367c97eb-901c-4688-ab45-2ee634454c0a', '贈王隨', '贈王隨', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["青雲自致晚應遙，朱邸新婚樂事饒。","飲罷更憐雙袖舞，試來偏愛五花驕。","帳裏爐香春夢曉，堂前燭影早更朝。","更說毬場新雨歇，王孫今日定相邀。"]', '["青云自致晚應遙，朱邸新婚乐事饒。","饮罷更怜雙袖舞，試来偏愛五花驕。","帳裏爐香春梦晓，堂前燭影早更朝。","更说毬場新雨歇，王孫今日定相邀。"]', '诗', 'shi', '', NULL, '贈王隨 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b411ce1e-ac09-4427-ab32-f8dc7a57e566', '同題仙游觀', '同題仙游观', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["仙臺下見五城樓，風物淒淒宿雨收。","山色遙連秦樹晚，砧聲近報漢宮秋。","疎松影落空壇靜，細草香閑小洞幽。","何用別尋方外去，人間亦自有丹丘。"]', '["仙台下见五城楼，风物淒淒宿雨收。","山色遙連秦樹晚，砧声近報漢宮秋。","疎松影落空壇静，細草香闲小洞幽。","何用別尋方外去，人间亦自有丹丘。"]', '诗', 'shi', '', NULL, '同題仙游觀 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3e8a1e0-aa8d-488f-86e9-7957ba5e46cd', '訪王起居不遇留贈', '訪王起居不遇留贈', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["雙龍闕下拜恩初，天子令君注起居。","載筆已齊周右史，論詩更事謝中書。","行聞漏滴隨金仗，入對爐煙侍玉除。","賀客自知來獨晚，青驪不見意何如。"]', '["雙龙闕下拜恩初，天子令君注起居。","載笔已齊周右史，論诗更事謝中书。","行闻漏滴隨金仗，入对爐煙侍玉除。","賀客自知来独晚，青驪不见意何如。"]', '诗', 'shi', '', NULL, '訪王起居不遇留贈 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0205d533-59d4-4fb4-a9e1-f447f6de1134', '送劉評事赴廣州使幕', '送劉評事赴廣州使幕', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["征南官屬似君稀，才子當今劉孝威。","蠻府參軍趨傳舍，交州刺史拜行衣。","前臨瘴海無人過，却望衡陽少雁飛。","爲報蒼梧雲影道，明年早送客帆歸。"]', '["征南官屬似君稀，才子當今劉孝威。","蠻府參軍趨傳舍，交州刺史拜行衣。","前臨瘴海無人過，却望衡陽少雁飞。","爲報蒼梧云影道，明年早送客帆归。"]', '诗', 'shi', '', NULL, '送劉評事赴廣州使幕 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3ed689f-6083-4041-b4d2-8f294506ee0c', '送冷朝陽還上元', '送冷朝陽還上元', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["青絲䋏引木蘭船，名遂身歸拜慶年。","落日澄江烏榜外，秋風疎柳白門前。","橋通小市家林近，山帶平湖野寺連。","別後依依寒食裏，共君攜手在東田。"]', '["青絲䋏引木蘭船，名遂身归拜慶年。","落日澄江烏榜外，秋风疎柳白门前。","橋通小市家林近，山带平湖野寺連。","別後依依寒食裏，共君携手在东田。"]', '诗', 'shi', '', NULL, '送冷朝陽還上元 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00877f47-5209-41c9-b25c-2c0ba2caf637', '送高別駕歸汴州', '送高別駕归汴州', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["信陵門下識君偏，駿馬輕裘正少年。","寒雨送歸千里外，東風沈醉百花前。","身隨玉帳心應愜，官佐龍符勢又全。","久客未知何計是，參差去借汶陽田。"]', '["信陵门下識君偏，駿马轻裘正少年。","寒雨送归千里外，东风沈醉百花前。","身隨玉帳心應愜，官佐龙符勢又全。","久客未知何計是，參差去借汶陽田。"]', '诗', 'shi', '', NULL, '送高別駕歸汴州 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('301b1228-db1f-47f2-9425-a732c65ef0ad', '送康洗馬歸滑州', '送康洗马归滑州', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["腰佩雕弓漢射聲，東歸銜命見雙旌。","青絲玉勒康侯馬，孟水金堤滑伯城。","臘雪夜看宜縱飲，寒蕪晝獵不妨行。","懷君又隔千山遠，別後春風百草生。"]', '["腰佩雕弓漢射声，东归銜命见雙旌。","青絲玉勒康侯马，孟水金堤滑伯城。","臘雪夜看宜縱饮，寒蕪晝獵不妨行。","懷君又隔千山远，別後春风百草生。"]', '诗', 'shi', '', NULL, '送康洗馬歸滑州 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17fb8726-a553-4a26-bd21-7a344ae6c902', '寄上田僕射', '寄上田僕射', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["家封薛縣異諸田，報主榮親義兩全。","僕射臨戎謝安石，大夫持憲杜延年。","金裝晝出羅千騎，玉案晨飡直萬錢。","應念一身留闕下，闔門遙寄魯西偏。"]', '["家封薛縣異諸田，報主榮親義兩全。","僕射臨戎謝安石，大夫持憲杜延年。","金裝晝出羅千騎，玉案晨飡直万錢。","應念一身留闕下，闔门遙寄魯西偏。"]', '诗', 'shi', '', NULL, '寄上田僕射 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bafe4ffc-feca-4394-848c-a3b06d7bbdda', '送王光輔歸青州兼寄儲侍郎', '送王光輔归青州兼寄儲侍郎', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["幾回奏事建章宮，聖主偏知漢將功。","身著紫衣趨闕下，口銜丹詔出關東。","蟬聲驛路秋山裏，草色河橋落照中。","遠憶故人滄海別，當年好躍五花驄。"]', '["幾回奏事建章宮，聖主偏知漢將功。","身著紫衣趨闕下，口銜丹詔出关东。","蟬声驛路秋山裏，草色河橋落照中。","远憶故人滄海別，當年好躍五花驄。"]', '诗', 'shi', '', NULL, '送王光輔歸青州兼寄儲侍郎 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7029b05-dbc0-4c17-84b9-3582767b67ba', '宴楊駙馬山池', '宴楊駙马山池', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["垂楊拂岸草茸茸，繡戶簾前花影重。","鱠下玉盤紅縷細，酒開金甕綠醅濃。","中朝駙馬何平叔，南國詞人陸士龍。","落日泛舟同醉處，回潭百丈映千峰。"]', '["垂楊拂岸草茸茸，繡戶簾前花影重。","鱠下玉盤紅縷細，酒开金甕綠醅濃。","中朝駙马何平叔，南国词人陸士龙。","落日泛舟同醉处，回潭百丈映千峰。"]', '诗', 'shi', '', NULL, '宴楊駙馬山池 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d22c6b8-dc91-46dd-bfe3-8fbbec90b121', '送長史李少府入蜀', '送长史李少府入蜀', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["行行獨出故關遲，南望千山無盡期。","見舞巴童應暫笑，聞歌蜀道又堪悲。","孤城晚閉清江上，匹馬寒嘶白露時。","別後此心君自見，山中何事不相思。"]', '["行行独出故关遲，南望千山無尽期。","见舞巴童應暫笑，闻歌蜀道又堪悲。","孤城晚閉清江上，匹马寒嘶白露时。","別後此心君自见，山中何事不相思。"]', '诗', 'shi', '', NULL, '送長史李少府入蜀 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e388e44d-dfde-4c11-a146-5de448497720', '送客還江東', '送客還江东', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["不妨高臥順流歸，五兩行看掃翠微。","鼯鼠夜喧孤枕近，鵁鶄曉避客船飛。","一壺先醉桃枝簟，百和初熏苧布衣。","君到新林江口泊，吟詩應賞謝玄暉。"]', '["不妨高臥順流归，五兩行看掃翠微。","鼯鼠夜喧孤枕近，鵁鶄晓避客船飞。","一壺先醉桃枝簟，百和初熏苧布衣。","君到新林江口泊，吟诗應賞謝玄暉。"]', '诗', 'shi', '', NULL, '送客還江東 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac9a971b-9802-4303-a76d-fafaa49563df', '寄令狐尚書', '寄令狐尚书', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["立身榮貴復何如，龍節紅旗從板輿。","妙略多推霍驃騎，能文獨見沈尚書。","臨風高會千門帳，映水連營百乘車。","他日感恩慙未報，舉家猶似涸池魚。"]', '["立身榮貴复何如，龙節紅旗從板輿。","妙略多推霍驃騎，能文独见沈尚书。","臨风高會千门帳，映水連營百乘车。","他日感恩慙未報，舉家猶似涸池鱼。"]', '诗', 'shi', '', NULL, '寄令狐尚書 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a68c6d1-adc3-4c46-aaf0-4a199170c382', '扈從郊廟因呈兩省諸公', '扈從郊廟因呈兩省諸公', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["丹墀列士主恩同，廄馬翩翩出漢宮。","奉引乘輿金仗裏，親嘗賜食玉盤中。","晝趨行殿旌門北，夜宿齋房刻漏東。","明日駕迴承雨露，齊將萬歲及春風。"]', '["丹墀列士主恩同，廄马翩翩出漢宮。","奉引乘輿金仗裏，親嘗賜食玉盤中。","晝趨行殿旌门北，夜宿斋房刻漏东。","明日駕迴承雨露，齊將万歲及春风。"]', '诗', 'shi', '', NULL, '扈從郊廟因呈兩省諸公 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bf15138-71d8-4a73-8b8e-d9c7654c9e80', '送端州馮使君', '送端州馮使君', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["白皙風流似有鬚，一門豪貴領蒼梧。","三峰亭暗橘邊宿，八桂林香節下趨。","玉樹羣兒爭翠羽，金盤少妾揀明珠。","懷君樂事不可見，騣馬翩翩新虎符。"]', '["白皙风流似有鬚，一门豪貴領蒼梧。","三峰亭暗橘邊宿，八桂林香節下趨。","玉樹羣兒爭翠羽，金盤少妾揀明珠。","懷君乐事不可见，騣马翩翩新虎符。"]', '诗', 'shi', '', NULL, '送端州馮使君 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ca0e586-2804-4c73-9190-1ccc18267e00', '送王府張參軍附學及第東歸', '送王府張參軍附学及第东归', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["鄰家不識鬬雞翁，閉戶能齊隱者風。","顧步曾爲小山客，成名因事大江公。","一身千里寒蕪上，單馬重裘臘月中。","寂寂故園行見在，暮天殘雪洛城東。"]', '["鄰家不識鬬雞翁，閉戶能齊隐者风。","顧步曾爲小山客，成名因事大江公。","一身千里寒蕪上，單马重裘臘月中。","寂寂故园行见在，暮天殘雪洛城东。"]', '诗', 'shi', '', NULL, '送王府張參軍附學及第東歸 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aea75aac-91ff-4299-8d32-43ef9da2b346', '送齊明府赴東陽', '送齊明府赴东陽', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["綠絲帆繂桂爲檣，過盡淮山楚水長。","萬里移家背春穀，一官行府向東陽。","風流好愛杯中物，豪蕩仍欺陌上郎。","別後心期如在眼，猨聲煙色樹蒼蒼。"]', '["綠絲帆繂桂爲檣，過尽淮山楚水长。","万里移家背春穀，一官行府向东陽。","风流好愛杯中物，豪蕩仍欺陌上郎。","別後心期如在眼，猨声煙色樹蒼蒼。"]', '诗', 'shi', '', NULL, '送齊明府赴東陽 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('880aa6dd-56a3-4432-9d27-f77f724ef37d', '魯中送從事歸滎陽', '魯中送從事归滎陽', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["故園衰草帶滎波，歲晚知如君思何。","輕橐歸時魯縞薄，寒衣縫處鄭綿多。","萬人都督鳴騮送，百里邦君枉騎過。","累路盡逢知己在，曾無對酒不高歌。"]', '["故园衰草带滎波，歲晚知如君思何。","轻橐归时魯縞薄，寒衣縫处鄭綿多。","万人都督鳴騮送，百里邦君枉騎過。","累路尽逢知己在，曾無对酒不高歌。"]', '诗', 'shi', '', NULL, '魯中送從事歸滎陽 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c9db622-4daa-499a-81d6-d991e2b426cd', '衮州送李明府使蘇州便赴告期', '衮州送李明府使蘇州便赴告期', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["莫言水國去迢迢，白馬吳門見不遙。","楓樹林中經楚雨，木蘭舟上蹋江潮。","空山古寺千年石，草色寒隄百尺橋。","早晚盧家蘭室在，珊瑚玉佩徹青霄。"]', '["莫言水国去迢迢，白马吳门见不遙。","楓樹林中經楚雨，木蘭舟上蹋江潮。","空山古寺千年石，草色寒隄百尺橋。","早晚盧家蘭室在，珊瑚玉佩徹青霄。"]', '诗', 'shi', '', NULL, '衮州送李明府使蘇州便赴告期 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf9d968d-510c-4646-8bf6-7844b70a18fb', '送田明府歸終南別業', '送田明府归終南別業', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["故園此日多心賞，窗下泉流竹外雲。","近館應逢沈道士，比鄰自識卞田君。","離宮樹影登山見，上苑鐘聲過雪聞。","相勸早移丹鳳闕，不須常戀白鷗羣。"]', '["故园此日多心賞，窗下泉流竹外云。","近館應逢沈道士，比鄰自識卞田君。","離宮樹影登山见，上苑鐘声過雪闻。","相勸早移丹鳳闕，不須常戀白鷗羣。"]', '诗', 'shi', '', NULL, '送田明府歸終南別業 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('866044e3-2a37-485d-aca7-3de867948317', '家兄自山南罷歸獻詩敘事', '家兄自山南罷归獻诗敘事', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["時輩已爭先，吾兄未著鞭。","空嗟鑷鬚日，猶是屈腰年。","不以殊方遠，仍論水地偏。","襄橙隨客路，漢竹引歸船。","雲木巴東峽，林泉峴北川。","池餘騎馬處，宅似臥龍邊。","夜簟千峰月，朝窗萬井煙。","朱荷江女院，青稻楚人田。","縣舍多瀟灑，城樓入醉眠。","黃苞柑正熟，紅縷鱠仍鮮。","坐厭牽絲倦，因從解綬旋。","初辭五斗米，唯奉一囊錢。","室好生虛白，書耽守太玄。","櫪中嘶欵段，階下引潺湲。","落照淵明柳，春風叔夜弦。","絳紗儒客帳，丹訣羽人篇。","雅論承安石，新詩與惠連。","興清湖見底，襟豁霧開天。","魏闕心猶繫，周才道豈捐。","一丘無自逸，三府會招賢。"]', '["时輩已爭先，吾兄未著鞭。","空嗟鑷鬚日，猶是屈腰年。","不以殊方远，仍論水地偏。","襄橙隨客路，漢竹引归船。","云木巴东峽，林泉峴北川。","池餘騎马处，宅似臥龙邊。","夜簟千峰月，朝窗万井煙。","朱荷江女院，青稻楚人田。","縣舍多瀟灑，城楼入醉眠。","黄苞柑正熟，紅縷鱠仍鲜。","坐厭牽絲倦，因從解綬旋。","初辞五斗米，唯奉一囊錢。","室好生虛白，书耽守太玄。","櫪中嘶欵段，階下引潺湲。","落照淵明柳，春风叔夜弦。","絳紗儒客帳，丹訣羽人篇。","雅論承安石，新诗與惠連。","兴清湖见底，襟豁霧开天。","魏闕心猶繫，周才道豈捐。","一丘無自逸，三府會招賢。"]', '诗', 'shi', '', NULL, '家兄自山南罷歸獻詩敘事 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('362e5391-9347-48d7-a42a-35efebb88ba3', '奉送王相公縉赴幽州巡邊', '奉送王相公縉赴幽州巡邊', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["黃閣開帷幄，丹墀侍冕旒。","位高湯左相，權總漢諸侯。","不改周南化，仍分趙北憂。","雙旌過易水，千騎入幽州。","塞草連天暮，邊風動地秋。","無因隨遠道，結束佩吳鉤。"]', '["黄閣开帷幄，丹墀侍冕旒。","位高湯左相，權總漢諸侯。","不改周南化，仍分趙北憂。","雙旌過易水，千騎入幽州。","塞草連天暮，邊风动地秋。","無因隨远道，結束佩吳鉤。"]', '诗', 'shi', '', NULL, '奉送王相公縉赴幽州巡邊 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27400495-0bfe-4223-a30b-a6c4a1ef4816', '寄贈虢州張參軍', '寄贈虢州張參軍', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["三十事諸侯，賢豪冠北州。","桃花迎駿馬，蘇合染輕裘。","觀妓將軍第，題詩關尹樓。","青林朝送客，綠嶼晚回舟。","好栗分通子，名香贈莫愁。","洗杯新酒熟，把燭故人留。","百雉歸雲過，千峰宿雨收。","蒹葭露下晚，菡萏水中秋。","憶昨陪行樂，常時接獻酬。","佳期雖霧散，惠問亦川流。","開卷酲堪解，含毫思苦抽。","無因達情意，西望日悠悠。"]', '["三十事諸侯，賢豪冠北州。","桃花迎駿马，蘇合染轻裘。","观妓將軍第，題诗关尹楼。","青林朝送客，綠嶼晚回舟。","好栗分通子，名香贈莫愁。","洗杯新酒熟，把燭故人留。","百雉归云過，千峰宿雨收。","蒹葭露下晚，菡萏水中秋。","憶昨陪行乐，常时接獻酬。","佳期雖霧散，惠问亦川流。","开卷酲堪解，含毫思苦抽。","無因達情意，西望日悠悠。"]', '诗', 'shi', '', NULL, '寄贈虢州張參軍 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c45227f-c9a5-403e-a742-01a617a66ce2', '送李中丞赴商州', '送李中丞赴商州', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["五馬渭橋東，連嘶逐曉風。","當年紫髯將，他日黑頭公。","不異金吾寵，兼齊玉帳雄。","閉營春雪下，吹角暮山空。","香麝松陰裏，寒猨黛色中。","郡齋多賞事，好與故人同。"]', '["五马渭橋东，連嘶逐晓风。","當年紫髯將，他日黑头公。","不異金吾寵，兼齊玉帳雄。","閉營春雪下，吹角暮山空。","香麝松陰裏，寒猨黛色中。","郡斋多賞事，好與故人同。"]', '诗', 'shi', '', NULL, '送李中丞赴商州 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd5b7b5d-6e30-449b-a44a-be293eb76a9d', '漢宮曲二首 一', '漢宮曲二首 一', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["駿馬繡障泥，紅塵撲四蹄。","歸時何太晚，日照杏花西。"]', '["駿马繡障泥，紅塵撲四蹄。","归时何太晚，日照杏花西。"]', '诗', 'shi', '', NULL, '漢宮曲二首 一 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('794686a6-fc91-4d55-a50d-dfeda75dc75b', '漢宮曲二首 二', '漢宮曲二首 二', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["繡幕珊瑚鉤，春開翡翠樓。","深情不肯道，嬌倚鈿箜篌。"]', '["繡幕珊瑚鉤，春开翡翠楼。","深情不肯道，嬌倚鈿箜篌。"]', '诗', 'shi', '', NULL, '漢宮曲二首 二 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceae777e-f781-4d5a-ab55-33cd1a42effa', '陪孟都督祭嶽途中有贈', '陪孟都督祭嶽途中有贈', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["封疆七百里，祿秩二千石。","擁節祠太山，寒天霜草白。"]', '["封疆七百里，祿秩二千石。","擁節祠太山，寒天霜草白。"]', '诗', 'shi', '', NULL, '陪孟都督祭嶽途中有贈 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1a3295b-4d6e-40f6-99c6-ea38df448c9b', '宿甑山', '宿甑山', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["山中今夜何人，闕下當年近臣。","青瑣應須早去，白雲何用相親。"]', '["山中今夜何人，闕下當年近臣。","青瑣應須早去，白云何用相親。"]', '诗', 'shi', '', NULL, '宿甑山 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1abbe7d9-55cc-4f8c-9f81-e2e402a10900', '別甑山', '別甑山', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["一身趨侍丹墀，西路翩翩去時。","惆悵青山綠水，何年更是來期。"]', '["一身趨侍丹墀，西路翩翩去时。","惆悵青山綠水，何年更是来期。"]', '诗', 'shi', '', NULL, '別甑山 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6688025a-ec4e-4857-997f-de52f7f13346', '送陳明府赴淮南', '送陳明府赴淮南', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["年華近逼清明，落日微風送行。","黃鳥綿蠻芳樹，紫騮躞蹀東城。","花間一杯促膝，煙外千里含情。","應渡淮南信宿，諸侯擁斾相迎。"]', '["年华近逼清明，落日微风送行。","黄鸟綿蠻芳樹，紫騮躞蹀东城。","花间一杯促膝，煙外千里含情。","應渡淮南信宿，諸侯擁斾相迎。"]', '诗', 'shi', '', NULL, '送陳明府赴淮南 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e169bdee-e544-4a38-b659-f3acb51b9df6', '送客知鄂州', '送客知鄂州', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["江口千家帶楚雲，江花亂點雪紛紛。","春風落日誰相見，青翰舟中有鄂君。"]', '["江口千家带楚云，江花亂点雪紛紛。","春风落日誰相见，青翰舟中有鄂君。"]', '诗', 'shi', '', NULL, '送客知鄂州 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77ac62ee-6396-4ac0-a3ab-cb84ba2e5cd0', '寒食', '寒食', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["春城無處不飛花，寒食東風御柳斜。","日暮漢宮傳蠟燭，輕煙散入五侯家。"]', '["春城無处不飞花，寒食东风御柳斜。","日暮漢宮傳蠟燭，轻煙散入五侯家。"]', '诗', 'shi', '', NULL, '寒食 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41a1a003-673c-461e-800c-5520dcad7400', '羽林騎', '羽林騎', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["駿馬牽來御柳中，鳴鞭欲向渭橋東。","紅蹄亂蹋春城雪，花頷驕嘶上苑風。"]', '["駿马牽来御柳中，鳴鞭欲向渭橋东。","紅蹄亂蹋春城雪，花頷驕嘶上苑风。"]', '诗', 'shi', '', NULL, '羽林騎 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('976e4304-0924-4e80-9c5c-60c6646a9705', '看調馬', '看調马', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["鴛鴦赭白齒新齊，晚日花中散碧蹄。","玉勒斗回初噴沫，金鞭欲下不成嘶。"]', '["鴛鴦赭白齒新齊，晚日花中散碧蹄。","玉勒斗回初噴沫，金鞭欲下不成嘶。"]', '诗', 'shi', '', NULL, '看調馬 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('394d5a0d-3970-4d74-a541-2d7f2aaa4f60', '寄贈衡州楊使君', '寄贈衡州楊使君', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["湘竹斑斑湘水春，衡陽太守虎符新。","朝來笑向歸鴻道，早晚南飛見主人。"]', '["湘竹斑斑湘水春，衡陽太守虎符新。","朝来笑向归鴻道，早晚南飞见主人。"]', '诗', 'shi', '', NULL, '寄贈衡州楊使君 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('575b9318-2d52-480d-8b79-4203109700fb', '宿石邑山中', '宿石邑山中', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["浮雲不共此山齊，山靄蒼蒼望轉迷。","曉月暫飛高樹裏，秋河隔在數峰西。"]', '["浮云不共此山齊，山靄蒼蒼望轉迷。","晓月暫飞高樹裏，秋河隔在數峰西。"]', '诗', 'shi', '', NULL, '宿石邑山中 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('084a7bf6-dfe9-4f11-99b2-55ce23b21fa9', '江南曲', '江南曲', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["長樂花枝雨點銷，江城日暮好相邀。","春樓不閉葳蕤鎖，綠水回通宛轉橋。"]', '["长乐花枝雨点銷，江城日暮好相邀。","春楼不閉葳蕤鎖，綠水回通宛轉橋。"]', '诗', 'shi', '', NULL, '江南曲 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d63caf47-6edc-46d4-b5b8-cacede26dc50', '贈張千牛', '贈張千牛', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["蓬萊闕下是天家，上路新回白鼻騧。","急管晝催平樂酒，春衣夜宿杜陵花。"]', '["蓬萊闕下是天家，上路新回白鼻騧。","急管晝催平乐酒，春衣夜宿杜陵花。"]', '诗', 'shi', '', NULL, '贈張千牛 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fc6b384-e4bf-4bc9-8d65-33804cc1ae82', '漢宮曲二首 一', '漢宮曲二首 一', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["五柞宮中過臘看，萬年枝上雪花殘。","綺窗夜閉玉堂靜，素綆朝穿金井寒。"]', '["五柞宮中過臘看，万年枝上雪花殘。","綺窗夜閉玉堂静，素綆朝穿金井寒。"]', '诗', 'shi', '', NULL, '漢宮曲二首 一 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('041dffad-e61e-47eb-9aae-31b5150784a0', '漢宮曲二首 二', '漢宮曲二首 二', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["家在長陵小市中，珠簾繡戶對春風。","君王昨日移仙仗，玉輦迎將入漢宮。"]', '["家在长陵小市中，珠簾繡戶对春风。","君王昨日移仙仗，玉輦迎將入漢宮。"]', '诗', 'shi', '', NULL, '漢宮曲二首 二 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac7e882c-576b-479f-bc7b-88aa5b00fed6', '贈李翼', '贈李翼', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["王孫別舍擁朱輪，不羨空名樂此身。","門外碧潭春洗馬，樓前紅燭夜迎人。"]', '["王孫別舍擁朱輪，不羨空名乐此身。","门外碧潭春洗马，楼前紅燭夜迎人。"]', '诗', 'shi', '', NULL, '贈李翼 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3e790d3-91fa-4575-89d1-0cdd3701bb5c', '少年行', '少年行', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["千點斕斒玉勒驄，青絲結尾繡纏騣。","鳴鞭曉出章臺路，葉葉春衣楊柳風。"]', '["千点斕斒玉勒驄，青絲結尾繡纏騣。","鳴鞭晓出章台路，葉葉春衣楊柳风。"]', '诗', 'shi', '', NULL, '少年行 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85c8567d-7db9-4c84-8352-86f530b1de88', '題玉真觀李祕書院', '題玉真观李祕书院', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["白雲斜日影深松，玉宇瑤壇知幾重。","把酒題詩人散後，華陽洞裏有疎鐘。"]', '["白云斜日影深松，玉宇瑤壇知幾重。","把酒題诗人散後，华陽洞裏有疎鐘。"]', '诗', 'shi', '', NULL, '題玉真觀李祕書院 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9220d0e0-b30f-4186-8d35-945cdd49c036', '送客之潞府', '送客之潞府', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["官柳青青匹馬嘶，迴風暮雨入銅鞮。","佳期別在春山裏，應是人蓡五葉齊。"]', '["官柳青青匹马嘶，迴风暮雨入銅鞮。","佳期別在春山裏，應是人蓡五葉齊。"]', '诗', 'shi', '', NULL, '送客之潞府 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc554577-3009-4589-9e39-f06493a654a3', '送客貶五溪', '送客貶五溪', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["南過猨聲一逐臣，回看秋草淚霑巾。","寒天暮雪空山裏，幾處蠻家是主人。"]', '["南過猨声一逐臣，回看秋草泪霑巾。","寒天暮雪空山裏，幾处蠻家是主人。"]', '诗', 'shi', '', NULL, '送客貶五溪 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5cc1b29-4977-48c0-92eb-a08063abf06b', '送齊山人歸長白山', '送齊山人归长白山', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["舊事仙人白兔公，掉頭歸去又乘風。","柴門流水依然在，一路寒山萬木中。"]', '["旧事仙人白兔公，掉头归去又乘风。","柴门流水依然在，一路寒山万木中。"]', '诗', 'shi', '', NULL, '送齊山人歸長白山 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdc1bcb7-09a3-47fe-a04f-05a8543a0086', '寄裴鄆州', '寄裴鄆州', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["烏紗靈壽對秋風，悵望浮雲濟水東。","官樹陰陰鈴閣暮，州人轉憶白頭翁。"]', '["烏紗靈壽对秋风，悵望浮云濟水东。","官樹陰陰鈴閣暮，州人轉憶白头翁。"]', '诗', 'shi', '', NULL, '寄裴鄆州 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27622d64-c196-4bbf-9cbd-89ca4d3cf99e', '梁城贈一二同幕', '梁城贈一二同幕', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["五營河畔列旌旗，吹角鳴鼙日暮時。","曾是信陵門下客，兩迴相弔不勝悲。"]', '["五營河畔列旌旗，吹角鳴鼙日暮时。","曾是信陵门下客，兩迴相弔不勝悲。"]', '诗', 'shi', '', NULL, '梁城贈一二同幕 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dd25e7d-c935-4eb6-993e-144a95798d50', '河上寄故人', '河上寄故人', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["河流曉天，濮水清煙。","日暖昆吾臺上，春深顓頊城邊。","鶯聲亂啁鵠囗，花片細點龍泉。","西望情人早至，猶應得醉芳年。"]', '["河流晓天，濮水清煙。","日暖昆吾台上，春深顓頊城邊。","鶯声亂啁鵠囗，花片細点龙泉。","西望情人早至，猶應得醉芳年。"]', '诗', 'shi', '', NULL, '河上寄故人 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b26105a2-d9e4-4f3a-a0d4-1adb67facb0f', '留題寧川香蓋寺壁', '留題寧川香蓋寺壁', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["愛遠登高塵眼開。","爲憐蕭寺上經臺，山川誰識龍蛇蟄。","天地自迎風雨來，柳放寒條秋已老。","雁搖孤翼暮空迴，何人會得其中事。","又被殘花落日催。"]', '["愛远登高塵眼开。","爲怜蕭寺上經台，山川誰識龙蛇蟄。","天地自迎风雨来，柳放寒條秋已老。","雁搖孤翼暮空迴，何人會得其中事。","又被殘花落日催。"]', '诗', 'shi', '', NULL, '留題寧川香蓋寺壁 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25a3e97e-464e-4d18-a912-1c1cf82b175d', '寄柳氏', '寄柳氏', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["章臺柳，章臺柳，顏色青青今在否？縱使長條似舊垂，也應攀折他人手。"]', '["章台柳，章台柳，顏色青青今在否？縱使长條似旧垂，也應攀折他人手。"]', '诗', 'shi', '', NULL, '寄柳氏 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('effc7dbe-9c0c-4dcf-aaab-d9a64a308bac', '海上寄蕭立', '海上寄蕭立', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["朔風剪塞草，寒露日夜結。","行行到瀛壖，歸思生暮節。","驛樓見萬里，延首望遼碣。","遠海入大荒，平蕪際窮髮。","舊國在夢想，故人胡且越。","契闊阻風期，荏苒成雨別。","海西望京口，兩地各天末。","索居動經秋，再笑知曷月。","日南望中盡，唯見飛鳥滅。","音塵未易得，何由慰飢渴。"]', '["朔风剪塞草，寒露日夜結。","行行到瀛壖，归思生暮節。","驛楼见万里，延首望遼碣。","远海入大荒，平蕪際窮髮。","旧国在梦想，故人胡且越。","契闊阻风期，荏苒成雨別。","海西望京口，兩地各天末。","索居动經秋，再笑知曷月。","日南望中尽，唯见飞鸟滅。","音塵未易得，何由慰飢渴。"]', '诗', 'shi', '', NULL, '海上寄蕭立 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24ef8bab-1d3b-468f-97f5-d6518a5429cc', '三月三日自京到華陰於水亭獨酌寄裴六薛八', '三月三日自京到华陰於水亭独酌寄裴六薛八', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["祗役匪遑息，經時客三秦。","還家問節候，知到上巳辰。","山縣何所有，高城閉青春。","和風不吾欺，桃杏滿四鄰。","舊友適遠別，誰當接歡欣。","呼兒命長瓢，獨酌湘吳醇。","一酌一朗詠，既酣意亦申。","言筌暫兩忘，霞月祗相新。","裴子塵表物，薛侯席上珍。","寄書二傲吏，何日同車茵。","詎肯使空名，終然羈此身。","他年解桎梏，長作海上人。"]', '["祗役匪遑息，經时客三秦。","還家问節候，知到上巳辰。","山縣何所有，高城閉青春。","和风不吾欺，桃杏满四鄰。","旧友適远別，誰當接歡欣。","呼兒命长瓢，独酌湘吳醇。","一酌一朗詠，既酣意亦申。","言筌暫兩忘，霞月祗相新。","裴子塵表物，薛侯席上珍。","寄书二傲吏，何日同车茵。","詎肯使空名，終然羈此身。","他年解桎梏，长作海上人。"]', '诗', 'shi', '', NULL, '三月三日自京到華陰於水亭獨酌寄裴六薛八 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60eb6632-93f6-4d37-b50f-b4e9d7acc503', '代書寄上裴六冀劉二潁', '代书寄上裴六冀劉二潁', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["昔余馬首東，君在海北汭。","盡屏簿領書，相與議巖穴。","載來詣佳境，每山有車轍。","長嘯林木動，高歌唾壺缺。","此辭月未周，虜馬嘶絳闕。","猛虎踞大道，九州當中裂。","聞君棄孤城，猶自握漢節。","恥栖惡木影，忍與故山別。","脫舄挂嶺雲，冏然若鳥逝。","唯留潺湲水，分付練溪月。","爾來大谷梨，白花再成雪。","關梁限天險，歡樂竟兩絕。","大盜近削平，三川今底寧。","句芒布春令，屏翳收雷霆。","伊洛日夜漲，鳴臯蘭杜青。","騫騫兩黃鵠，何處遊青冥。","疇昔切玉刃，應如新發硎。","及時當樹勳，高懸景鐘銘。","莫抱白雲意，徑往丹丘庭。","功成儻長揖，然後謀滄溟。"]', '["昔余马首东，君在海北汭。","尽屏簿領书，相與議巖穴。","載来詣佳境，每山有车轍。","长嘯林木动，高歌唾壺缺。","此辞月未周，虜马嘶絳闕。","猛虎踞大道，九州當中裂。","闻君棄孤城，猶自握漢節。","恥栖惡木影，忍與故山別。","脫舄挂嶺云，冏然若鸟逝。","唯留潺湲水，分付練溪月。","爾来大谷梨，白花再成雪。","关梁限天險，歡乐竟兩絕。","大盜近削平，三川今底寧。","句芒布春令，屏翳收雷霆。","伊洛日夜漲，鳴臯蘭杜青。","騫騫兩黄鵠，何处游青冥。","疇昔切玉刃，應如新發硎。","及时當樹勳，高懸景鐘銘。","莫抱白云意，徑往丹丘庭。","功成儻长揖，然後謀滄溟。"]', '诗', 'shi', '', NULL, '代書寄上裴六冀劉二潁 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('997a7b34-550b-4f06-b160-ceedf658540e', '客舍月下對酒醉後寄畢四燿', '客舍月下对酒醉後寄畢四燿', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["鄉路風雪深，生事憂患迫。","天長波瀾廣，高舉無六翮。","獨立寒夜移，幽境思彌積。","霜月照膽淨，銀河入簷白。","沽酒聊自勞，開樽坐簷隙。","主人奏絲桐，能使高興劇。","清機暫無累，獻酢更絡繹。","慷慨葛天歌，愔愔廣陵陌。","既醉萬事遺，耳熱心亦適。","視身兀如泥，瞪目傲今昔。","故人間城闕，音信兩脉脉。","別時前盟在，寸景莫自擲。","心與白日鬬，十無一滿百。","寓形薪火內，甘作天地客。","與物無親疎，斗酒勝竹帛。","何必用自苦，將貽古賢責。"]', '["乡路风雪深，生事憂患迫。","天长波瀾廣，高舉無六翮。","独立寒夜移，幽境思彌積。","霜月照膽淨，銀河入簷白。","沽酒聊自勞，开樽坐簷隙。","主人奏絲桐，能使高兴劇。","清機暫無累，獻酢更絡繹。","慷慨葛天歌，愔愔廣陵陌。","既醉万事遺，耳熱心亦適。","視身兀如泥，瞪目傲今昔。","故人间城闕，音信兩脉脉。","別时前盟在，寸景莫自擲。","心與白日鬬，十無一满百。","寓形薪火內，甘作天地客。","與物無親疎，斗酒勝竹帛。","何必用自苦，將貽古賢責。"]', '诗', 'shi', '', NULL, '客舍月下對酒醉後寄畢四燿 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f278530-500b-4239-9fd7-cd476af8b08e', '下弋陽江舟中代書寄裴侍御', '下弋陽江舟中代书寄裴侍御', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["故鄉隔西日，水去連長天。","前路知幾許，但指天南邊。","愴恨極浦外，隱映青山連。","東風滿帆來，五兩如弓弦。","遙羨繡衣客，冏然馬首先。","得餐武昌魚，不顧潯陽田。","屈指數別日，忽乎成兩年。","百花已滿眼，春草漸碧鮮。","豈是離居時，奈何于役牽。","洞庭有深涉，曷日期歸旋。","且作異鄉料，詎知攜手緣。","離憂未易銷，莫道樽酒賢。"]', '["故乡隔西日，水去連长天。","前路知幾許，但指天南邊。","愴恨極浦外，隐映青山連。","东风满帆来，五兩如弓弦。","遙羨繡衣客，冏然马首先。","得餐武昌鱼，不顧潯陽田。","屈指數別日，忽乎成兩年。","百花已满眼，春草漸碧鲜。","豈是離居时，奈何于役牽。","洞庭有深涉，曷日期归旋。","且作異乡料，詎知携手緣。","離憂未易銷，莫道樽酒賢。"]', '诗', 'shi', '', NULL, '下弋陽江舟中代書寄裴侍御 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('832f06ec-eb60-4f11-8564-bb3a7e8629a8', '癸卯歲赴南豐道中聞京師失守寄權士繇韓幼深', '癸卯歲赴南豐道中闻京師失守寄權士繇韓幼深', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["種田不遇歲，策名不遭時。","胡塵晦落日，西望泣路岐。","猛虎嘯北風，麕麚皆載馳。","深泥駕疲牛，踸踔余何之。","詰屈白道轉，繚繞清溪隨。","荒谷嘯山鬼，深林啼子規。","長歎指故山，三奏歸來詞。","不逢眼中人，調苦車逶遲。","士繇松筠操，幼深瓊樹姿。","別來平安否，何階一申眉。","白雲失帝鄉，遠水恨天涯。","昂藏雙威鳳，曷月還西枝。","努力愛華髮，盛年振羽儀。","但令迍難康，不負滄洲期。","莫作新亭泣，徒使夷吾嗤。"]', '["種田不遇歲，策名不遭时。","胡塵晦落日，西望泣路岐。","猛虎嘯北风，麕麚皆載驰。","深泥駕疲牛，踸踔余何之。","詰屈白道轉，繚繞清溪隨。","荒谷嘯山鬼，深林啼子規。","长歎指故山，三奏归来词。","不逢眼中人，調苦车逶遲。","士繇松筠操，幼深瓊樹姿。","別来平安否，何階一申眉。","白云失帝乡，远水恨天涯。","昂藏雙威鳳，曷月還西枝。","努力愛华髮，盛年振羽儀。","但令迍难康，不負滄洲期。","莫作新亭泣，徒使夷吾嗤。"]', '诗', 'shi', '', NULL, '癸卯歲赴南豐道中聞京師失守寄權士繇韓幼深 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25721b8d-4d53-4494-9e32-f4ce981c4dfb', '賈員外處見中書賈舍人巴陵詩集覧之懷舊代書寄贈', '賈員外处见中书賈舍人巴陵诗集覧之懷旧代书寄贈', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["海岸望青瑣，雲長天漫漫。","十年不一展，知有關山難。","適逢阮始平，立馬問長安。","取公詠懷詩，示我江海瀾。","暫若窺武庫，森然矛戟寒。","眼明遺頭風，心悅忘朝餐。","大駕今返正，熊羆扈鳴鑾。","公遊鳳凰沼，獻可在筆端。","繫越有長纓，封關祗一丸。","冏然翔寥廓，仰望慚羽翰。","嘉會不我與，相思歲雲殫。","唯當袖佳句，持比青琅玕。"]', '["海岸望青瑣，云长天漫漫。","十年不一展，知有关山难。","適逢阮始平，立马问长安。","取公詠懷诗，示我江海瀾。","暫若窺武庫，森然矛戟寒。","眼明遺头风，心悅忘朝餐。","大駕今返正，熊羆扈鳴鑾。","公游鳳凰沼，獻可在笔端。","繫越有长纓，封关祗一丸。","冏然翔寥廓，仰望慚羽翰。","嘉會不我與，相思歲云殫。","唯當袖佳句，持比青琅玕。"]', '诗', 'shi', '', NULL, '賈員外處見中書賈舍人巴陵詩集覧之懷舊代書寄贈 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59ef1225-521f-4e5d-8015-b5f2f306640c', '代書寄上李廣州', '代书寄上李廣州', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["皖水望番禺，迢迢青天末。","鴻鴈飛不到，音塵何由達。","獨有輿人歌，隔雲聲諠聒。","皆稱府君仁，百越賴全活。","推誠魚鱉信，持正魑魅怛。","疲民保中和，性足無夭閼。","天子咨四岳，佇公濟方割。","幾時復旋歸，入踐青瑣闥。","賤子託明德，繚若松上葛。","別離鄙恡生，結念思所豁。","門欄關山阻，岐路天地闊。","唯憑萬里書，持用慰飢渴。"]', '["皖水望番禺，迢迢青天末。","鴻鴈飞不到，音塵何由達。","独有輿人歌，隔云声諠聒。","皆稱府君仁，百越賴全活。","推誠鱼鱉信，持正魑魅怛。","疲民保中和，性足無夭閼。","天子咨四岳，佇公濟方割。","幾时复旋归，入踐青瑣闥。","賤子託明德，繚若松上葛。","別離鄙恡生，結念思所豁。","门欄关山阻，岐路天地闊。","唯憑万里书，持用慰飢渴。"]', '诗', 'shi', '', NULL, '代書寄上李廣州 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63eb44fd-c33b-462a-a22d-1dff34b55115', '夏中詶于逖畢燿問病見贈', '夏中詶于逖畢燿问病见贈', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["救物智所昧，學仙願未從。","行藏兩乖角，蹭蹬風波中。","薄宦耻降志，臥痾非養蒙。","閉關涉兩旬，羇思浩無窮。","鸑鷟何處來，雙舞下碧空。","離別隔雲雨，惠然此相逢。","把手賀疾間，舉杯欣酒濃。","新詩見久要，清論激深衷。","高館舒夜簟，開門延微風。","火雲赫嵯峨，日暮千萬峯。","遙指故山笑，相看撫號鐘。","聲和由心清，事感知氣同。","出處未易料，且歌緩愁容。","願君崇明德，歲暮如青松。"]', '["救物智所昧，学仙願未從。","行藏兩乖角，蹭蹬风波中。","薄宦耻降志，臥痾非養蒙。","閉关涉兩旬，羇思浩無窮。","鸑鷟何处来，雙舞下碧空。","離別隔云雨，惠然此相逢。","把手賀疾间，舉杯欣酒濃。","新诗见久要，清論激深衷。","高館舒夜簟，开门延微风。","火云赫嵯峨，日暮千万峯。","遙指故山笑，相看撫號鐘。","声和由心清，事感知氣同。","出处未易料，且歌緩愁容。","願君崇明德，歲暮如青松。"]', '诗', 'shi', '', NULL, '夏中詶于逖畢燿問病見贈 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7416f975-2ef2-4b64-81fa-41e24a9dc04e', '詶梁二十宋中所贈兼留別梁少府', '詶梁二十宋中所贈兼留別梁少府', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["少讀黃帝書，肯不笑機事。","意猶負深衷，未免名跡累。","厭貧學干祿，欲徇賓王利。","甘爲風波人，豈復江海意。","擔簦平臺下，是日飲羇思。","逢君道寸心，暫喜一交臂。","緒言未及竟，離念已復至。","甯[陵]望南丘，雲雨成兩地。","途殊跡方間，河廣流且駛。","暮帆望不及，覽贈心欲醉。","愛君如金錫，昆弟皆茂異。","奕赫連絲衣，榮養能錫類。","君子道未長，深藏青雲器。","巨鱗有縱時，今日不足議。","唯當加餐飯，好我袖中字。","別離動經年，莫道分首易。"]', '["少读黄帝书，肯不笑機事。","意猶負深衷，未免名跡累。","厭貧学干祿，欲徇賓王利。","甘爲风波人，豈复江海意。","擔簦平台下，是日饮羇思。","逢君道寸心，暫喜一交臂。","緒言未及竟，離念已复至。","甯[陵]望南丘，云雨成兩地。","途殊跡方间，河廣流且駛。","暮帆望不及，覽贈心欲醉。","愛君如金錫，昆弟皆茂異。","奕赫連絲衣，榮養能錫類。","君子道未长，深藏青云器。","巨鱗有縱时，今日不足議。","唯當加餐飯，好我袖中字。","別離动經年，莫道分首易。"]', '诗', 'shi', '', NULL, '詶梁二十宋中所贈兼留別梁少府 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8082376a-6f93-46f4-9e4e-ea1e6a600c93', '庚子歲避地至玉山詶韓司馬所贈', '庚子歲避地至玉山詶韓司马所贈', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["滄海疾風起，洪波駭恬鱗。","已無濟川分，甘作乘桴人。","揮手謝秣陵，舉帆指甌閩。","安和風塵表，偶與瓊瑤親。","共悲行路難，況逢江南春。","故園忽如夢，返復知何辰。","曠野豺虎滿，深山蘭蕙新。","枉君灞陵什，廻首徒酸辛。"]', '["滄海疾风起，洪波駭恬鱗。","已無濟川分，甘作乘桴人。","揮手謝秣陵，舉帆指甌閩。","安和风塵表，偶與瓊瑤親。","共悲行路难，況逢江南春。","故园忽如梦，返复知何辰。","曠野豺虎满，深山蘭蕙新。","枉君灞陵什，廻首徒酸辛。"]', '诗', 'shi', '', NULL, '庚子歲避地至玉山詶韓司馬所贈 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0faec6a8-f7d3-44bf-b69b-db48b9e74f11', '奉和李大夫同呂評事太行苦熱行兼寄院中諸公', '奉和李大夫同呂評事太行苦熱行兼寄院中諸公', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["駟馬上太行，修途亙遼碣。","王程無留駕，日昃未遑歇。","請問此何時，恢台朱明月。","長蛇稽天討，上將方北伐。","明主命使臣，皇華得時傑。","已忘羊腸險，豈憚濕風熱。","搖策汗滂滄，登岸思紆結。","炎雲如煙火，谿谷將恐竭。","晝景赩可畏，涼飆何由發。","山長飛鳥墮，目極行車絕。","趙魏方俶擾，安危俟明哲。","歸路豈不懷，飲冰有苦節。","會同傳檄至，疑議立談決。","況有阮元瑜，翩翩秉書札。","起予歌赤坂，永好踰白雪。","誰念剖竹人，無因執羈紲。"]', '["駟马上太行，修途亙遼碣。","王程無留駕，日昃未遑歇。","請问此何时，恢台朱明月。","长蛇稽天討，上將方北伐。","明主命使臣，皇华得时傑。","已忘羊腸險，豈憚濕风熱。","搖策汗滂滄，登岸思紆結。","炎云如煙火，谿谷將恐竭。","晝景赩可畏，涼飆何由發。","山长飞鸟墮，目極行车絕。","趙魏方俶擾，安危俟明哲。","归路豈不懷，饮冰有苦節。","會同傳檄至，疑議立談決。","況有阮元瑜，翩翩秉书札。","起予歌赤坂，永好踰白雪。","誰念剖竹人，無因執羈紲。"]', '诗', 'shi', '', NULL, '奉和李大夫同呂評事太行苦熱行兼寄院中諸公 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30a03a87-348d-477a-9f49-962ce991f8a8', '詶皇甫侍御望天灊山見示之作', '詶皇甫侍御望天灊山见示之作', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["早歲慕五嶽，嘗爲塵機礙。","孰知天柱峯，今與郡齋對。","隱嶙抱元氣，氤氳含青靄。","雲崖媚遠空，石壁寒古塞。","漢皇南遊日，望秩此昭配。","法駕到谷口，禮容振荒外。","焚柴百神趨，執玉萬方會。","天旋物順動，德布澤霶霈。","講武威已耀，學仙功未艾。","黃金竟何成，洪業遽淪昧。","度世若一瞬，昨朝已千載。","如今封禪壇，唯見雲雨晦。","長望哀往古，勞生慚大塊。","清暉幸相娛，幽獨知所賴。","寒城春方正，初日明可愛。","萬殊喜陽和，余亦荷時泰。","山色日夜綠，下有清淺瀨。","愧作拳僂人，沈迷簿書內。","登臨歎拘限，出處悲老大。","況聽郢中曲，復識湘南態。","思免物累牽，敢令道機退。","瞞然誦佳句，持此秋蘭佩。"]', '["早歲慕五嶽，嘗爲塵機礙。","孰知天柱峯，今與郡斋对。","隐嶙抱元氣，氤氳含青靄。","云崖媚远空，石壁寒古塞。","漢皇南游日，望秩此昭配。","法駕到谷口，禮容振荒外。","焚柴百神趨，執玉万方會。","天旋物順动，德布澤霶霈。","講武威已耀，学仙功未艾。","黄金竟何成，洪業遽淪昧。","度世若一瞬，昨朝已千載。","如今封禪壇，唯见云雨晦。","长望哀往古，勞生慚大塊。","清暉幸相娛，幽独知所賴。","寒城春方正，初日明可愛。","万殊喜陽和，余亦荷时泰。","山色日夜綠，下有清淺瀨。","愧作拳僂人，沈迷簿书內。","登臨歎拘限，出处悲老大。","況听郢中曲，复識湘南態。","思免物累牽，敢令道機退。","瞞然誦佳句，持此秋蘭佩。"]', '诗', 'shi', '', NULL, '詶皇甫侍御望天灊山見示之作 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d2e9ee1-99e7-4116-93c3-f3cf68e44527', '送陳兼應辟兼寄高適賈至', '送陳兼應辟兼寄高適賈至', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["結綠處燕石，卞和不必知。","所以王佐才，未能忘茅茨。","罷官梁山外，穫稻楚水湄。","適會傅巖人，虛舟濟川時。","天網忽搖頓，公才難棄遺。","鳳凰翔千仞，今始一鳴岐。","上馬指國門，舉鞭射書帷。","預知大人賦，掩却歸來詞。","天子方在宥，朝廷張四維。","料君能獻可，努力副疇咨。","舊友滿皇州，高冠飛翠蕤。","相逢絳闕下，應道軒車遲。","高侯秉戎翰，策馬觀西夷。","方從幕中事，參謀王者師。","賈生去洛陽，焜耀琳瑯姿。","芳名動北步，逸韻陵南皮。","肅肅舉鴻毛，冷然順風吹。","波流有同異，由是限別離。","漢塞隔隴底，秦川連鎬池。","白雲日夜滿，道里安可思。","夢想浩盈積，物華愁變衰。","因君附錯刀，送遠益淒其。","四海各橫絕，九霄應易期。","不知故巢燕，決起棲何枝。"]', '["結綠处燕石，卞和不必知。","所以王佐才，未能忘茅茨。","罷官梁山外，穫稻楚水湄。","適會傅巖人，虛舟濟川时。","天網忽搖頓，公才难棄遺。","鳳凰翔千仞，今始一鳴岐。","上马指国门，舉鞭射书帷。","預知大人賦，掩却归来词。","天子方在宥，朝廷張四維。","料君能獻可，努力副疇咨。","旧友满皇州，高冠飞翠蕤。","相逢絳闕下，應道軒车遲。","高侯秉戎翰，策马观西夷。","方從幕中事，參謀王者師。","賈生去洛陽，焜耀琳瑯姿。","芳名动北步，逸韻陵南皮。","肅肅舉鴻毛，冷然順风吹。","波流有同異，由是限別離。","漢塞隔隴底，秦川連鎬池。","白云日夜满，道里安可思。","梦想浩盈積，物华愁变衰。","因君附錯刀，送远益淒其。","四海各橫絕，九霄應易期。","不知故巢燕，決起棲何枝。"]', '诗', 'shi', '', NULL, '送陳兼應辟兼寄高適賈至 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d130680-3936-409c-a214-f9e0257a27eb', '送相里郎中赴江西', '送相里郎中赴江西', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["君把一尺詔，南遊濟滄浪。","受恩忘險艱，不道歧路長。","戎狄方搆患，休牛殊未遑。","三秦千倉空，戰卒如餓狼。","委輸資外府，諏謀寄賢良。","有才當陳力，安得遂翱翔。","豈不慎井賦，賦均人亦康。","遙知軒車到，萬室安耕桑。","火伏金氣騰，昊天欲蒼茫。","寒蟬慘巴鄧，秋色愁沅湘。","昨日攜手西，於今芸再黃。","歡娛詎幾許，復向天一方。","蹢躅話世故，惆悵舉離觴。","共求數刻歡，戲謔君此堂。","今日把手笑，少時各他鄉。","身名同風波，聚散未易量。","曷月還朝天，及時開智囊。","前期儻猶闊，加飯勉自強。"]', '["君把一尺詔，南游濟滄浪。","受恩忘險艱，不道歧路长。","戎狄方搆患，休牛殊未遑。","三秦千倉空，戰卒如餓狼。","委輸資外府，諏謀寄賢良。","有才當陳力，安得遂翱翔。","豈不慎井賦，賦均人亦康。","遙知軒车到，万室安耕桑。","火伏金氣腾，昊天欲蒼茫。","寒蟬慘巴鄧，秋色愁沅湘。","昨日携手西，於今芸再黄。","歡娛詎幾許，复向天一方。","蹢躅話世故，惆悵舉離觴。","共求數刻歡，戲謔君此堂。","今日把手笑，少时各他乡。","身名同风波，聚散未易量。","曷月還朝天，及时开智囊。","前期儻猶闊，加飯勉自強。"]', '诗', 'shi', '', NULL, '送相里郎中赴江西 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42da4617-5aaf-4a12-8d01-d64fd9cecae5', '觀海', '观海', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["北登渤澥島，廻首秦東門。","誰尸造物功，鑿此天池源。","澒洞吞百谷，周流無四垠。","廓然混茫際，望見天地根。","白日自中吐，扶桑如可捫。","超遙蓬萊峰，想像金臺存。","秦帝昔經此，登臨冀飛翻。","揚旌百神會，望日羣山奔。","徐福竟何成，羨門徒空言。","唯見石橋足，千年潮水痕。"]', '["北登渤澥島，廻首秦东门。","誰尸造物功，鑿此天池源。","澒洞吞百谷，周流無四垠。","廓然混茫際，望见天地根。","白日自中吐，扶桑如可捫。","超遙蓬萊峰，想像金台存。","秦帝昔經此，登臨冀飞翻。","揚旌百神會，望日羣山奔。","徐福竟何成，羨门徒空言。","唯见石橋足，千年潮水痕。"]', '诗', 'shi', '', NULL, '觀海 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fa64671-b74f-44f4-b685-99878869f07f', '初晴抱琴登馬退山對酒望遠醉後作', '初晴抱琴登马退山对酒望远醉後作', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["年長心易感，況爲憂患纏。","壯圖迫世故，行止兩茫然。","王旅方伐叛，虎臣皆被堅。","魯人著儒服，甘就南山田。","挈榼上高磴，超遙望平川。","滄江大如綖，隱映入遠天。","荒服何所有，山花雪中然。","寒泉得日景，吐霤鳴湔湔。","舉酒勸白雲，唱歌慰頹年。","微風度竹來，韻我號鍾弦。","一彈一引滿，耳熱知心宣。","曲終余亦酣，起舞山水前。","人生幾何時，太半百憂煎。","今日羇愁破，始知濁酒賢。"]', '["年长心易感，況爲憂患纏。","壯圖迫世故，行止兩茫然。","王旅方伐叛，虎臣皆被堅。","魯人著儒服，甘就南山田。","挈榼上高磴，超遙望平川。","滄江大如綖，隐映入远天。","荒服何所有，山花雪中然。","寒泉得日景，吐霤鳴湔湔。","舉酒勸白云，唱歌慰頹年。","微风度竹来，韻我號鍾弦。","一彈一引满，耳熱知心宣。","曲終余亦酣，起舞山水前。","人生幾何时，太半百憂煎。","今日羇愁破，始知濁酒賢。"]', '诗', 'shi', '', NULL, '初晴抱琴登馬退山對酒望遠醉後作 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df79e604-7c77-456d-97dc-9292f55c67c4', '同徐侍郎五雲溪新庭重陽宴集作', '同徐侍郎五云溪新庭重陽宴集作', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["萬峰蒼翠色，雙溪清淺流。","已符東山趣，況值江南秋。","白露天地肅，黃花門館幽。","山公惜美景，肯爲芳樽留。","五馬照池塘，繁弦催獻酬。","臨風孟嘉帽，乘興李膺舟。","騁望傲千古，當歌遺四愁。","豈令永和人，獨擅山陰遊。"]', '["万峰蒼翠色，雙溪清淺流。","已符东山趣，況值江南秋。","白露天地肅，黄花门館幽。","山公惜美景，肯爲芳樽留。","五马照池塘，繁弦催獻酬。","臨风孟嘉帽，乘兴李膺舟。","騁望傲千古，當歌遺四愁。","豈令永和人，独擅山陰游。"]', '诗', 'shi', '', NULL, '同徐侍郎五雲溪新庭重陽宴集作 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccbc2bb1-3369-4f62-85b7-b90af85e03ea', '雨晴後陪王員外泛後湖得溪字', '雨晴後陪王員外泛後湖得溪字', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["遠山媚平楚，宿雨漲清溪。","沿泝任舟檝，歡言無町畦。","酒酣相視笑，心與白鷗齊。"]', '["远山媚平楚，宿雨漲清溪。","沿泝任舟檝，歡言無町畦。","酒酣相視笑，心與白鷗齊。"]', '诗', 'shi', '', NULL, '雨晴後陪王員外泛後湖得溪字 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc01e269-75e6-4f68-8ce1-ea2615ba9719', '題思禪寺上方', '題思禪寺上方', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["溪口聞法鼓，停橈登翠屏。","攀雲到金界，合掌開禪扃。","鬱律衆山抱，空濛花雨零。","老僧指香樓，云是不死庭。","眇眇于越路，茫茫春草青。","遠山噴百谷，繚繞馳東溟。","目極道何在，境照心亦冥。","騞然諸根空，破結如破瓶。","下視三界狹，但聞五濁腥。","山中有良藥，吾欲隳天形。"]', '["溪口闻法鼓，停橈登翠屏。","攀云到金界，合掌开禪扃。","鬱律衆山抱，空濛花雨零。","老僧指香楼，云是不死庭。","眇眇于越路，茫茫春草青。","远山噴百谷，繚繞驰东溟。","目極道何在，境照心亦冥。","騞然諸根空，破結如破瓶。","下視三界狹，但闻五濁腥。","山中有良藥，吾欲隳天形。"]', '诗', 'shi', '', NULL, '題思禪寺上方 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('556a1fa5-a3d2-48cb-bfb7-354c057e042f', '季冬自嵩山赴洛道中作', '季冬自嵩山赴洛道中作', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["皇運偶中變，長蛇食中土。","天蓋西北傾，衆星隕如雨。","胡塵動地起，千里聞戰鼓。","死人成爲阜，流血塗草莽。","策馬何紛紛，捐軀抗豺虎。","甘心赴國難，誰謂荼葉苦。","天子初受命，省方造區宇。","斬鯨安溟波，截鼇作天柱。","三微復正統，五玉歸文祖。","不圖漢官儀，今日忽再覩。","升高望京邑，佳氣連海浦。","寶鼎歊景雲，明堂舞干羽。","虎臣囗激昂，囗囗囗禦侮。","腐儒著縫掖，何處議鄒魯。","西上轘轅山，丘陵橫今古。","和氣蒸萬物，臘月春靄吐。","得爲太平人，窮達不足數。","他日遇封禪，著書繼三五。"]', '["皇運偶中变，长蛇食中土。","天蓋西北傾，衆星隕如雨。","胡塵动地起，千里闻戰鼓。","死人成爲阜，流血塗草莽。","策马何紛紛，捐軀抗豺虎。","甘心赴国难，誰謂荼葉苦。","天子初受命，省方造區宇。","斬鯨安溟波，截鼇作天柱。","三微复正統，五玉归文祖。","不圖漢官儀，今日忽再覩。","升高望京邑，佳氣連海浦。","寶鼎歊景云，明堂舞干羽。","虎臣囗激昂，囗囗囗禦侮。","腐儒著縫掖，何处議鄒魯。","西上轘轅山，丘陵橫今古。","和氣蒸万物，臘月春靄吐。","得爲太平人，窮達不足數。","他日遇封禪，著书繼三五。"]', '诗', 'shi', '', NULL, '季冬自嵩山赴洛道中作 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bef2cc78-10ff-4c56-8db2-7c496b1891b5', '早發若峴驛望廬山', '早發若峴驛望廬山', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["雨罷山翠鮮，泠泠東風好。","斷崖雲生處，是向峯頂道。","誰謂峯頂遠，跂予可瞻討。","忘緣祛天機，脫屐恨不早。","祗恐歲云暮，遂與空名老。","心往跡未幷，慚愧山上草。"]', '["雨罷山翠鲜，泠泠东风好。","斷崖云生处，是向峯頂道。","誰謂峯頂远，跂予可瞻討。","忘緣祛天機，脫屐恨不早。","祗恐歲云暮，遂與空名老。","心往跡未幷，慚愧山上草。"]', '诗', 'shi', '', NULL, '早發若峴驛望廬山 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cf815ef-1a26-4115-9b66-81baff361615', '寒夜溪行舟中作', '寒夜溪行舟中作', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["日沈諸山昏，寂歷羣動宿。","孤舟獨不繫，風水夜相逐。","雲歸恆星白，霜下天地肅。","月輪大如盤，金波入空谷。","魏闕萬里道，羇念千慮束。","倦飛思故巢，敢望桐與竹。","沈吟登樓賦，中夜起三復。","憂來無良方，歸候春酒熟。"]', '["日沈諸山昏，寂歷羣动宿。","孤舟独不繫，风水夜相逐。","云归恆星白，霜下天地肅。","月輪大如盤，金波入空谷。","魏闕万里道，羇念千慮束。","倦飞思故巢，敢望桐與竹。","沈吟登楼賦，中夜起三复。","憂来無良方，归候春酒熟。"]', '诗', 'shi', '', NULL, '寒夜溪行舟中作 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ceb6380-ba87-46cd-a32e-e257aea18af1', '壬辰歲過舊居', '壬辰歲過旧居', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["少年事遠遊，出入燕與秦。","離居歲周天，猶作勞歌人。","負劒渡潁水，歸馬自知津。","緣源到舊廬，攬涕尋荒榛。","鄰里喜相勞，壺觴展殷勤。","酒蘭擊筑語，及此離會因。","丈夫隨世波，豈料百年身。","今日負鄙願，多慙故山春。"]', '["少年事远游，出入燕與秦。","離居歲周天，猶作勞歌人。","負劒渡潁水，归马自知津。","緣源到旧廬，攬涕尋荒榛。","鄰里喜相勞，壺觴展殷勤。","酒蘭擊筑語，及此離會因。","丈夫隨世波，豈料百年身。","今日負鄙願，多慙故山春。"]', '诗', 'shi', '', NULL, '壬辰歲過舊居 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef546ff5-da19-4063-98ad-5a3cfae0849d', '丙戌歲正月出洛陽書懷', '丙戌歲正月出洛陽书懷', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["往歲衣褐見，受服金馬門。","擬將忠與貞，來酬主人恩。","天地暫雷雨，洪波生平原。","窮鱗遂蹭蹬，夙昔事罕存。","幸逢帝出震，授鉞清東藩。","白日忽再中，萬方咸駿奔。","王風從西來，春光滿乾坤。","蟄蟲競飛動，余亦辭籠樊。","遭遇思自強，寵辱安足言。","唯將四方志，廻首謝故園。"]', '["往歲衣褐见，受服金马门。","擬將忠與貞，来酬主人恩。","天地暫雷雨，洪波生平原。","窮鱗遂蹭蹬，夙昔事罕存。","幸逢帝出震，授鉞清东藩。","白日忽再中，万方咸駿奔。","王风從西来，春光满乾坤。","蟄蟲競飞动，余亦辞籠樊。","遭遇思自強，寵辱安足言。","唯將四方志，廻首謝故园。"]', '诗', 'shi', '', NULL, '丙戌歲正月出洛陽書懷 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57afc121-9250-46ba-9503-6d19b0b49ff1', '傷春懷歸', '傷春懷归', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["誰謂鄉可望，望在天地涯。","但有時命同，萬里共歲華。","昨夜南山雨，殷雷坼萌芽。","源桃不余欺，先發秦人家。","寂寂戶外掩，遲遲春日斜。","源桃默無言，秦人獨長嗟。","不惜中腸苦，但言會合賒。","思歸吾誰訴，笑向南枝花。"]', '["誰謂乡可望，望在天地涯。","但有时命同，万里共歲华。","昨夜南山雨，殷雷坼萌芽。","源桃不余欺，先發秦人家。","寂寂戶外掩，遲遲春日斜。","源桃默無言，秦人独长嗟。","不惜中腸苦，但言會合賒。","思归吾誰訴，笑向南枝花。"]', '诗', 'shi', '', NULL, '傷春懷歸 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56f2dfa5-3d19-4b8f-a6da-8323290985ba', '雜詩', '杂诗', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["百花結成子，春物捨我去。","流年惜不得，獨坐空閨暮。","心自有所待，甘爲物華悞。","未必千黃金，買得一人顧。"]', '["百花結成子，春物捨我去。","流年惜不得，独坐空閨暮。","心自有所待，甘爲物华悞。","未必千黄金，買得一人顧。"]', '诗', 'shi', '', NULL, '雜詩 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aa53beb-a128-45f2-9bec-c2a15a0843c7', '山中春思', '山中春思', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["獺祭川水大，人家春日長。","獨謠晝不暮，搔首慙年芳。","靡草知節換，含葩向新陽。","不嫌三徑深，爲我生池塘。","亭午井竈閑，雀聲響空倉。","花落沒屐齒，風動羣木香。","歸路雲水外，天涯杳茫茫。","獨卷萬里心，深入山鳥行。","芳景勿相迫，春愁未遽忘。"]', '["獺祭川水大，人家春日长。","独謠晝不暮，搔首慙年芳。","靡草知節換，含葩向新陽。","不嫌三徑深，爲我生池塘。","亭午井竈闲，雀声响空倉。","花落沒屐齒，风动羣木香。","归路云水外，天涯杳茫茫。","独卷万里心，深入山鸟行。","芳景勿相迫，春愁未遽忘。"]', '诗', 'shi', '', NULL, '山中春思 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12286fc2-c262-43e8-817d-020327e8c690', '雨後公超谷北原眺望寄高拾遺', '雨後公超谷北原眺望寄高拾遺', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["崖口雨足收，清光洗高天。","虹蜺斂殘靄，山水含碧鮮。","遠空霞破露月輪，薄雲片片成魚鱗。","五陵如薺渭如帶，目極千里關山春。","朝來爽氣未易說，畫取花峯贈遠人。"]', '["崖口雨足收，清光洗高天。","虹蜺斂殘靄，山水含碧鲜。","远空霞破露月輪，薄云片片成鱼鱗。","五陵如薺渭如带，目極千里关山春。","朝来爽氣未易说，畫取花峯贈远人。"]', '诗', 'shi', '', NULL, '雨後公超谷北原眺望寄高拾遺 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('740e4166-38a6-4fa4-8ecb-5ff6eacc6de7', '自東都還濠州奉詶王八諫議見贈', '自东都還濠州奉詶王八諫議见贈', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["關西仕時俱稚容，彪彪之鬢始相逢。","天地變化縣城改，獨有故人交態在。","不言會合跡未幷，猶以歲寒心相待。","洛陽居守寄酇侯，君著貂冠參運籌。","高閣連雲騎省夜，新文會友涼風秋。","青袍白面昔攜手，冉冉府趨君記否。","雲分雨散十五年，始得一笑樽酒前。","未遑少留驟遠別，況值旅鴈鳴秋天。","二華舊遊如夢想，他時再會何由緣。","賴君贈我郢中曲，別後相思被管弦。"]', '["关西仕时俱稚容，彪彪之鬢始相逢。","天地变化縣城改，独有故人交態在。","不言會合跡未幷，猶以歲寒心相待。","洛陽居守寄酇侯，君著貂冠參運籌。","高閣連云騎省夜，新文會友涼风秋。","青袍白面昔携手，冉冉府趨君記否。","云分雨散十五年，始得一笑樽酒前。","未遑少留驟远別，況值旅鴈鳴秋天。","二华旧游如梦想，他时再會何由緣。","賴君贈我郢中曲，別後相思被管弦。"]', '诗', 'shi', '', NULL, '自東都還濠州奉詶王八諫議見贈 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc326cee-2472-4d7d-8c4c-97a590a72ade', '官渡柳歌送李員外承恩往揚州覲省', '官渡柳歌送李員外承恩往揚州覲省', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["君不見官渡河兩岸，三月楊柳枝。","千條萬條色，一一勝綠絲。","花作鉛粉絮，葉成翠羽帳。","此時送遠人，悵望春水上。","遠客折楊柳，依依兩含情。","夾郎木蘭舟，送郎千里行。","郎把紫泥書，東征覲庭闈。","脫却貂襜褕，新著五綵衣。","雙鳳幷兩翅，將雛東南飛。","五兩得便風，幾日到揚州。","莫貪揚州好，客行剩淹留。","郎到官渡頭，春闌已應久。","殷勤道遠別，爲謝大堤柳。","攀條儻相憶，五里一回首。","明年柳枝黃，問郎還家否。"]', '["君不见官渡河兩岸，三月楊柳枝。","千條万條色，一一勝綠絲。","花作鉛粉絮，葉成翠羽帳。","此时送远人，悵望春水上。","远客折楊柳，依依兩含情。","夾郎木蘭舟，送郎千里行。","郎把紫泥书，东征覲庭闈。","脫却貂襜褕，新著五綵衣。","雙鳳幷兩翅，將雛东南飞。","五兩得便风，幾日到揚州。","莫貪揚州好，客行剩淹留。","郎到官渡头，春闌已應久。","殷勤道远別，爲謝大堤柳。","攀條儻相憶，五里一回首。","明年柳枝黄，问郎還家否。"]', '诗', 'shi', '', NULL, '官渡柳歌送李員外承恩往揚州覲省 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68a65221-277b-4996-8d68-fed7604c1b8c', '東平蓬萊驛夜宴平盧楊判官醉後贈別姚太守置酒留宴', '东平蓬萊驛夜宴平盧楊判官醉後贈別姚太守置酒留宴', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["驛樓漲海壖，秋月寒城邊。","相見自不足，況逢主人賢。","夜清酒濃人如玉，一斗何啻直十千。","木蘭爲樽金爲杯，江南急管盧女弦。","齊童如花解郢曲，起舞激楚歌採蓮。","固知別多相逢少，樂極哀至心嬋娟。","少留莫辭醉，前路方悠然。","明日分飛儻相憶，祗應遙望西南天。"]', '["驛楼漲海壖，秋月寒城邊。","相见自不足，況逢主人賢。","夜清酒濃人如玉，一斗何啻直十千。","木蘭爲樽金爲杯，江南急管盧女弦。","齊童如花解郢曲，起舞激楚歌採蓮。","固知別多相逢少，乐極哀至心嬋娟。","少留莫辞醉，前路方悠然。","明日分飞儻相憶，祗應遙望西南天。"]', '诗', 'shi', '', NULL, '東平蓬萊驛夜宴平盧楊判官醉後贈別姚太守置酒留宴 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cd0788b-f590-4c33-afb9-22ca04af73e0', '同岑郎中屯田韋員外花樹歌', '同岑郎中屯田韋員外花樹歌', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["東風動地吹花發，渭城桃李千樹雪。","芳菲可愛不可留，武陵歸客心欲絕。","金華省郎惜佳辰，秪持棣蕚照青春。","君家自是成蹊處，況有庭花作主人。"]', '["东风动地吹花發，渭城桃李千樹雪。","芳菲可愛不可留，武陵归客心欲絕。","金华省郎惜佳辰，秪持棣蕚照青春。","君家自是成蹊处，況有庭花作主人。"]', '诗', 'shi', '', NULL, '同岑郎中屯田韋員外花樹歌 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76c709fa-28a8-4635-a6c8-997b24e696fb', '和李尚書畫射虎圖歌', '和李尚书畫射虎圖歌', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["飢虎呀呀立當路，萬夫震恐百獸怒。","彤弓金鏃當者誰，鳴鞭飛控流星馳。","居然畫中見真態，若務除惡不顧私。","時和年豐五兵已，白額未誅壯士耻。","分銖遠邇懸彀中，不中不發思全功。","捨矢如破石可裂，應弦盡敵山爲空。","殺氣滿堂觀者駭，颯若崖谷生長風。","精微入神在毫末，作繢造物可同功。","方叔秉鉞受命新，丹青起予氣益振。","底綏靜難巧可擬，嗟歎不足聲成文。","他時代天育萬物，亦以此道安斯民。"]', '["飢虎呀呀立當路，万夫震恐百獸怒。","彤弓金鏃當者誰，鳴鞭飞控流星驰。","居然畫中见真態，若務除惡不顧私。","时和年豐五兵已，白額未誅壯士耻。","分銖远邇懸彀中，不中不發思全功。","捨矢如破石可裂，應弦尽敵山爲空。","殺氣满堂观者駭，颯若崖谷生长风。","精微入神在毫末，作繢造物可同功。","方叔秉鉞受命新，丹青起予氣益振。","底綏静难巧可擬，嗟歎不足声成文。","他时代天育万物，亦以此道安斯民。"]', '诗', 'shi', '', NULL, '和李尚書畫射虎圖歌 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99e0eca3-2edb-4967-b656-f055cf439e8a', '和贈遠', '和贈远', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["憶得去年春風至，中庭桃李映瑣窗。","美人挾瑟對芳樹，玉顏亭亭與花雙。","今年新花如舊時，去年美人不在茲。","借問離居恨深淺，祗應獨有庭花知。"]', '["憶得去年春风至，中庭桃李映瑣窗。","美人挾瑟对芳樹，玉顏亭亭與花雙。","今年新花如旧时，去年美人不在茲。","借问離居恨深淺，祗應独有庭花知。"]', '诗', 'shi', '', NULL, '和贈遠 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b85c4c4a-f589-49a8-a7cb-c31467ce625c', '和題藤架', '和題藤架', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["䔿䔿葉成幄，璀璀花落架。","花前離心苦，愁至無日夜。","人去藤花千里強，藤花無主爲誰芳。","相思歷亂何由盡，春日迢迢如線長。"]', '["䔿䔿葉成幄，璀璀花落架。","花前離心苦，愁至無日夜。","人去藤花千里強，藤花無主爲誰芳。","相思歷亂何由尽，春日迢迢如線长。"]', '诗', 'shi', '', NULL, '和題藤架 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3060b96f-1373-4ab8-b5cd-e602ce9b4151', '江上代書寄裴使君', '江上代书寄裴使君', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["何地離念劇，江臯風雪時。","艱難傷遠道，老大怯前期。","疇昔行藏計，祗將力命推。","能令書信數，猶足緩相思。"]', '["何地離念劇，江臯风雪时。","艱难傷远道，老大怯前期。","疇昔行藏計，祗將力命推。","能令书信數，猶足緩相思。"]', '诗', 'shi', '', NULL, '江上代書寄裴使君 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a6006f8-1767-4d21-b631-fdeb28721ec8', '詣開悟禪師問心法次第寄韓郎中', '詣开悟禪師问心法次第寄韓郎中', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["障深聞道晚，根鈍出塵難。","濁劫相從慣，迷途自謂安。","得知身垢妄，始喜額珠完。","欲識真如理，君嘗法味看。"]', '["障深闻道晚，根鈍出塵难。","濁劫相從慣，迷途自謂安。","得知身垢妄，始喜額珠完。","欲識真如理，君嘗法味看。"]', '诗', 'shi', '', NULL, '詣開悟禪師問心法次第寄韓郎中 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58fbfdb2-6dc9-4ba8-ba75-827a3c78c4d3', '登後湖傷春懷京師故舊', '登後湖傷春懷京師故旧', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["昨日看搖落，驚秋方怨咨。","幾經開口笑，復及看花時。","世事空名束，生涯素髮知。","山山春草滿，何處不相思。"]', '["昨日看搖落，驚秋方怨咨。","幾經开口笑，复及看花时。","世事空名束，生涯素髮知。","山山春草满，何处不相思。"]', '诗', 'shi', '', NULL, '登後湖傷春懷京師故舊 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c80e4104-8e5e-491f-97d2-9beb82d5802c', '暮春於山谷寺上方遇恩命加官賜服詶皇甫侍御見賀之作', '暮春於山谷寺上方遇恩命加官賜服詶皇甫侍御见賀之作', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["天書到法堂，朽質被榮光。","自笑無功德，殊恩謬激揚。","還登建禮署，猶忝會稽章。","佳句慙相及，稱仁豈易當。"]', '["天书到法堂，朽質被榮光。","自笑無功德，殊恩謬激揚。","還登建禮署，猶忝會稽章。","佳句慙相及，稱仁豈易當。"]', '诗', 'shi', '', NULL, '暮春於山谷寺上方遇恩命加官賜服詶皇甫侍御見賀之作 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e502aa21-de65-4abd-99ab-ba4773dfbf7e', '荅李滁州題庭前石竹花見寄', '荅李滁州題庭前石竹花见寄', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["殷疑曙霞染，巧類匣刀裁。","不怕南風熱，能迎小暑開。","遊蜂憐色好，思婦感年催。","覽贈添離恨，愁腸日幾廻。"]', '["殷疑曙霞染，巧類匣刀裁。","不怕南风熱，能迎小暑开。","游蜂怜色好，思婦感年催。","覽贈添離恨，愁腸日幾廻。"]', '诗', 'shi', '', NULL, '荅李滁州題庭前石竹花見寄 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('007e3153-8214-4631-a64e-49c8f2e00a6b', '得李滁州書以玉潭莊見託因書春思以詩代荅', '得李滁州书以玉潭莊见託因书春思以诗代荅', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["春物行將老，懷君意詎堪。","朱顏因酒強，白髮對花慙。","日日思瓊樹，書書話玉潭。","知同百口累，曷日辦抽簪。"]', '["春物行將老，懷君意詎堪。","朱顏因酒強，白髮对花慙。","日日思瓊樹，书书話玉潭。","知同百口累，曷日辦抽簪。"]', '诗', 'shi', '', NULL, '得李滁州書以玉潭莊見託因書春思以詩代荅 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c35c1f4-6edd-4626-976d-59bc295d93e3', '荅李滁州憶玉潭新居見寄', '荅李滁州憶玉潭新居见寄', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["從來招隱地，未有剖符人。","山水能成癖，巢夷擬獨親。","猪肝無足累，馬首敢辭勤。","掃灑潭中月，他時望德鄰。"]', '["從来招隐地，未有剖符人。","山水能成癖，巢夷擬独親。","猪肝無足累，马首敢辞勤。","掃灑潭中月，他时望德鄰。"]', '诗', 'shi', '', NULL, '荅李滁州憶玉潭新居見寄 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fe49699-594f-4b6e-807f-020a98bc4eff', '將赴京答李紓贈別', '將赴京答李紓贈別', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["膠漆常投分，荆蠻各倦遊。","帝鄉今獨往，溝水便分流。","甘作遠行客，深慙不繫舟。","思君帶將緩，豈直日三秋。"]', '["膠漆常投分，荆蠻各倦游。","帝乡今独往，溝水便分流。","甘作远行客，深慙不繫舟。","思君带將緩，豈直日三秋。"]', '诗', 'shi', '', NULL, '將赴京答李紓贈別 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff9ada12-e2d1-4ac7-87b0-faf835b9b730', '和張大夫秋日有懷呈院中諸公', '和張大夫秋日有懷呈院中諸公', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["至公無暇日，高閣閉秋天。","肘印拘王事，籬花思長年。","績成心不有，慮澹物猶牽。","竊效泉魚躍，因聞郢曲妍。"]', '["至公無暇日，高閣閉秋天。","肘印拘王事，籬花思长年。","績成心不有，慮澹物猶牽。","竊效泉鱼躍，因闻郢曲妍。"]', '诗', 'shi', '', NULL, '和張大夫秋日有懷呈院中諸公 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e706dda5-841a-4397-a760-5ad1edaee1a2', '和大夫秋夜書情即事', '和大夫秋夜书情即事', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["上略當分閫，高情善閉關。","忘機羣動息，無戰五兵閑。","鈴閣風傳漏，書窗月滿山。","方知秋興作，非惜二毛斑。"]', '["上略當分閫，高情善閉关。","忘機羣动息，無戰五兵闲。","鈴閣风傳漏，书窗月满山。","方知秋兴作，非惜二毛斑。"]', '诗', 'shi', '', NULL, '和大夫秋夜書情即事 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd1a92df-e874-48ad-ae81-3ba96fa08dac', '送虢州王錄事之任', '送虢州王錄事之任', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["謂子文章達，當年羽翼高。","一經俄白首，三命尚青袍。","未遇須藏器，安卑莫告勞。","盤根儻相值，試用發硎刀。"]', '["謂子文章達，當年羽翼高。","一經俄白首，三命尚青袍。","未遇須藏器，安卑莫告勞。","盤根儻相值，試用發硎刀。"]', '诗', 'shi', '', NULL, '送虢州王錄事之任 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('415110b9-d043-4d70-aaaa-c738d2e79f2d', '送長孫將軍拜歙州之任', '送长孫將軍拜歙州之任', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["臨難敢橫行，遭時取盛名。","五兵常典校，四十又專城。","浪逐樓船破，風從虎竹生。","島夷今可料，繫頸有長纓。"]', '["臨难敢橫行，遭时取盛名。","五兵常典校，四十又專城。","浪逐楼船破，风從虎竹生。","島夷今可料，繫頸有长纓。"]', '诗', 'shi', '', NULL, '送長孫將軍拜歙州之任 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8fbb630-1b97-47a2-951e-0e11e8ce2758', '送何員外使湖南', '送何員外使湖南', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["夙昔皆黃綬，差池復瑣闈。","上田無晚熟，逸翮果先飛。","前路舟休繫，故山雲不歸。","王程儻未復，莫遣鯉書稀。"]', '["夙昔皆黄綬，差池复瑣闈。","上田無晚熟，逸翮果先飞。","前路舟休繫，故山云不归。","王程儻未复，莫遣鯉书稀。"]', '诗', 'shi', '', NULL, '送何員外使湖南 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfbedb71-d49c-4452-9863-177aca5e81ae', '送江陵全少卿赴府任', '送江陵全少卿赴府任', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["冢司方眘選，劇縣得英髦。","固是攀雲漸，何嗟趨府勞。","楚山迎驛路，漢水漲秋濤。","騫翥方茲始，看君六翮高。"]', '["冢司方眘選，劇縣得英髦。","固是攀云漸，何嗟趨府勞。","楚山迎驛路，漢水漲秋濤。","騫翥方茲始，看君六翮高。"]', '诗', 'shi', '', NULL, '送江陵全少卿赴府任 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb747f2c-dbcc-43ec-a73e-e3ee70eaeaca', '送虞秀才擢第歸長沙', '送虞秀才擢第归长沙', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["充賦名今遂，安親事不違。","甲科文比玉，歸路錦爲衣。","海運同鵾化，風帆若鳥飛。","知君到三逕，松菊有光輝。"]', '["充賦名今遂，安親事不違。","甲科文比玉，归路錦爲衣。","海運同鵾化，风帆若鸟飞。","知君到三逕，松菊有光輝。"]', '诗', 'shi', '', NULL, '送虞秀才擢第歸長沙 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a39a30e-316a-4cc7-bc7e-857aabde0eb4', '送陽翟張主簿之任', '送陽翟張主簿之任', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["舊聞陽翟縣，西接鳳高山。","作吏同山隱，知君處劇閑。","少年當効用，遠道豈辭艱。","遲子揚名後，方期綵服還。"]', '["旧闻陽翟縣，西接鳳高山。","作吏同山隐，知君处劇闲。","少年當効用，远道豈辞艱。","遲子揚名後，方期綵服還。"]', '诗', 'shi', '', NULL, '送陽翟張主簿之任 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ec9dd01-04f7-4713-93f4-5113ff4a5d9f', '送游員外赴淮西', '送游員外赴淮西', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["多君有奇略，投筆佐元戎。","已佩郎官印，兼乘御史驄。","使星隨驛騎，歸路有秋風。","莫道無書札，他年懷袖空。"]', '["多君有奇略，投笔佐元戎。","已佩郎官印，兼乘御史驄。","使星隨驛騎，归路有秋风。","莫道無书札，他年懷袖空。"]', '诗', 'shi', '', NULL, '送游員外赴淮西 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3444a2ca-ee8d-4537-a1af-d0060bb80ea1', '送馬鄭州', '送马鄭州', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["使君朱兩轓，春日整東轅。","芳草成臯路，青山涼水源。","勉修循吏跡，以謝主人恩。","當使仁風動，遙聽輿頌諠。"]', '["使君朱兩轓，春日整东轅。","芳草成臯路，青山涼水源。","勉修循吏跡，以謝主人恩。","當使仁风动，遙听輿頌諠。"]', '诗', 'shi', '', NULL, '送馬鄭州 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('270864c0-5af6-4afc-ad50-a8352f533854', '送義烏韋明府', '送義烏韋明府', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["妙年能致身，陳力復安親。","不憚關山遠，寧辭簿領勤。","過江雲滿路，到縣海爲鄰。","每歎違心賞，吳門正早春。"]', '["妙年能致身，陳力复安親。","不憚关山远，寧辞簿領勤。","過江云满路，到縣海爲鄰。","每歎違心賞，吳门正早春。"]', '诗', 'shi', '', NULL, '送義烏韋明府 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8258bd2-118c-4db1-8ee8-02ba00bf5430', '送陳王府張長史還京', '送陳王府張长史還京', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["論齒弟兄列，爲邦前後差。","十年方一見，此別復何嗟。","極目故關道，傷心南浦花。","少時相憶處，招手望行車。"]', '["論齒弟兄列，爲邦前後差。","十年方一见，此別复何嗟。","極目故关道，傷心南浦花。","少时相憶处，招手望行车。"]', '诗', 'shi', '', NULL, '送陳王府張長史還京 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e761c18-6176-4adc-b1dc-42d297995958', '水西館泛舟送王員外', '水西館泛舟送王員外', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["單醪敢獻酢，曲沼荷經過。","泛覽親魚鳥，夤緣涉芰荷。","劇談增惠愛，美景借清和。","明日汀洲草，依依奈別何。"]', '["單醪敢獻酢，曲沼荷經過。","泛覽親鱼鸟，夤緣涉芰荷。","劇談增惠愛，美景借清和。","明日汀洲草，依依奈別何。"]', '诗', 'shi', '', NULL, '水西館泛舟送王員外 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42f61ca0-8a41-470d-8fe8-d5de63db5ac0', '李卿東池夜宴得池字', '李卿东池夜宴得池字', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["政成機不擾，心愜宴忘疲。","去燭延高月，傾罍就小池。","舞盤廻雪動，弦奏躍魚隨。","自是山公興，誰令下士知。"]', '["政成機不擾，心愜宴忘疲。","去燭延高月，傾罍就小池。","舞盤廻雪动，弦奏躍鱼隨。","自是山公兴，誰令下士知。"]', '诗', 'shi', '', NULL, '李卿東池夜宴得池字 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a41dbd6-e1d7-462d-9e71-8259ec5e7061', '九月九日李蘇州東樓宴', '九月九日李蘇州东楼宴', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["是菊花開日，當君乘興秋。","風前孟嘉帽，月下庾公樓。","酒解留征客，歌能破別愁。","醉歸無以贈，祗奉萬年酬。"]', '["是菊花开日，當君乘兴秋。","风前孟嘉帽，月下庾公楼。","酒解留征客，歌能破別愁。","醉归無以贈，祗奉万年酬。"]', '诗', 'shi', '', NULL, '九月九日李蘇州東樓宴 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3db26dd-97dc-480a-a07f-521d91c2c72d', '蕭文學山池宴集', '蕭文学山池宴集', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["檀欒千畝綠，知是辟疆園。","遠岫當庭戶，諸花覆水源。","主人邀盡醉，林鳥助狂言。","莫問愁多少，今皆付酒樽。"]', '["檀欒千畝綠，知是辟疆园。","远岫當庭戶，諸花覆水源。","主人邀尽醉，林鸟助狂言。","莫问愁多少，今皆付酒樽。"]', '诗', 'shi', '', NULL, '蕭文學山池宴集 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dbc7bc5-67e6-4648-b376-b0bd6f809b98', '與韓侍御同尋李七舍人不遇題壁留贈', '與韓侍御同尋李七舍人不遇題壁留贈', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["三徑何寂寂，主人山上山。","亭空簷月在，水落釣磯閑。","藥院雞犬靜，酒壚苔蘚班。","知君少機事，當待暮雲還。"]', '["三徑何寂寂，主人山上山。","亭空簷月在，水落釣磯闲。","藥院雞犬静，酒壚苔蘚班。","知君少機事，當待暮云還。"]', '诗', 'shi', '', NULL, '與韓侍御同尋李七舍人不遇題壁留贈 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29caf0d7-6d84-4b60-975d-d2acce3b89e4', '喜辱韓十四郎中書兼封近詩示代書題贈', '喜辱韓十四郎中书兼封近诗示代书題贈', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["各牽于役間遊遨，獨坐相思正鬱陶。","長跪讀書心蹔緩，短章投我曲何高。","宦情緣木知非願，王事敦人敢告勞。","所歎在官成遠別，徒言岏水纔容舠。"]', '["各牽于役间游遨，独坐相思正鬱陶。","长跪读书心蹔緩，短章投我曲何高。","宦情緣木知非願，王事敦人敢告勞。","所歎在官成远別，徒言岏水纔容舠。"]', '诗', 'shi', '', NULL, '喜辱韓十四郎中書兼封近詩示代書題贈 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cb201dc-c6ee-45c2-a3e8-55f422fe789b', '早發龍沮館舟中寄東海徐司倉鄭司戶', '早發龙沮館舟中寄东海徐司倉鄭司戶', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["沙禽相呼曙色分，漁浦鳴桹十里聞。","正當秋風渡楚水，況值遠道傷離羣。","津頭却望後湖岸，別處已隔東山雲。","停艫目送北歸翼，惜無瑤華持寄君。"]', '["沙禽相呼曙色分，漁浦鳴桹十里闻。","正當秋风渡楚水，況值远道傷離羣。","津头却望後湖岸，別处已隔东山云。","停艫目送北归翼，惜無瑤华持寄君。"]', '诗', 'shi', '', NULL, '早發龍沮館舟中寄東海徐司倉鄭司戶 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d26522-f5d4-402c-9be6-2d9019d4f1a2', '詶常郿縣見贈', '詶常郿縣见贈', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["愛君修政若修身，鰥寡來歸乳雉馴。","堂上五弦銷暇日，邑中千室有陽春。","謂乘鳧舄朝天子，却愧猪肝累主人。","辭後讀君懷縣作，定知三歲字猶新。"]', '["愛君修政若修身，鰥寡来归乳雉馴。","堂上五弦銷暇日，邑中千室有陽春。","謂乘鳧舄朝天子，却愧猪肝累主人。","辞後读君懷縣作，定知三歲字猶新。"]', '诗', 'shi', '', NULL, '詶常郿縣見贈 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('065d04e0-474e-41be-8f82-e5e47f41112d', '登山谷寺上方答皇甫侍御臥疾闕陪車騎之後', '登山谷寺上方答皇甫侍御臥疾闕陪车騎之後', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["梵宮香閣攀霞上，天柱孤峯指掌看。","漢主馬蹤成蔓草，法王身相示空棺。","雲扶踴塔青霄庳，松蔭禪庭白日寒。","不見戴逵心莫展，賴將新贈比琅玕。"]', '["梵宮香閣攀霞上，天柱孤峯指掌看。","漢主马蹤成蔓草，法王身相示空棺。","云扶踴塔青霄庳，松蔭禪庭白日寒。","不见戴逵心莫展，賴將新贈比琅玕。"]', '诗', 'shi', '', NULL, '登山谷寺上方答皇甫侍御臥疾闕陪車騎之後 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6827814b-c6e3-4c66-884f-42d714338fa1', '答皇甫十六侍御北歸留別作', '答皇甫十六侍御北归留別作', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["正當楚客傷春地，豈是騷人道別時。","俱徇空名嗟欲老，況將行役料前期。","勞生多故應同病，羸馬單車莫自悲。","明日相望隔雲水，解顔唯有袖中詩。"]', '["正當楚客傷春地，豈是騷人道別时。","俱徇空名嗟欲老，況將行役料前期。","勞生多故應同病，羸马單车莫自悲。","明日相望隔云水，解顔唯有袖中诗。"]', '诗', 'shi', '', NULL, '答皇甫十六侍御北歸留別作 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abf81fb1-69da-456b-b5db-b2048c8a2868', '答李滁州見寄', '答李滁州见寄', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["相逢遽歎別離牽，三見江臯惠草鮮。","白髮俱生歡未再，滄州獨往意何堅。","愁看郡內花將歇，忍過山中月屢圓。","終日望君休汝騎，愧無堪報起予篇。"]', '["相逢遽歎別離牽，三见江臯惠草鲜。","白髮俱生歡未再，滄州独往意何堅。","愁看郡內花將歇，忍過山中月屢圓。","終日望君休汝騎，愧無堪報起予篇。"]', '诗', 'shi', '', NULL, '答李滁州見寄 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfaaaf11-9ead-4921-a71e-1f60be94af03', '得柳員外書封寄近詩書中兼報新主行營兵馬因代書戲答', '得柳員外书封寄近诗书中兼報新主行營兵马因代书戲答', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["郎官作掾心非好，儒服臨戎政已聞。","說劒嘗宗漆園吏，戒嚴應笑棘門軍。","遙知抵掌論皇道，時復吟詩向白雲。","百越待君言即敘，相思不敢愴離羣。"]', '["郎官作掾心非好，儒服臨戎政已闻。","说劒嘗宗漆园吏，戒嚴應笑棘门軍。","遙知抵掌論皇道，时复吟诗向白云。","百越待君言即敘，相思不敢愴離羣。"]', '诗', 'shi', '', NULL, '得柳員外書封寄近詩書中兼報新主行營兵馬因代書戲答 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b29732f-3ca8-45c3-a894-c1caaa21622e', '同皇甫侍御齋中春望見示之作', '同皇甫侍御斋中春望见示之作', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["望遠思歸心易傷，況將衰鬢偶年光。","時攀芳樹愁花盡，晝掩高齋厭日長。","甘比流波辭舊浦，忍看新草遍橫塘。","因君贈我江楓詠，春思如今未易量。"]', '["望远思归心易傷，況將衰鬢偶年光。","时攀芳樹愁花尽，晝掩高斋厭日长。","甘比流波辞旧浦，忍看新草遍橫塘。","因君贈我江楓詠，春思如今未易量。"]', '诗', 'shi', '', NULL, '同皇甫侍御齋中春望見示之作 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9f0c9ff-9301-4ad3-99f5-7283edd3aa6d', '傷春贈遠', '傷春贈远', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["去水流年日並馳，年光客思兩相隨。","咨嗟斑鬢今承弁，慙愧新荷又發池。","楊柳逶迤愁遠道，鷓鴣啁哳怨南枝。","憶君何啻同瓊樹，但向春風送別離。"]', '["去水流年日並驰，年光客思兩相隨。","咨嗟斑鬢今承弁，慙愧新荷又發池。","楊柳逶迤愁远道，鷓鴣啁哳怨南枝。","憶君何啻同瓊樹，但向春风送別離。"]', '诗', 'shi', '', NULL, '傷春贈遠 獨孤及 shi');
